python3 << 'PY'
import json
with open('/workspace/contracts/openapi.contract.json') as f:
    c = json.load(f)
def resolve(ref, depth=0):
    if depth>3: return ref
    if isinstance(ref, dict):
        if '$ref' in ref:
            name = ref['$ref'].split('/')[-1]
            return {name: resolve(c['components']['schemas'].get(name,{}), depth+1)}
        out = {}
        for k,v in ref.items():
            if k in ('description','example','format','minLength','maxLength','minimum','maximum','minItems','default'):
                continue
            out[k] = resolve(v, depth+1)
        return out
    if isinstance(ref, list):
        return [resolve(x, depth) for x in ref]
    return ref
for p, methods in sorted(c['paths'].items()):
    for m, op in methods.items():
        if m not in ('get','post','put','patch','delete'): continue
        print('='*80)
        print(f"{m.upper()} {p} -> {op.get('operationId')}")
        print(f"summary: {op.get('summary','')}")
        print(f"tags: {op.get('tags')}")
        if 'parameters' in op:
            print('params:', json.dumps(op['parameters'], indent=2)[:800])
        if 'requestBody' in op:
            rb = op['requestBody']
            content = rb.get('content',{}).get('application/json',{})
            schema = content.get('schema',{})
            print('REQUEST:', json.dumps(resolve(schema), indent=2)[:3000])
        for code, resp in sorted(op.get('responses',{}).items()):
            content = resp.get('content',{}).get('application/json',{})
            schema = content.get('schema',{})
            print(f'ReSPONSE {code}: {resp.get("description","")}')
            if schema:
                print(json.dumps(resolve(schema), indent=2)[:2500])
        print()
