python3 << 'PY'
import json
with open('/workspace/contracts/openapi.contract.json') as f:
    c = json.load(f)

# Save condensed request/response required fields for each op
ops = []
for p, methods in sorted(c['paths'].items()):
    for m, op in methods.items():
        if m not in ('get','post','put','patch','delete'): continue
        entry = {'method': m.upper(), 'path': p, 'operationId': op.get('operationId')}
        if 'requestBody' in op:
            schema = op['requestBody']['content']['application/json']['schema']
            entry['req_required'] = schema.get('required', [])
            entry['req_props'] = list(schema.get('properties', {}).keys())
        resps = {}
        for code, resp in op.get('responses', {}).items():
            content = resp.get('content', {}).get('application/json', {})
            schema = content.get('schema', {})
            if 'properties' in schema and 'data' in schema.get('properties', {}):
                data = schema['properties']['data']
                if '$ref' in data:
                    ref = data['$ref'].split('/')[-1]
                    ds = c['components']['schemas'][ref]
                    resps[code] = {'ref': ref, 'required': ds.get('required'), 'props': list(ds.get('properties',{}).keys())}
                else:
                    resps[code] = {'required': data.get('required'), 'props': list(data.get('properties',{}).keys())}
            elif schema:
                resps[code] = {'required': schema.get('required'), 'props': list(schema.get('properties',{}).keys()) if 'properties' in schema else schema}
        entry['responses'] = resps
        ops.append(entry)

with open('/tmp/ops_summary.json','w') as f:
    json.dump(ops, f, indent=2)
print(len(ops), 'ops')

# Also dump full create-collection-request and other key ones
keys = ['create_collection_request','create_user','create_location','create_connection','create_sample_type',
        'list_role_work','read_ui_bootstrap','read_operations_state','read_journey_plan','read_sample_state',
        'select_active_role','ingest_presealed_sample','confirm_handoff','initiate_handoff',
        'configure_capacity','report_disruption','reroute_journey','split_journey','merge_journeys',
        'edit_active_plan','search_audit_trail','stream_realtime_events','read_serviceability_snapshot',
        'set_worker_availability','decline_assignment','collect_and_seal_sample','confirm_laboratory_receipt',
        'record_laboratory_exception','record_handling_checkpoint','record_worker_location','update_assignment_progress',
        'set_location_status','set_location_function_status','set_connection_status','configure_laboratory_acceptance',
        'read_sample_lifecycle','read_user']
for p, methods in c['paths'].items():
    for m, op in methods.items():
        if op.get('operationId') in keys:
            print('\n###', op['operationId'], m.upper(), p)
            if 'requestBody' in op:
                print('REQ:', json.dumps(op['requestBody']['content']['application/json']['schema'], indent=2)[:2000])
            for code in ['200','201']:
                if code in op.get('responses',{}):
                    s = op['responses'][code].get('content',{}).get('application/json',{}).get('schema',{})
                    print(f'OK {code}:', json.dumps(s, indent=2)[:2500])
