python3 -c '
import json
with open("/workspace/contracts/openapi.contract.json") as f:
    c = json.load(f)
keys = ["create_collection_request","create_user","create_location","create_connection","create_sample_type","list_role_work","read_ui_bootstrap","read_operations_state","read_journey_plan","read_sample_state","select_active_role","ingest_presealed_sample","confirm_handoff","initiate_handoff","configure_capacity","report_disruption","reroute_journey","split_journey","merge_journeys","edit_active_plan","search_audit_trail","stream_realtime_events","read_serviceability_snapshot","set_worker_availability","decline_assignment","collect_and_seal_sample","confirm_laboratory_receipt","record_laboratory_exception","record_handling_checkpoint","record_worker_location","update_assignment_progress","set_location_status","set_location_function_status","set_connection_status","configure_laboratory_acceptance","read_sample_lifecycle","read_user"]
for p, methods in c["paths"].items():
    for m, op in methods.items():
        if op.get("operationId") in keys:
            print("\n###", op["operationId"], m.upper(), p)
            if "requestBody" in op:
                print("REQ:", json.dumps(op["requestBody"]["content"]["application/json"]["schema"], indent=2)[:2500])
            for code in ["200","201"]:
                if code in op.get("responses",{}):
                    s = op["responses"][code].get("content",{}).get("application/json",{}).get("schema",{})
                    print("OK %s:" % code, json.dumps(s, indent=2)[:3000])
' > /tmp/ops_detail.txt 2>&1 && wc -l /tmp/ops_detail.txt && head -c 50000 /tmp/ops_detail.txt

