action.file_text:
package app

import (
	"os"
	"strings"
)

type Config struct {
	Addr            string
	DatabaseURL     string
	MongoURI        string
	AdminUsername   string
	AdminPassword   string
	StaticDir       string
	MapAssetsDir    string
	JWTSecret       string
	LocationStaleSec int
	OfferTimeoutSec  int
}

func LoadConfig() Config {
	addr := env("ADDR", ":8080")
	if !strings.Contains(addr, ":") {
		addr = ":" + addr
	}
	return Config{
		Addr:             addr,
		DatabaseURL:      env("DATABASE_URL", "postgresql://arena:arena@127.0.0.1:5432/arena?sslmode=disable"),
		MongoURI:         env("MONGODB_URI", "mongodb://127.0.0.1:27017/arena"),
		AdminUsername:    env("ADMIN_USERNAME", "admin"),
		AdminPassword:    env("ADMIN_PASSWORD", "admin"),
		StaticDir:        env("STATIC_DIR", "/workspace/frontend/dist"),
		MapAssetsDir:     env("MAP_ASSETS_DIR", "/opt/arena/map-assets"),
		JWTSecret:        env("JWT_SECRET", "labsample-dev-secret-change-me"),
		LocationStaleSec: 300,
		OfferTimeoutSec:  120,
	}
}

func env(k, def string) string {
	if v := os.Getenv(k); v != "" {
		return v
	}
	return def
}

