func (d *DB) Reset(ctx context.Context) error {
	tables := []string{
		"worker_location_updates", "handling_checkpoints", "disruptions",
		"serviceability_snapshots", "realtime_events", "idempotency_keys",
		"timeline_events", "audit_log", "capacity_reservations", "handoffs",
		"assignments", "journey_stops", "journeys", "samples", "lab_acceptances",
		"connections", "locations", "sample_types", "sessions", "users",
		"network_meta", "meta",
	}
