func MustJSON(v interface{}) []byte {
	b, _ := json.Marshal(v)
	return b
}

func FromJSON[T any](b []byte) T {
	var v T
	_ = json.Unmarshal(b, &v)
	return v
}

func HaversineKm(lat1, lon1, lat2, lon2 float64) float64 {
	const R = 6371.0
	toRad := func(d float64) float64 { return d * math.Pi / 180 }
	dLat := toRad(lat2 - lat1)
	dLon := toRad(lon2 - lon1)
	a := math.Sin(dLat/2)*math.Sin(dLat/2) +
		math.Cos(toRad(lat1))*math.Cos(toRad(lat2))*math.Sin(dLon/2)*math.Sin(dLon/2)
	c := 2 * math.Atan2(math.Sqrt(a), math.Sqrt(1-a))
	return R * c
}

func ContainsStr(ss []string, s string) bool {
	for _, x := range ss {
		if x == s {
			return true
		}
	}
	return false
}

func FormatTime(t time.Time) string {
	if t.IsZero() {
		return ""
	}
	return t.UTC().Format(time.RFC3339Nano)
}

func FormatTimePtr(t *time.Time) interface{} {
	if t == nil || t.IsZero() {
		return nil
	}
	return t.UTC().Format(time.RFC3339Nano)
}

func RoleOK(role string) bool {
	switch role {
	case "administrator", "dispatcher", "requester", "collection_professional",
		"delivery_partner", "node_handler", "laboratory_team":
		return true
	}
	return false
}

func DefaultActiveRole(roles []string) string {
	if len(roles) == 1 {
		return roles[0]
	}
	// Prefer administrator if present for bootstrap convenience when single-purpose
	if len(roles) == 0 {
		return ""
	}
	return ""
}

