package app

import (
	"context"
	"log"
	"net/http"
	"sync"
	"time"

	"labsample/internal/auth"
	"labsample/internal/db"
	"labsample/internal/models"
)

type App struct {
	Cfg    Config
	DB     *db.DB
	mu     sync.Mutex
	subs   map[chan models.RealtimeEvent]struct{}
	ready  bool
}

func New(cfg Config) (*App, error) {
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	d, err := db.Connect(ctx, cfg.DatabaseURL, cfg.MongoURI)
	if err != nil {
		return nil, err
	}
	a := &App{Cfg: cfg, DB: d, subs: map[chan models.RealtimeEvent]struct{}{}}
	return a, nil
}

func (a *App) Close() {
	a.DB.Close()
}

func (a *App) Bootstrap(ctx context.Context) error {
	if err := a.DB.Migrate(ctx); err != nil {
		return err
	}
	if err := a.ensureAdmin(ctx); err != nil {
		return err
	}
	if err := a.ensureDefaultSampleTypes(ctx); err != nil {
		return err
	}
	if err := a.ensureServiceabilitySnapshot(ctx); err != nil {
		return err
	}
	a.ready = true
	go a.offerExpiryLoop()
	log.Printf("bootstrap complete")
	return nil
}

func (a *App) ensureAdmin(ctx context.Context) error {
	var n int
	err := a.DB.Pool.QueryRow(ctx, `SELECT COUNT(*) FROM users`).Scan(&n)
	if err != nil {
		return err
	}
	if n > 0 {
		return nil
	}
	hash, err := auth.HashPassword(a.Cfg.AdminPassword)
	if err != nil {
		return err
	}
	id := NewID()
	_, err = a.DB.Pool.Exec(ctx, `
		INSERT INTO users (id, username, password_hash, full_name, roles, qualifications, certifications, active)
		VALUES ($1,$2,$3,$4,$5::jsonb,$6::jsonb,$7::jsonb,true)`,
		id, a.Cfg.AdminUsername, hash, "Administrator",
		MustJSON([]string{models.RoleAdministrator}),
		MustJSON([]string{}),
		MustJSON([]models.Certification{}),
	)
	return err
}

func (a *App) ensureDefaultSampleTypes(ctx context.Context) error {
	var n int
	_ = a.DB.Pool.QueryRow(ctx, `SELECT COUNT(*) FROM sample_types`).Scan(&n)
	if n > 0 {
		return nil
	}
	defaults := []struct {
		name, qual, container string
		minT, maxT            float64
		cooled, batch         bool
	}{
		{"Amber", "Amber", "standard", 2, 25, false, true},
		{"Indigo", "Indigo", "standard", 2, 25, false, true},
		{"Frost", "Frost", "cooled", 2, 8, true, true},
		{"Pulse", "Pulse", "standard", 2, 25, false, false},
	}
	// Create first without incompatibilities, then set Indigo incompatible with Amber
	ids := map[string]string{}
	for _, d := range defaults {
		id := NewID()
		ids[d.name] = id
		_, err := a.DB.Pool.Exec(ctx, `
			INSERT INTO sample_types (id, name, qualified_collector_required, required_qualification,
				container_type, temperature_min_c, temperature_max_c, incompatible_sample_types,
				requires_cooled_route, batching_allowed)
			VALUES ($1,$2,true,$3,$4,$5,$6,'[]'::jsonb,$7,$8)`,
			id, d.name, d.qual, d.container, d.minT, d.maxT, d.cooled, d.batch)
		if err != nil {
			return err
		}
	}
	// Indigo must not share with Amber
	if amber, ok := ids["Amber"]; ok {
		if indigo, ok2 := ids["Indigo"]; ok2 {
			_, _ = a.DB.Pool.Exec(ctx, `
				UPDATE sample_types SET incompatible_sample_types = $1::jsonb WHERE id = $2`,
				MustJSON([]string{amber}), indigo)
			_, _ = a.DB.Pool.Exec(ctx, `
				UPDATE sample_types SET incompatible_sample_types = $1::jsonb WHERE id = $2`,
				MustJSON([]string{indigo}), amber)
		}
	}
	return nil
}

func (a *App) ensureServiceabilitySnapshot(ctx context.Context) error {
	var ver int
	err := a.DB.Pool.QueryRow(ctx, `SELECT current_serviceability_version FROM network_meta WHERE id=1`).Scan(&ver)
	if err != nil {
		return err
	}
	if ver == 0 {
		return a.recomputeServiceability(ctx)
	}
	return nil
}

func (a *App) offerExpiryLoop() {
	ticker := time.NewTicker(5 * time.Second)
	defer ticker.Stop()
	for range ticker.C {
		ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
		_ = a.expireOffers(ctx)
		cancel()
	}
}

func (a *App) IsReady() bool {
	if !a.ready {
		return false
	}
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()
	if err := a.DB.Pool.Ping(ctx); err != nil {
		return false
	}
	if err := a.DB.Mongo.Ping(ctx, nil); err != nil {
		return false
	}
	return true
}

func (a *App) Router() http.Handler {
	mux := http.NewServeMux()
	a.registerRoutes(mux)
	return a.withMiddleware(mux)
}

