action.file_text:
package app

import (
	"context"
	"encoding/json"
	"time"

	"github.com/jackc/pgx/v5"
	"labsample/internal/auth"
	"labsample/internal/httpapi"
	"labsample/internal/models"
)

func (a *App) getUser(ctx context.Context, id string) (*models.User, error) {
	u := &models.User{}
	var roles, quals, certs []byte
	var assigned *string
	var penalty *time.Time
	var lat, lon *float64
	var locAt *time.Time
	err := a.DB.Pool.QueryRow(ctx, `
		SELECT id, username, password_hash, email, full_name, phone, roles, qualifications, certifications,
			active, assigned_location_id, available, capacity_units, decline_penalty_until,
			latest_lat, latest_lon, location_recorded_at, created_at
		FROM users WHERE id=$1`, id).Scan(
		&u.ID, &u.Username, &u.PasswordHash, &u.Email, &u.FullName, &u.Phone,
		&roles, &quals, &certs, &u.Active, &assigned, &u.Available, &u.CapacityUnits,
		&penalty, &lat, &lon, &locAt, &u.CreatedAt,
	)
	if err != nil {
		return nil, err
	}
	u.Roles = FromJSON[[]string](roles)
	u.Qualifications = FromJSON[[]string](quals)
	u.Certifications = FromJSON[[]models.Certification](certs)
	u.AssignedLocationID = assigned
	u.DeclinePenaltyUntil = penalty
	u.LatestLat = lat
	u.LatestLon = lon
	u.LocationRecordedAt = locAt
	return u, nil
}

func (a *App) getUserByUsername(ctx context.Context, username string) (*models.User, error) {
	var id string
	err := a.DB.Pool.QueryRow(ctx, `SELECT id FROM users WHERE username=$1`, username).Scan(&id)
	if err != nil {
		return nil, err
	}
	return a.getUser(ctx, id)
}

func (a *App) userJSON(u *models.User) map[string]interface{} {
	out := map[string]interface{}{
		"userId":         u.ID,
		"username":       u.Username,
		"roles":          u.Roles,
		"qualifications": u.Qualifications,
		"certifications": certsJSON(u.Certifications),
		"active":         u.Active,
	}
	if u.Email != "" {
		out["email"] = u.Email
	}
	if u.FullName != "" {
		out["fullName"] = u.FullName
	}
	if u.Phone != "" {
		out["phone"] = u.Phone
	}
	return out
}

func certsJSON(cs []models.Certification) []map[string]interface{} {
	out := make([]map[string]interface{}, 0, len(cs))
	for _, c := range cs {
		m := map[string]interface{}{"code": c.Code, "active": c.Active}
		if c.ExpiresAt != nil {
			m["expiresAt"] = FormatTime(*c.ExpiresAt)
		}
		out = append(out, m)
	}
	return out
}

func (a *App) handleAuthenticate(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}
	if err := httpapi.DecodeJSON(r, &req); err != nil {
		httpapi.WriteError(w, err)
		return
	}
	u, err := a.getUserByUsername(r.Context(), req.Username)
	if err != nil || !auth.CheckPassword(u.PasswordHash, req.Password) || !u.Active {
		httpapi.WriteError(w, httpapi.ErrInvalidCredentials)
		a.audit(r.Context(), "", "", "authenticate_user", "user", req.Username, false, map[string]interface{}{"reason": "invalid_credentials"})
		return
	}
	token, err := auth.NewToken()
	if err != nil {
		httpapi.WriteError(w, httpapi.E(500, "internal_error", "token error"))
		return
	}
	active := DefaultActiveRole(u.Roles)
	exp := auth.SessionExpiry()
	_, err = a.DB.Pool.Exec(r.Context(), `
		INSERT INTO sessions (token, user_id, active_role, roles, expires_at) VALUES ($1,$2,$3,$4::jsonb,$5)`,
		token, u.ID, active, MustJSON(u.Roles), exp)
	if err != nil {
		httpapi.WriteError(w, httpapi.E(500, "internal_error", "session error"))
		return
	}
	a.audit(r.Context(), u.ID, active, "authenticate_user", "user", u.ID, true, nil)
	httpapi.WriteData(w, 200, map[string]interface{}{
		"sessionToken": token,
		"userId":       u.ID,
		"roles":        u.Roles,
		"activeRole":   active,
	})
}

func (a *App) handleSelectRole(w http.ResponseWriter, r *http.Request) {
	s := SessionFrom(r.Context())
	u := UserFrom(r.Context())
	if s == nil || u == nil {
		httpapi.WriteError(w, httpapi.ErrUnauthorized)
		return
	}
	var req struct {
		Role string `json:"role"`
	}
	if err := httpapi.DecodeJSON(r, &req); err != nil {
		httpapi.WriteError(w, err)
		return
	}
	if !ContainsStr(u.Roles, req.Role) || !RoleOK(req.Role) {
		httpapi.WriteError(w, httpapi.ErrForbidden)
		return
	}
	_, err := a.DB.Pool.Exec(r.Context(), `UPDATE sessions SET active_role=$1 WHERE token=$2`, req.Role, s.Token)
	if err != nil {
		httpapi.WriteError(w, httpapi.E(500, "internal_error", "update failed"))
		return
	}
	a.audit(r.Context(), u.ID, req.Role, "select_active_role", "user", u.ID, true, map[string]interface{}{"role": req.Role})
	httpapi.WriteData(w, 200, map[string]interface{}{
		"activeRole": req.Role,
		"roles":      u.Roles,
	})
}

func (a *App) handleCreateUser(w http.ResponseWriter, r *http.Request) {
	s, _, err := a.requireAdmin(r.Context())
	if err != nil {
		httpapi.WriteError(w, err)
		return
	}
	var req struct {
		Username           string                 `json:"username"`
		InitialPassword    string                 `json:"initialPassword"`
		Email              string                 `json:"email"`
		FullName           string                 `json:"fullName"`
		Phone              string                 `json:"phone"`
		Roles              []string               `json:"roles"`
		Qualifications     []string               `json:"qualifications"`
		Certifications     []models.Certification `json:"certifications"`
		Active             bool                   `json:"active"`
		AssignedLocationID *string                `json:"assignedLocationId"`
	}
	if err := httpapi.DecodeJSON(r, &req); err != nil {
		httpapi.WriteError(w, err)
		return
	}
	if req.Username == "" || req.InitialPassword == "" || len(req.Roles) == 0 {
		httpapi.WriteError(w, httpapi.E(400, "invalid_json", "missing required fields"))
		return
	}
	for _, role := range req.Roles {
		if !RoleOK(role) {
			httpapi.WriteError(w, httpapi.E(400, "invalid_json", "invalid role"))
			return
		}
	}
	if req.Qualifications == nil {
		req.Qualifications = []string{}
	}
	if req.Certifications == nil {
		req.Certifications = []models.Certification{}
	}
	for _, c := range req.Certifications {
		if c.Code == "" {
			httpapi.WriteError(w, httpapi.E(400, "invalid_certification", "invalid certification"))
			return
		}
	}
	hash, err := auth.HashPassword(req.InitialPassword)
	if err != nil {
		httpapi.WriteError(w, httpapi.E(500, "internal_error", "hash failed"))
		return
	}
	id := NewID()
	_, err = a.DB.Pool.Exec(r.Context(), `
		INSERT INTO users (id, username, password_hash, email, full_name, phone, roles, qualifications, certifications, active, assigned_location_id)
		VALUES ($1,$2,$3,$4,$5,$6,$7::jsonb,$8::jsonb,$9::jsonb,$10,$11)`,
		id, req.Username, hash, req.Email, req.FullName, req.Phone,
		MustJSON(req.Roles), MustJSON(req.Qualifications), MustJSON(req.Certifications),
		req.Active, req.AssignedLocationID)
	if err != nil {
		httpapi.WriteError(w, httpapi.E(409, "concurrent_conflict", "username may already exist"))
		return
	}
	u, _ := a.getUser(r.Context(), id)
	a.audit(r.Context(), s.UserID, s.ActiveRole, "create_user", "user", id, true, nil)
	httpapi.WriteData(w, 201, a.userJSON(u))
}

func (a *App) handleUpdateUserAccess(w http.ResponseWriter, r *http.Request) {
	s, _, err := a.requireAdmin(r.Context())
	if err != nil {
		httpapi.WriteError(w, err)
		return
	}
	var req struct {
		UserID             string                 `json:"userId"`
		Roles              []string               `json:"roles"`
		Qualifications     []string               `json:"qualifications"`
