package app

import (
	"context"
	"time"

	"go.mongodb.org/mongo-driver/v2/bson"
	"labsample/internal/models"
)

func (a *App) audit(ctx context.Context, actorID, role, action, entityType, entityID string, success bool, details map[string]interface{}) {
	if details == nil {
		details = map[string]interface{}{}
	}
	id := NewID()
	now := Now()
	var actor interface{}
	if actorID != "" {
		actor = actorID
	}
	_, _ = a.DB.Pool.Exec(ctx, `
		INSERT INTO audit_log (id, actor_id, actor_role, action, entity_type, entity_id, success, occurred_at, details)
		VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9::jsonb)`,
		id, actor, role, action, entityType, entityID, success, now, MustJSON(details))
	_, _ = a.DB.Pool.Exec(ctx, `
		INSERT INTO timeline_events (action, actor_id, role, entity_type, entity_id, success, occurred_at, details)
		VALUES ($1,$2,$3,$4,$5,$6,$7,$8::jsonb)`,
		action, actor, role, entityType, entityID, success, now, MustJSON(details))
	// Mongo archive
	_, _ = a.DB.MongoDB.Collection("audit_archive").InsertOne(ctx, bson.M{
		"auditId": id, "actorId": actorID, "actorRole": role, "role": role,
		"action": action, "entityType": entityType, "entityId": entityID,
		"success": success, "occurredAt": now, "details": details,
	})
	a.publishEvent(ctx, action, entityType, entityID, details)
}

func (a *App) publishEvent(ctx context.Context, typ, entityType, entityID string, payload map[string]interface{}) {
	if payload == nil {
		payload = map[string]interface{}{}
	}
	var id int64
	_ = a.DB.Pool.QueryRow(ctx, `
		INSERT INTO realtime_events (type, entity_type, entity_id, payload)
		VALUES ($1,$2,$3,$4::jsonb) RETURNING id`, typ, entityType, entityID, MustJSON(payload)).Scan(&id)
	ev := models.RealtimeEvent{
		ID: id, Type: typ, EntityType: entityType, EntityID: entityID,
		Payload: payload, CreatedAt: Now(),
	}
	a.mu.Lock()
	for ch := range a.subs {
		select {
		case ch <- ev:
		default:
		}
	}
	a.mu.Unlock()
}

func (a *App) subscribe() chan models.RealtimeEvent {
	ch := make(chan models.RealtimeEvent, 32)
	a.mu.Lock()
	a.subs[ch] = struct{}{}
	a.mu.Unlock()
	return ch
}

func (a *App) unsubscribe(ch chan models.RealtimeEvent) {
	a.mu.Lock()
	delete(a.subs, ch)
	a.mu.Unlock()
	close(ch)
}

func (a *App) getTimeline(ctx context.Context, entityType, entityID string) ([]models.TimelineEntry, error) {
	rows, err := a.DB.Pool.Query(ctx, `
		SELECT id, action, COALESCE(actor_id::text,''), role, entity_type, entity_id, success, occurred_at, details
		FROM timeline_events WHERE entity_type=$1 AND entity_id=$2 ORDER BY id ASC`, entityType, entityID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []models.TimelineEntry
	for rows.Next() {
		var e models.TimelineEntry
		var details []byte
		if err := rows.Scan(&e.EventID, &e.Action, &e.ActorID, &e.Role, &e.EntityType, &e.EntityID, &e.Success, &e.OccurredAt, &details); err != nil {
			return nil, err
		}
		e.Details = FromJSON[map[string]interface{}](details)
		if e.Details == nil {
			e.Details = map[string]interface{}{}
		}
		out = append(out, e)
	}
	if out == nil {
		out = []models.TimelineEntry{}
	}
	return out, nil
}

func (a *App) handleSearchAudit(w http.ResponseWriter, r *http.Request) {
	s, _, err := a.requireAdminOrDispatcher(r.Context())
	if err != nil {
		writeErr(w, err)
		return
	}
	_ = s
	var req struct {
		Query      string  `json:"query"`
		ActorID    *string `json:"actorId"`
		EntityType *string `json:"entityType"`
		EntityID   *string `json:"entityId"`
		Action     *string `json:"action"`
		Role       *string `json:"role"`
		Success    *bool   `json:"success"`
		FromTime   *string `json:"fromTime"`
		ToTime     *string `json:"toTime"`
		Limit      int     `json:"limit"`
		Offset     int     `json:"offset"`
		Order      string  `json:"order"`
	}
	if err := decode(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	if req.Limit <= 0 {
		req.Limit = 500
	}
	if req.Limit > 5000 {
		req.Limit = 5000
	}
	if req.Order == "" {
		req.Order = "newest_first"
	}
	q := `SELECT id, COALESCE(actor_id::text,''), actor_role, action, entity_type, entity_id, success, occurred_at, details FROM audit_log WHERE 1=1`
	args := []interface{}{}
	n := 1
	add := func(clause string, v interface{}) {
		q += clause
		args = append(args, v)
		n++
	}
	if req.ActorID != nil {
		add(` AND actor_id=$`+itoa(n), *req.ActorID)
	}
	if req.EntityType != nil {
		add(` AND entity_type=$`+itoa(n), *req.EntityType)
	}
	if req.EntityID != nil {
		add(` AND entity_id=$`+itoa(n), *req.EntityID)
	}
	if req.Action != nil {
		add(` AND action=$`+itoa(n), *req.Action)
	}
	if req.Role != nil {
		add(` AND actor_role=$`+itoa(n), *req.Role)
	}
	if req.Success != nil {
		add(` AND success=$`+itoa(n), *req.Success)
	}
	if req.FromTime != nil {
		if t, err := ParseTime(*req.FromTime); err == nil {
			add(` AND occurred_at >= $`+itoa(n), t)
		}
	}
	if req.ToTime != nil {
		if t, err := ParseTime(*req.ToTime); err == nil {
			add(` AND occurred_at <= $`+itoa(n), t)
		}
	}
	if req.Query != "" {
		add(` AND (action ILIKE $`+itoa(n)+` OR entity_id ILIKE $`+itoa(n)+` OR entity_type ILIKE $`+itoa(n)+` OR details::text ILIKE $`+itoa(n)+`)`, "%"+req.Query+"%")
	}
	countQ := `SELECT COUNT(*) FROM (` + q + `) c`
	var total int
	_ = a.DB.Pool.QueryRow(r.Context(), countQ, args...).Scan(&total)
	order := " ORDER BY occurred_at DESC, id DESC"
