func (a *App) handleConfigureCapacity(w http.ResponseWriter, r *http.Request) {
	s, me, err := a.requireRole(r.Context(), models.RoleAdministrator, models.RoleDispatcher, models.RoleNodeHandler, models.RoleLaboratoryTeam)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req struct {
		ResourceID          string `json:"resourceId"`
		CapacityUnits       int    `json:"capacityUnits"`
		CooledCapacityUnits *int   `json:"cooledCapacityUnits"`
	}
	if err := decode(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	cooled := 0
	if req.CooledCapacityUnits != nil {
		cooled = *req.CooledCapacityUnits
	}
	// Try location first
	loc, locErr := a.getLocation(r.Context(), req.ResourceID)
	if locErr == nil {
		if s.ActiveRole == models.RoleNodeHandler || s.ActiveRole == models.RoleLaboratoryTeam {
			if me.AssignedLocationID == nil || *me.AssignedLocationID != req.ResourceID {
				writeErr(w, httpapi.ErrForbidden)
				return
			}
		}
		if req.CapacityUnits < loc.Capacity.ReservedUnits || cooled < loc.Capacity.CooledReservedUnits {
			writeErr(w, httpapi.E(409, "concurrent_conflict", "capacity below reserved"))
			return
		}
		_, err = a.DB.Pool.Exec(r.Context(), `
			UPDATE locations SET capacity_units=$1, cooled_capacity_units=$2 WHERE id=$3`,
			req.CapacityUnits, cooled, req.ResourceID)
	} else {
		// connection
		var reserved, cooledReserved int
		err = a.DB.Pool.QueryRow(r.Context(), `SELECT reserved_units, cooled_reserved_units FROM connections WHERE id=$1`, req.ResourceID).
			Scan(&reserved, &cooledReserved)
		if err != nil {
			writeErr(w, httpapi.ErrNotFound)
			return
		}
		if s.ActiveRole != models.RoleAdministrator && s.ActiveRole != models.RoleDispatcher {
			writeErr(w, httpapi.ErrForbidden)
			return
		}
		if req.CapacityUnits < reserved || cooled < cooledReserved {
			writeErr(w, httpapi.E(409, "concurrent_conflict", "capacity below reserved"))
			return
		}
		_, err = a.DB.Pool.Exec(r.Context(), `
			UPDATE connections SET capacity_units=$1, cooled_capacity_units=$2 WHERE id=$3`,
			req.CapacityUnits, cooled, req.ResourceID)
	}
	if err != nil {
		writeErr(w, errInternal)
		return
	}
	_ = a.bumpNetworkRevision(r.Context())
	a.audit(r.Context(), s.UserID, s.ActiveRole, "configure_capacity", "capacity", req.ResourceID, true, nil)
	writeData(w, 200, map[string]interface{}{
		"resourceId": req.ResourceID, "capacityUnits": req.CapacityUnits, "cooledCapacityUnits": cooled,
	})
}

func (a *App) handleConfigureLabAcceptance(w http.ResponseWriter, r *http.Request) {
