		SELECT id, name, qualified_collector_required, required_qualification, container_type,
			temperature_min_c, temperature_max_c, incompatible_sample_types, requires_cooled_route, batching_allowed
		FROM sample_types WHERE id=$1`, id).Scan(
		&st.ID, &st.Name, &st.QualifiedCollectorRequired, &st.RequiredQualification, &st.ContainerType,
		&st.TemperatureMinC, &st.TemperatureMaxC, &inc, &st.RequiresCooledRoute, &st.BatchingAllowed)
