	}
	if req.TemperatureMinC > req.TemperatureMaxC {
		writeErr(w, httpapi.E(400, "invalid_handling_rule", "invalid temperature range"))
		return
	}
	qcr := true
	if req.QualifiedCollectorRequired != nil {
		qcr = *req.QualifiedCollectorRequired
	}
	if req.RequiredQualification == "" {
		req.RequiredQualification = req.Name
	}
	cooled := false
	if req.RequiresCooledRoute != nil {
		cooled = *req.RequiresCooledRoute
	}
	batch := true
	if req.BatchingAllowed != nil {
		batch = *req.BatchingAllowed
	}
	if req.IncompatibleSampleTypes == nil {
		req.IncompatibleSampleTypes = []string{}
	}
	id := NewID()
	_, err = a.DB.Pool.Exec(r.Context(), `
		INSERT INTO sample_types (id, name, qualified_collector_required, required_qualification,
			container_type, temperature_min_c, temperature_max_c, incompatible_sample_types,
			requires_cooled_route, batching_allowed)
		VALUES ($1,$2,$3,$4,$5,$6,$7,$8::jsonb,$9,$10)`,
		id, req.Name, qcr, req.RequiredQualification, req.ContainerType,
		req.TemperatureMinC, req.TemperatureMaxC, MustJSON(req.IncompatibleSampleTypes), cooled, batch)
	if err != nil {
		writeErr(w, httpapi.E(409, "concurrent_conflict", "name may exist"))
		return
	}
	st, _ := a.getSampleType(r.Context(), id)
	a.audit(r.Context(), s.UserID, s.ActiveRole, "create_sample_type", "sample_type", id, true, nil)
	writeData(w, 201, a.sampleTypeJSON(st))
