	s, _, err := a.requireAdmin(r.Context())
	if err != nil {
		writeErr(w, err)
		return
	}
	var req struct {
		LocationID string `json:"locationId"`
		Function   string `json:"function"`
		Active     bool   `json:"active"`
	}
	if err := decode(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	col := ""
	switch req.Function {
	case "collection_point":
		col = "fn_collection_point"
	case "transfer_point":
		col = "fn_transfer_point"
	case "hub":
		col = "fn_hub"
	case "laboratory":
		col = "fn_laboratory"
	default:
		writeErr(w, httpapi.E(400, "invalid_location_function", "invalid function"))
		return
	}
	tag, err := a.DB.Pool.Exec(r.Context(), `UPDATE locations SET `+col+`=$1 WHERE id=$2`, req.Active, req.LocationID)
	if err != nil || tag.RowsAffected() == 0 {
		writeErr(w, httpapi.ErrNotFound)
		return
	}
	_ = a.bumpNetworkRevision(r.Context())
	loc, _ := a.getLocation(r.Context(), req.LocationID)
	a.audit(r.Context(), s.UserID, s.ActiveRole, "set_location_function_status", "location", req.LocationID, true, nil)
	writeData(w, 200, map[string]interface{}{
		"locationId": req.LocationID, "function": req.Function, "active": req.Active, "functions": loc.Functions,
	})
}

func (a *App) handleCreateConnection(w http.ResponseWriter, r *http.Request) {
