		writeErr(w, err)
		return
	}
	loc, err := a.getLocation(r.Context(), req.LaboratoryID)
	if err != nil || !loc.Functions.Laboratory {
		writeErr(w, httpapi.ErrNotFound)
		return
	}
	var existing string
	err = a.DB.Pool.QueryRow(r.Context(), `SELECT id FROM lab_acceptances WHERE laboratory_id=$1 AND sample_type_id=$2`,
		req.LaboratoryID, req.SampleTypeID).Scan(&existing)
	id := existing
	if err != nil {
		id = NewID()
		_, err = a.DB.Pool.Exec(r.Context(), `
			INSERT INTO lab_acceptances (id, laboratory_id, sample_type_id, accepts) VALUES ($1,$2,$3,$4)`,
			id, req.LaboratoryID, req.SampleTypeID, req.Accepts)
	} else {
		_, err = a.DB.Pool.Exec(r.Context(), `UPDATE lab_acceptances SET accepts=$1 WHERE id=$2`, req.Accepts, id)
	}
	if err != nil {
		writeErr(w, errInternal)
		return
	}
