func (a *App) handleCreateSampleType(w http.ResponseWriter, r *http.Request) {
	s, _, err := a.requireAdmin(r.Context())
	if err != nil {
		writeErr(w, err)
		return
	}
	var req struct {
		Name                       string   `json:"name"`
		QualifiedCollectorRequired *bool    `json:"qualifiedCollectorRequired"`
		RequiredQualification      string   `json:"requiredQualification"`
		ContainerType              string   `json:"containerType"`
		TemperatureMinC            float64  `json:"temperatureMinC"`
		TemperatureMaxC            float64  `json:"temperatureMaxC"`
		IncompatibleSampleTypes    []string `json:"incompatibleSampleTypes"`
		RequiresCooledRoute        *bool    `json:"requiresCooledRoute"`
		BatchingAllowed            *bool    `json:"batchingAllowed"`
	}
	if err := decode(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	if req.Name == "" || req.ContainerType == "" {
		writeErr(w, httpapi.E(400, "invalid_handling_rule", "missing fields"))
		return
	}
	if req.TemperatureMinC > req.TemperatureMaxC {
		writeErr(w, httpapi.E(400, "invalid_handling_rule", "invalid temperature range"))
		return
	}
	qcr := true
	if req.QualifiedCollectorRequired != nil {
		qcr = *req.QualifiedCollectorRequired
	}
	if req.RequiredQualification == "" {
		req.RequiredQualification = req.Name
	}
	cooled := false
	if req.RequiresCooledRoute != nil {
		cooled = *req.RequiresCooledRoute
	}
	batch := true
	if req.BatchingAllowed != nil {
		batch = *req.BatchingAllowed
	}
	if req.IncompatibleSampleTypes == nil {
		req.IncompatibleSampleTypes = []string{}
	}
	id := NewID()
	_, err = a.DB.Pool.Exec(r.Context(), `
		INSERT INTO sample_types (id, name, qualified_collector_required, required_qualification,
			container_type, temperature_min_c, temperature_max_c, incompatible_sample_types,
			requires_cooled_route, batching_allowed)
		VALUES ($1,$2,$3,$4,$5,$6,$7,$8::jsonb,$9,$10)`,
		id, req.Name, qcr, req.RequiredQualification, req.ContainerType,
		req.TemperatureMinC, req.TemperatureMaxC, MustJSON(req.IncompatibleSampleTypes), cooled, batch)
	if err != nil {
		writeErr(w, httpapi.E(409, "concurrent_conflict", "name may exist"))
		return
	}
	st, _ := a.getSampleType(r.Context(), id)
	a.audit(r.Context(), s.UserID, s.ActiveRole, "create_sample_type", "sample_type", id, true, nil)
	writeData(w, 201, a.sampleTypeJSON(st))
}

func (a *App) handleUpdateSampleType(w http.ResponseWriter, r *http.Request) {
	s, _, err := a.requireAdmin(r.Context())
	if err != nil {
		writeErr(w, err)
		return
	}
	var req struct {
		SampleTypeID               string   `json:"sampleTypeId"`
		QualifiedCollectorRequired *bool    `json:"qualifiedCollectorRequired"`
		RequiredQualification      string   `json:"requiredQualification"`
		ContainerType              string   `json:"containerType"`
		TemperatureMinC            float64  `json:"temperatureMinC"`
		TemperatureMaxC            float64  `json:"temperatureMaxC"`
		IncompatibleSampleTypes    []string `json:"incompatibleSampleTypes"`
		RequiresCooledRoute        *bool    `json:"requiresCooledRoute"`
		BatchingAllowed            *bool    `json:"batchingAllowed"`
	}
	if err := decode(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	st, err := a.getSampleType(r.Context(), req.SampleTypeID)
	if err != nil {
		writeErr(w, httpapi.ErrNotFound)
		return
	}
	if req.TemperatureMinC > req.TemperatureMaxC {
		writeErr(w, httpapi.E(400, "invalid_handling_rule", "invalid temperature range"))
		return
	}
	qcr := st.QualifiedCollectorRequired
	if req.QualifiedCollectorRequired != nil {
		qcr = *req.QualifiedCollectorRequired
	}
	rq := req.RequiredQualification
	if rq == "" {
		rq = st.RequiredQualification
	}
	cooled := st.RequiresCooledRoute
	if req.RequiresCooledRoute != nil {
		cooled = *req.RequiresCooledRoute
	}
	batch := st.BatchingAllowed
	if req.BatchingAllowed != nil {
		batch = *req.BatchingAllowed
	}
	inc := req.IncompatibleSampleTypes
	if inc == nil {
		inc = st.IncompatibleSampleTypes
	}
	_, err = a.DB.Pool.Exec(r.Context(), `
		UPDATE sample_types SET qualified_collector_required=$1, required_qualification=$2, container_type=$3,
			temperature_min_c=$4, temperature_max_c=$5, incompatible_sample_types=$6::jsonb,
			requires_cooled_route=$7, batching_allowed=$8 WHERE id=$9`,
		qcr, rq, req.ContainerType, req.TemperatureMinC, req.TemperatureMaxC, MustJSON(inc), cooled, batch, req.SampleTypeID)
	if err != nil {
		writeErr(w, errInternal)
		return
	}
	st, _ = a.getSampleType(r.Context(), req.SampleTypeID)
	a.audit(r.Context(), s.UserID, s.ActiveRole, "update_sample_type", "sample_type", req.SampleTypeID, true, nil)
	writeData(w, 201, a.sampleTypeJSON(st))
}

func (a *App) getSampleType(ctx context.Context, id string) (*models.SampleType, error) {
	st := &models.SampleType{}
	var inc []byte
	err := a.DB.Pool.QueryRow(ctx, `
		SELECT id, name, qualified_collector_required, required_qualification, container_type,
			temperature_min_c, temperature_max_c, incompatible_sample_types, requires_cooled_route, batching_allowed
		FROM sample_types WHERE id=$1`, id).Scan(
		&st.ID, &st.Name, &st.QualifiedCollectorRequired, &st.RequiredQualification, &st.ContainerType,
		&st.TemperatureMinC, &st.TemperatureMaxC, &inc, &st.RequiresCooledRoute, &st.BatchingAllowed)
	if err != nil {
		return nil, err
	}
	st.IncompatibleSampleTypes = FromJSON[[]string](inc)
	if st.IncompatibleSampleTypes == nil {
		st.IncompatibleSampleTypes = []string{}
	}
	return st, nil
}

func (a *App) getSampleTypeByName(ctx context.Context, name string) (*models.SampleType, error) {
	var id string
	err := a.DB.Pool.QueryRow(ctx, `SELECT id FROM sample_types WHERE name=$1`, name).Scan(&id)
	if err != nil {
		return nil, err
	}
	return a.getSampleType(ctx, id)
}

func (a *App) sampleTypeJSON(st *models.SampleType) map[string]interface{} {
	return map[string]interface{}{
		"sampleTypeId": st.ID, "name": st.Name,
		"qualifiedCollectorRequired": st.QualifiedCollectorRequired,
		"requiredQualification":      st.RequiredQualification,
		"containerType":              st.ContainerType,
		"temperatureMinC":            st.TemperatureMinC,
		"temperatureMaxC":            st.TemperatureMaxC,
		"incompatibleSampleTypes":    st.IncompatibleSampleTypes,
		"requiresCooledRoute":        st.RequiresCooledRoute,
		"batchingAllowed":            st.BatchingAllowed,
	}
}

func (a *App) bumpNetworkRevision(ctx context.Context) error {
	_, err := a.DB.Pool.Exec(ctx, `UPDATE network_meta SET revision = revision + 1 WHERE id=1`)
	if err != nil {
		return err
	}
	return a.recomputeServiceability(ctx)
}

func (a *App) recomputeServiceability(ctx context.Context) error {
	var rev int
	_ = a.DB.Pool.QueryRow(ctx, `SELECT revision FROM network_meta WHERE id=1`).Scan(&rev)
	rows, err := a.DB.Pool.Query(ctx, `
		SELECT id, name, latitude, longitude, coverage_km FROM locations
		WHERE active=true AND fn_collection_point=true`)
	if err != nil {
		return err
	}
	defer rows.Close()
	regions := []models.ServiceabilityRegion{}
	for rows.Next() {
		var r models.ServiceabilityRegion
		if err := rows.Scan(&r.LocationID, &r.Name, &r.Latitude, &r.Longitude, &r.CoverageKm); err != nil {
			return err
		}
		regions = append(regions, r)
	}
	var ver int
	_ = a.DB.Pool.QueryRow(ctx, `SELECT COALESCE(MAX(version),0) FROM serviceability_snapshots`).Scan(&ver)
	ver++
	_, err = a.DB.Pool.Exec(ctx, `
		INSERT INTO serviceability_snapshots (version, status, computed_at, network_revision, regions, active_collection_point_count)
		VALUES ($1,'complete',$2,$3,$4::jsonb,$5)`,
		ver, time.Now().UTC(), rev, MustJSON(regions), len(regions))
	if err != nil {
		return err
	}
	_, err = a.DB.Pool.Exec(ctx, `UPDATE network_meta SET current_serviceability_version=$1 WHERE id=1`, ver)
	return err
}

func (a *App) currentServiceabilityVersion(ctx context.Context) int {
	var v int
	_ = a.DB.Pool.QueryRow(ctx, `SELECT current_serviceability_version FROM network_meta WHERE id=1`).Scan(&v)
	if v < 1 {
		v = 1
	}
	return v
}

func (a *App) handleReadServiceabilitySnapshot(w http.ResponseWriter, r *http.Request) {
	if _, _, err := a.requireRole(r.Context()); err != nil {
		writeErr(w, err)
		return
	}
	var req struct{}
	_ = decode(r, &req)
	var ver, rev, count int
	var status string
	var computed time.Time
	var regionsJSON []byte
	err := a.DB.Pool.QueryRow(r.Context(), `
		SELECT s.version, s.status, s.computed_at, s.network_revision, s.regions, s.active_collection_point_count
		FROM serviceability_snapshots s
		JOIN network_meta m ON m.current_serviceability_version = s.version
		WHERE m.id=1`).Scan(&ver, &status, &computed, &rev, &regionsJSON, &count)
	if err != nil {
		// empty snapshot
		writeData(w, 200, map[string]interface{}{
			"version": 1, "status": "complete", "computedAt": FormatTime(Now()),
			"networkRevision": 0, "regions": []interface{}{}, "activeCollectionPointCount": 0,
		})
		return
	}
	regions := FromJSON[[]models.ServiceabilityRegion](regionsJSON)
	if regions == nil {
		regions = []models.ServiceabilityRegion{}
	}
	writeData(w, 200, map[string]interface{}{
		"version": ver, "status": status, "computedAt": FormatTime(computed),
		"networkRevision": rev, "regions": regions, "activeCollectionPointCount": count,
	})
}

