		return
	}
	now := Now()
	holder := me.ID
	if req.HolderID != nil && (s.ActiveRole == models.RoleAdministrator || s.ActiveRole == models.RoleDispatcher) {
		holder = *req.HolderID
	}
	route, reason, _ := a.checkServiceability(r.Context(), serviceabilityInput{
		Origin: req.Origin, OriginType: req.OriginType, OriginNodeID: req.OriginNodeID,
		SampleTypeID: req.SampleTypeID, RequestedAt: now, DeliveryDeadline: deadline,
		EarliestCollectionAt: now, LatestCollectionAt: deadline,
	})
	sampleID := NewID()
	requestID := NewID()
	svc := "unserviceable"
	status := "sealed"
	if reason == "serviceable" {
		svc = "serviceable"
	}
	var targetLab *string
	if route != nil && route.Laboratory != nil {
		targetLab = &route.Laboratory.ID
	}
	_, err = a.DB.Pool.Exec(r.Context(), `
		INSERT INTO samples (
			id, request_id, requester_id, origin_lat, origin_lon, origin_type, origin_node_id,
			requested_at, delivery_deadline, earliest_collection_at, latest_collection_at,
			sample_type_id, container_type, temperature_min_c, temperature_max_c, incompatible_sample_types,
			serviceability, serviceability_reason, status, sealed, sealed_at, already_sealed,
			current_holder_id, target_laboratory_id, latest_lat, latest_lon, location_recorded_at)
		VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9,$8,$9,$10,$11,$12,$13,$14::jsonb,$15,$16,$17,true,$8,true,$18,$19,$4,$5,$8)`,
		sampleID, requestID, me.ID, req.Origin.Latitude, req.Origin.Longitude, req.OriginType, req.OriginNodeID,
		now, deadline, st.ID, st.ContainerType, st.TemperatureMinC, st.TemperatureMaxC, MustJSON(st.IncompatibleSampleTypes),
		svc, reason, status, holder, targetLab)
	if err != nil {
		writeErr(w, errInternal)
		return
	}
	a.audit(r.Context(), s.UserID, s.ActiveRole, "ingest_presealed_sample", "sample", sampleID, true, nil)
	if reason == "serviceable" && route != nil {
		_ = a.planJourneyForSample(r.Context(), sampleID, route, true)
	}
	sample, _ := a.getSample(r.Context(), sampleID)
	writeData(w, 201, a.sampleStateJSON(r.Context(), sample))
}

