func (a *App) handleCollectAndSeal(w http.ResponseWriter, r *http.Request) {
	s, me, err := a.requireRole(r.Context(), models.RoleCollectionProfessional, models.RoleAdministrator)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req struct {
		AssignmentID string             `json:"assignmentId"`
		SampleID     string             `json:"sampleId"`
		Coordinate   *models.Coordinate `json:"coordinate"`
		SealedAt     string             `json:"sealedAt"`
	}
	if err := decode(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	asg, err := a.getAssignment(r.Context(), req.AssignmentID)
	if err != nil || asg.Kind != "collection" {
		writeErr(w, notFound())
		return
	}
	if asg.WorkerID == nil || *asg.WorkerID != me.ID {
		if s.ActiveRole != models.RoleAdministrator {
			writeErr(w, httpapi.ErrForbidden)
			return
		}
	}
	if asg.Status != "accepted" && asg.Status != "in_progress" {
		writeErr(w, httpapi.E(409, "invalid_assignment_state", "assignment not accepted"))
		return
	}
	sample, err := a.getSample(r.Context(), req.SampleID)
	if err != nil || sample.ID != asg.SampleID {
		writeErr(w, notFound())
		return
	}
	// qualification check
	st, _ := a.getSampleType(r.Context(), sample.SampleTypeID)
	if st != nil && st.QualifiedCollectorRequired {
		ok := ContainsStr(me.Qualifications, st.RequiredQualification) || ContainsStr(me.Qualifications, st.Name)
		for _, c := range me.Certifications {
			if c.Active && (c.Code == st.RequiredQualification || c.Code == st.Name) {
				ok = true
			}
		}
		if !ok && s.ActiveRole != models.RoleAdministrator {
			writeErr(w, httpapi.E(403, "not_qualified", "collector not qualified"))
			return
		}
	}
	now := Now()
	if req.SealedAt != "" {
		if t, err := ParseTime(req.SealedAt); err == nil {
			now = t
		}
	}
	// collection window
	if now.Before(sample.EarliestCollectionAt) || now.After(sample.LatestCollectionAt) {
		writeErr(w, httpapi.E(409, "outside_collection_window", "outside collection window"))
		return
	}
	lat, lon := sample.Origin.Latitude, sample.Origin.Longitude
	if req.Coordinate != nil {
		lat, lon = req.Coordinate.Latitude, req.Coordinate.Longitude
	}
	_, err = a.DB.Pool.Exec(r.Context(), `
		UPDATE samples SET status='sealed', sealed=true, sealed_at=$1, current_holder_id=$2,
			latest_lat=$3, latest_lon=$4, location_recorded_at=$1 WHERE id=$5`,
		now, me.ID, lat, lon, sample.ID)
	if err != nil {
		writeErr(w, errInternal)
		return
	}
	_, _ = a.DB.Pool.Exec(r.Context(), `
		UPDATE assignments SET status='completed', completed_at=$1 WHERE id=$2`, now, asg.ID)
	// activate next assignment offer
	_ = a.offerNextAssignments(r.Context(), sample.ID)
	a.audit(r.Context(), s.UserID, s.ActiveRole, "collect_and_seal_sample", "sample", sample.ID, true, nil)
	sample, _ = a.getSample(r.Context(), sample.ID)
	writeData(w, 200, a.sampleStateJSON(r.Context(), sample))
}

func (a *App) handleConfirmLabReceipt(w http.ResponseWriter, r *http.Request) {
	s, me, err := a.requireRole(r.Context(), models.RoleLaboratoryTeam, models.RoleAdministrator)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req struct {
		AssignmentID string `json:"assignmentId"`
		SampleID     string `json:"sampleId"`
		LaboratoryID string `json:"laboratoryId"`
		ReceivedAt   string `json:"receivedAt"`
	}
	if err := decode(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	asg, err := a.getAssignment(r.Context(), req.AssignmentID)
	if err != nil || asg.Kind != "laboratory" {
		writeErr(w, notFound())
		return
	}
	if asg.WorkerID == nil || *asg.WorkerID != me.ID {
		if s.ActiveRole != models.RoleAdministrator {
			writeErr(w, httpapi.ErrForbidden)
			return
		}
	}
	sample, err := a.getSample(r.Context(), req.SampleID)
	if err != nil {
		writeErr(w, notFound())
		return
	}
	now := Now()
	if req.ReceivedAt != "" {
		if t, e := ParseTime(req.ReceivedAt); e == nil {
			now = t
		}
	}
	labID := req.LaboratoryID
	if labID == "" && asg.LaboratoryID != nil {
		labID = *asg.LaboratoryID
	}
	_, err = a.DB.Pool.Exec(r.Context(), `
		UPDATE samples SET status='received', received_laboratory_id=$1, received_at=$2,
			current_holder_id=$3, location_recorded_at=$2 WHERE id=$4`,
		labID, now, me.ID, sample.ID)
	if err != nil {
		writeErr(w, errInternal)
		return
	}
	_, _ = a.DB.Pool.Exec(r.Context(), `UPDATE assignments SET status='completed', completed_at=$1 WHERE id=$2`, now, asg.ID)
	if sample.ActiveJourneyID != nil {
		_, _ = a.DB.Pool.Exec(r.Context(), `UPDATE journeys SET status='completed' WHERE id=$1`, *sample.ActiveJourneyID)
		_ = a.releaseCapacityForJourney(r.Context(), *sample.ActiveJourneyID)
	}
	a.audit(r.Context(), s.UserID, s.ActiveRole, "confirm_laboratory_receipt", "sample", sample.ID, true, nil)
	sample, _ = a.getSample(r.Context(), sample.ID)
	writeData(w, 200, a.sampleLifecycleJSON(r.Context(), sample))
}

func (a *App) handleRecordLabException(w http.ResponseWriter, r *http.Request) {
	s, me, err := a.requireRole(r.Context(), models.RoleLaboratoryTeam, models.RoleAdministrator, models.RoleDispatcher)
	if err != nil {
		writeErr(w, err)
		return
	}
	_ = me
	var req struct {
		SampleID string `json:"sampleId"`
		Reason   string `json:"reason"`
		Kind     string `json:"kind"`
	}
	if err := decode(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	now := Now()
	kind := req.Kind
	if kind == "" {
		kind = "laboratory_rejection"
	}
	tag, err := a.DB.Pool.Exec(r.Context(), `
		UPDATE samples SET status='exception', exception_reason=$1, exception_at=$2, exception_kind=$3 WHERE id=$4`,
		req.Reason, now, kind, req.SampleID)
	if err != nil || tag.RowsAffected() == 0 {
		writeErr(w, notFound())
		return
	}
	a.audit(r.Context(), s.UserID, s.ActiveRole, "record_laboratory_exception", "sample", req.SampleID, true,
		map[string]interface{}{"reason": req.Reason, "kind": kind})
	sample, _ := a.getSample(r.Context(), req.SampleID)
	writeData(w, 200, a.sampleLifecycleJSON(r.Context(), sample))
}

func (a *App) handleRecordHandlingCheckpoint(w http.ResponseWriter, r *http.Request) {
	s, me, err := a.requireRole(r.Context(),
		models.RoleCollectionProfessional, models.RoleDeliveryPartner,
		models.RoleNodeHandler, models.RoleLaboratoryTeam, models.RoleAdministrator)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req struct {
		SampleID              string  `json:"sampleId"`
		AssignmentID          string  `json:"assignmentId"`
		LocationID            *string `json:"locationId"`
		ContainerType         string  `json:"containerType"`
		ObservedTemperatureC  float64 `json:"observedTemperatureC"`
	}
	if err := decode(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	sample, err := a.getSample(r.Context(), req.SampleID)
	if err != nil {
		writeErr(w, notFound())
		return
	}
	if sample.CurrentHolderID == nil || *sample.CurrentHolderID != me.ID {
		if s.ActiveRole != models.RoleAdministrator {
			writeErr(w, httpapi.ErrForbidden)
			return
		}
	}
	compliant := req.ObservedTemperatureC >= sample.TemperatureMinC &&
		req.ObservedTemperatureC <= sample.TemperatureMaxC
	if req.ContainerType != "" && sample.ContainerType != "" && req.ContainerType != sample.ContainerType {
		// frost requires cooled container etc - soft check
		if sample.ContainerType == "cooled" && req.ContainerType != "cooled" {
			compliant = false
		}
	}
	id := NewID()
	now := Now()
	_, _ = a.DB.Pool.Exec(r.Context(), `
		INSERT INTO handling_checkpoints (id, sample_id, assignment_id, location_id, container_type, observed_temperature_c, compliant, recorded_at, actor_id)
		VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9)`,
		id, req.SampleID, req.AssignmentID, req.LocationID, req.ContainerType, req.ObservedTemperatureC, compliant, now, me.ID)
	if !compliant {
		kind := "handling_violation"
		reason := "observed container or temperature outside required range"
		_, _ = a.DB.Pool.Exec(r.Context(), `
			UPDATE samples SET status='exception', exception_reason=$1, exception_at=$2, exception_kind=$3 WHERE id=$4`,
			reason, now, kind, sample.ID)
	}
	a.audit(r.Context(), s.UserID, s.ActiveRole, "record_handling_checkpoint", "sample", sample.ID, true,
		map[string]interface{}{"compliant": compliant})
	sample, _ = a.getSample(r.Context(), sample.ID)
	writeData(w, 200, map[string]interface{}{
		"checkpointId": id, "compliant": compliant, "sample": a.sampleLifecycleJSON(r.Context(), sample),
	})
}

