		FROM samples WHERE id=$1 OR request_id=$1`, id).Scan(
		&s.ID, &s.RequestID, &s.RequesterID, &s.Origin.Latitude, &s.Origin.Longitude, &s.OriginType, &originNode,
		&s.RequestedAt, &s.DeliveryDeadline, &s.EarliestCollectionAt, &s.LatestCollectionAt,
		&s.SampleTypeID, &s.ContainerType, &s.TemperatureMinC, &s.TemperatureMaxC, &inc,
		&s.Serviceability, &s.ServiceabilityReason, &s.Status, &s.Sealed, &sealedAt, &s.AlreadySealed,
		&holder, &journey, &target, &received, &receivedAt,
		&lat, &lon, &locAt, &handoff,
		&exReason, &exAt, &exKind, &s.CreatedAt,
	)
	if err != nil {
		return nil, err
	}
	s.OriginNodeID = originNode
	s.CurrentHolderID = holder
	s.ActiveJourneyID = journey
	s.TargetLaboratoryID = target
	s.ReceivedLaboratoryID = received
	s.ReceivedAt = receivedAt
	s.SealedAt = sealedAt
	s.LatestLat = lat
	s.LatestLon = lon
	s.LocationRecordedAt = locAt
	s.PendingHandoffID = handoff
	s.ExceptionReason = exReason
	s.ExceptionAt = exAt
	s.ExceptionKind = exKind
	s.IncompatibleSampleTypes = FromJSON[[]string](inc)
	if s.IncompatibleSampleTypes == nil {
		s.IncompatibleSampleTypes = []string{}
	}
	return s, nil
}

func (a *App) locationStale(s *models.Sample) bool {
	if s.LocationRecordedAt == nil {
		return true
	}
	return time.Since(*s.LocationRecordedAt) > time.Duration(a.Cfg.LocationStaleSec)*time.Second
}

func (a *App) activeAssignmentIDs(ctx context.Context, sampleID string) []string {
	rows, err := a.DB.Pool.Query(ctx, `
		SELECT id FROM assignments WHERE sample_id=$1 AND status IN ('offered','accepted','in_progress','pending')
		ORDER BY sequence, created_at`, sampleID)
	if err != nil {
		return []string{}
	}
	defer rows.Close()
	var out []string
	for rows.Next() {
		var id string
		_ = rows.Scan(&id)
		out = append(out, id)
	}
	if out == nil {
		out = []string{}
	}
	return out
}

