file_editor: {"command": "create", "path": "/workspace/backend/internal/app/journeys.go", "file_text": "package app

import (
	"context"
	"fmt"
	"net/http"
	"time"

	"labsample/internal/httpapi"
	"labsample/internal/models"
)

func (a *App) planJourneyForSample(ctx context.Context, sampleID string, route *plannedRoute, presealed bool) error {
	sample, err := a.getSample(ctx, sampleID)
	if err != nil {
		return err
	}
	st, err := a.getSampleType(ctx, sample.SampleTypeID)
	if err != nil {
		return err
	}
	journeyID := NewID()
	routeMode := "direct"
	if len(route.Hops) > 1 {
		routeMode = "multi_stop"
	}
	now := Now()
	eta := route.ArrivalAt
	_, err = a.DB.Pool.Exec(ctx, `
		INSERT INTO journeys (id, plan_version, route_mode, status, estimated_delivery_at, total_cost_units,
			capacity_used, sample_ids, assigned_worker_ids, valid)
		VALUES ($1,1,$2,'planned',$3,$4,1,$5::jsonb,'[]'::jsonb,true)`,
		journeyID, routeMode, eta, route.TotalCost, MustJSON([]string{sampleID}))
	if err != nil {
		return err
	}
	// stops
	seq := 0
	stopIDs := []string{}
	addStop := func(locID, stopType string, at time.Time, lat, lon float64) {
		sid := NewID()
		_, _ = a.DB.Pool.Exec(ctx, `
			INSERT INTO journey_stops (id, journey_id, location_id, stop_type, sequence, estimated_at, dwell_minutes, lat, lon)
			VALUES ($1,$2,$3,$4,$5,$6,0,$7,$8)`,
			sid, journeyID, locID, stopType, seq, at, lat, lon)
		stopIDs = append(stopIDs, sid)
		seq++
	}
	t := sample.EarliestCollectionAt
	if t.Before(now) {
		t = now
	}
	// origin stop (virtual if home)
	originLocID := NewID()
	if route.CollectionNode != nil {
		if sample.OriginType == "node" && sample.OriginNodeID != nil {
			originLocID = *sample.OriginNodeID
		} else {
			// use collection node as first network stop; origin is home/clinic
			addStop(route.CollectionNode.ID, "collection", t, sample.Origin.Latitude, sample.Origin.Longitude)
			originLocID = route.CollectionNode.ID
			t = t.Add(time.Duration(route.CollectionNode.HandlingMinutes) * time.Minute)
		}
	}
	prevLoc := originLocID
	for _, h := range route.Hops {
		t = t.Add(time.Duration(h.TravelMinutes) * time.Minute)
		toLoc, _ := a.getLocation(ctx, h.ToLocationID)
		lat, lon := 0.0, 0.0
		if toLoc != nil {
			lat, lon = toLoc.Coordinate.Latitude, toLoc.Coordinate.Longitude
			t = t.Add(time.Duration(toLoc.HandlingMinutes) * time.Minute)
		}
		stopType := "transfer"
		if toLoc != nil && toLoc.Functions.Laboratory {
			stopType = "laboratory"
		} else if toLoc != nil && toLoc.Functions.Hub {
			stopType = "hub"
		}
		addStop(h.ToLocationID, stopType, t, lat, lon)
		prevLoc = h.ToLocationID
	}
	_ = prevLoc

	cooledUnits := 0
	if st.RequiresCooledRoute {
		cooledUnits = 1
	}

	var collectionIDs, nodeIDs, labIDs []string
	var firstTransport, middleTransport, finalTransport *string
	asgSeq := 0

	if !presealed {
		// collection assignment
		cid := NewID()
		fromID := originLocID
		toID := originLocID
		if route.CollectionNode != nil {
			toID = route.CollectionNode.ID
		}
		_, err = a.DB.Pool.Exec(ctx, `
			INSERT INTO assignments (id, journey_id, sample_id, kind, status, sequence, from_location_id, to_location_id, expected_sample_type_id)
			VALUES ($1,$2,$3,'collection','pending',$4,$5,$6,$7)`,
			cid, journeyID, sampleID, asgSeq, fromID, toID, sample.SampleTypeID)
		if err != nil {
			return err
		}
		collectionIDs = append(collectionIDs, cid)
		asgSeq++
		_ = a.offerAssignment(ctx, cid)
	}

	// transport legs for each hop
	transportIDs := []string{}
	for i, h := range route.Hops {
		tid := NewID()
		from := h.FromLocationID
		to := h.ToLocationID
		_, err = a.DB.Pool.Exec(ctx, `
			INSERT INTO assignments (id, journey_id, sample_id, kind, status, sequence, from_location_id, to_location_id)
			VALUES ($1,$2,$3,'transport','pending',$4,$5,$6)`,
			tid, journeyID, sampleID, asgSeq, from, to)
		if err != nil {
			return err
		}
		transportIDs = append(transportIDs, tid)
		// reserve connection capacity
		_ = a.reserveCapacity(ctx, h.ConnectionID, "connection", journeyID, sampleID, 1, cooledUnits)
		asgSeq++

		// node assignment at intermediate stops
		if i < len(route.Hops)-1 {
			nid := NewID()
			_, _ = a.DB.Pool.Exec(ctx, `
				INSERT INTO assignments (id, journey_id, sample_id, kind, status, sequence, node_id, to_location_id)
				VALUES ($1,$2,$3,'node','pending',$4,$5,$5)`,
				nid, journeyID, sampleID, asgSeq, to)
			nodeIDs = append(nodeIDs, nid)
			asgSeq++
		}
	}
	if len(transportIDs) > 0 {
		firstTransport = &transportIDs[0]
		finalTransport = &transportIDs[len(transportIDs)-1]
		if len(transportIDs) >= 3 {
			mid := transportIDs[len(transportIDs)/2]
			middleTransport = &mid
		} else if len(transportIDs) == 2 {
			middleTransport = &transportIDs[0]
		}
	}

	// laboratory assignment
	if route.Laboratory != nil {
		lid := NewID()
		_, err = a.DB.Pool.Exec(ctx, `
			INSERT INTO assignments (id, journey_id, sample_id, kind, status, sequence, laboratory_id, to_location_id, expected_sample_type_id)
			VALUES ($1,$2,$3,'laboratory','pending',$4,$5,$5,$6)`,
			lid, journeyID, sampleID, asgSeq, route.Laboratory.ID, sample.SampleTypeID)
		if err != nil {
			return err
		}
		labIDs = append(labIDs, lid)
		_ = a.reserveCapacity(ctx, route.Laboratory.ID, "location", journeyID, sampleID, 1, cooledUnits)
	}
	if route.CollectionNode != nil {
		_ = a.reserveCapacity(ctx, route.CollectionNode.ID, "location", journeyID, sampleID, 1, cooledUnits)
	}

	_, err = a.DB.Pool.Exec(ctx, `
		UPDATE journeys SET collection_assignment_ids=$1::jsonb, node_assignment_ids=$2::jsonb,
			laboratory_assignment_ids=$3::jsonb, first_transport_assignment_id=$4,
			middle_transport_assignment_id=$5, final_transport_assignment_id=$6, status='active'
		WHERE id=$7`,
		MustJSON(collectionIDs), MustJSON(nodeIDs), MustJSON(labIDs),
		firstTransport, middleTransport, finalTransport, journeyID)
	if err != nil {
		return err
	}
	_, err = a.DB.Pool.Exec(ctx, `UPDATE samples SET active_journey_id=$1, status=CASE WHEN status='sealed' THEN 'in_transit' ELSE 'planned' END, target_laboratory_id=$2 WHERE id=$3`,
		journeyID, func() interface{} {
			if route.Laboratory != nil {
				return route.Laboratory.ID
			}
			return nil
		}(), sampleID)
	if err != nil {
		return err
	}
	// offer first pending non-collection if presealed
	if presealed {
		_ = a.offerNextAssignments(ctx, sampleID)
	}
	return nil
}

func (a *App) reserveCapacity(ctx context.Context, resourceID, resourceType, journeyID, sampleID string, units, cooled int) error {
	if resourceType == "location" {
		var cu, ru, ccu, cru int
		err := a.DB.Pool.QueryRow(ctx, `
			SELECT capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units FROM locations WHERE id=$1`, resourceID).
			Scan(&cu, &ru, &ccu, &cru)
		if err != nil {
			return err
		}
		if cu > 0 && ru+units > cu {
			return fmt.Errorf("insufficient capacity")
		}
		if ccu > 0 && cru+cooled > ccu {
			return fmt.Errorf("insufficient cooled capacity")
		}
		_, err = a.DB.Pool.Exec(ctx, `
			UPDATE locations SET reserved_units = reserved_units + $1, cooled_reserved_units = cooled_reserved_units + $2 WHERE id=$3`,
			units, cooled, resourceID)
		if err != nil {
			return err
		}
	} else if resourceType == "connection" {
		var cu, ru, ccu, cru int
		err := a.DB.Pool.QueryRow(ctx, `
			SELECT capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units FROM connections WHERE id=$1`, resourceID).
			Scan(&cu, &ru, &ccu, &cru)
		if err != nil {
			return err
		}
		if cu > 0 && ru+units > cu {
			return fmt.Errorf("insufficient capacity")
		}
		if ccu > 0 && cru+cooled > ccu {
			return fmt.Errorf("insufficient cooled capacity")
		}
		_, err = a.DB.Pool.Exec(ctx, `
			UPDATE connections SET reserved_units = reserved_units + $1, cooled_reserved_units = cooled_reserved_units + $2 WHERE id=$3`,
			units, cooled, resourceID)
		if err != nil {
			return err
		}
	}
	id := NewID()
	_, err := a.DB.Pool.Exec(ctx, `
		INSERT INTO capacity_reservations (id, resource_id, resource_type, journey_id, sample_id, units, cooled_units, active)
		VALUES ($1,$2,$3,$4,$5,$6,$7,true)`,
		id, resourceID, resourceType, journeyID, sampleID, units, cooled)
	return err
}

func (a *App) releaseCapacityForJourney(ctx context.Context, journeyID string) error {
	rows, err := a.DB.Pool.Query(ctx, `
		SELECT id, resource_id, resource_type, units, cooled_units FROM capacity_reservations
		WHERE journey_id=$1 AND active=true`, journeyID)
	if err != nil {
		return err
	}
	defer rows.Close()
	type res struct {
		id, rid, rtype string
		units, cooled  int
	}
	var list []res
	for rows.Next() {
		var r res
		_ = rows.Scan(&r.id, &r.rid, &r.rtype, &r.units, &r.cooled)
		list = append(list, r)
	}
	for _, r := range list {
		if r.rtype == "location" {
			_, _ = a.DB.Pool.Exec(ctx, `
				UPDATE locations SET reserved_units = GREATEST(0, reserved_units - $1),
					cooled_reserved_units = GREATEST(0, cooled_reserved_units - $2) WHERE id=$3`,
				r.units, r.cooled, r.rid)
		} else if r.rtype == "connection" {
			_, _ = a.DB.Pool.Exec(ctx, `
				UPDATE connections SET reserved_units = GREATEST(0, reserved_units - $1),
					cooled_reserved_units = GREATEST(0, cooled_reserved_units - $2) WHERE id=$3`,
				r.units, r.cooled, r.rid)
		}
		_, _ = a.DB.Pool.Exec(ctx, `UPDATE capacity_reservations SET active=false WHERE id=$1`, r.id)
	}
	return nil
}

func (a *App) getJourney(ctx context.Context, id string) (map[string]interface{}, error) {
	var jid string
	var parent *string
	var planVersion int
	var routeMode, status string
	var eta *time.Time
	var cost float64
	var capUsed int
	var sampleIDs, workerIDs, collIDs, nodeIDs, labIDs []byte
	var first, mid, final *string
	var valid bool
	var replan *string
	err := a.DB.Pool.QueryRow(ctx, `
		SELECT id, parent_journey_id, plan_version, route_mode, status, estimated_delivery_at, total_cost_units,
			capacity_used, sample_ids, assigned_worker_ids, collection_assignment_ids, node_assignment_ids,
			laboratory_assignment_ids, first_transport_assignment_id, middle_transport_assignment_id,
			final_transport_assignment_id, valid, replan_status
		FROM journeys WHERE id=$1`, id).Scan(
		&jid, &parent, &planVersion, &routeMode, &status, &eta, &cost, &capUsed,
		&sampleIDs, &workerIDs, &collIDs, &nodeIDs, &labIDs, &first, &mid, &final, &valid, &replan)
	if err != nil {
		return nil, err
	}
	stops := a.journeyStopsJSON(ctx, id)
	legs := a.journeyLegsJSON(ctx, id)
	sids := FromJSON[[]string](sampleIDs)
	if sids == nil {
		sids = []string{}
	}
	wids := FromJSON[[]string](workerIDs)
	if wids == nil {
		wids = []string{}
	}
	cids := FromJSON[[]string](collIDs)
	if cids == nil {
		cids = []string{}
	}
	nids := FromJSON[[]string](nodeIDs)
	if nids == nil {
		nids = []string{}
	}
	lids := FromJSON[[]string](labIDs)
	if lids == nil {
		lids = []string{}
	}
	capAvail := 0
	out := map[string]interface{}{
		"journeyId":                jid,
		"planVersion":              planVersion,
		"routeMode":                routeMode,
		"status":                   status,
		"totalCostUnits":           cost,
		"capacityUsed":             capUsed,
		"capacityAvailable":        capAvail,
		"sampleIds":                sids,
		"orderedStops":             stops,
		"legs":                     legs,
		"assignedWorkerIds":        wids,
		"collectionAssignmentIds":  cids,
		"nodeAssignmentIds":        nids,
		"laboratoryAssignmentIds":  lids,
		"valid":                    valid,
	}
	if parent != nil {
		out["parentJourneyId"] = *parent
	}
	if eta != nil {
		out["estimatedDeliveryAt"] = FormatTime(*eta)
	}
	if len(cids) > 0 {
		out["collectionAssignmentId"] = cids[0]
	}
	if first != nil {
		out["firstTransportAssignmentId"] = *first
	}
	if mid != nil {
		out["middleTransportAssignmentId"] = *mid
	}
	if final != nil {
		out["finalTransportAssignmentId"] = *final
	}
	if replan != nil {
		out["replanStatus"] = *replan
	}
	return out, nil
}

func (a *App) journeyStopsJSON(ctx context.Context, journeyID string) []map[string]interface{} {
	rows, err := a.DB.Pool.Query(ctx, `
		SELECT id, location_id, stop_type, sequence, estimated_at, dwell_minutes, lat, lon, completed_at
		FROM journey_stops WHERE journey_id=$1 ORDER BY sequence`, journeyID)
	if err != nil {
		return []map[string]interface{}{}
	}
	defer rows.Close()
	out := []map[string]interface{}{}
	for rows.Next() {
		var id, locID, stopType string
		var seq, dwell int
		var est time.Time
		var lat, lon *float64
		var completed *time.Time
		_ = rows.Scan(&id, &locID, &stopType, &seq, &est, &dwell, &lat, &lon, &completed)
		m := map[string]interface{}{
			"stopId": id, "locationId": locID, "stopType": stopType,
			"sequence": seq, "estimatedAt": FormatTime(est), "dwellMinutes": dwell,
		}
		if lat != nil && lon != nil {
			m["coordinate"] = models.Coordinate{Latitude: *lat, Longitude: *lon}
		}
		if completed != nil {
			m["completedAt"] = FormatTime(*completed)
		}
		out = append(out, m)
	}
	return out
}

