func (a *App) handleReadJourneyPlan(w http.ResponseWriter, r *http.Request) {
	s, me, err := a.requireRole(r.Context())
	if err != nil {
		writeErr(w, err)
		return
	}
	var req struct {
		JourneyID string `json:"journeyId"`
	}
	if err := decode(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	plan, err := a.getJourney(r.Context(), req.JourneyID)
	if err != nil {
		writeErr(w, notFound())
		return
	}
	// role-scoped views
	switch s.ActiveRole {
	case models.RoleRequester:
		// filter to requester journey plan
		sids := plan["sampleIds"].([]string)
		allowed := false
		for _, sid := range sids {
			sample, err := a.getSample(r.Context(), sid)
			if err == nil && sample.RequesterID == me.ID {
				allowed = true
				break
			}
		}
		if !allowed {
			writeErr(w, httpapi.ErrForbidden)
			return
		}
		out := map[string]interface{}{
			"journeyId": plan["journeyId"], "sampleIds": plan["sampleIds"], "legs": plan["legs"],
		}
		for _, k := range []string{"parentJourneyId", "planVersion", "routeMode", "status", "estimatedDeliveryAt", "totalCostUnits", "orderedStops"} {
			if v, ok := plan[k]; ok {
				out[k] = v
			}
		}
		writeData(w, 200, out)
		return
	case models.RoleCollectionProfessional, models.RoleDeliveryPartner, models.RoleNodeHandler, models.RoleLaboratoryTeam:
		// worker view - assigned legs only
		legs := a.journeyLegsJSON(r.Context(), req.JourneyID)
		filtered := []map[string]interface{}{}
		asgIDs := []string{}
		for _, leg := range legs {
			wid, _ := leg["workerId"].(string)
			off, _ := leg["offeredTo"].(string)
			if wid == me.ID || off == me.ID {
				filtered = append(filtered, leg)
				if id, ok := leg["assignmentId"].(string); ok {
					asgIDs = append(asgIDs, id)
				}
			}
		}
		out := map[string]interface{}{
			"journeyId": plan["journeyId"], "planVersion": plan["planVersion"],
			"routeMode": plan["routeMode"], "status": plan["status"],
			"scope": "assigned_legs", "assignmentIds": asgIDs,
			"sampleIds": plan["sampleIds"], "legs": filtered, "orderedStops": plan["orderedStops"],
			"collectionAssignmentIds": plan["collectionAssignmentIds"],
			"nodeAssignmentIds":       plan["nodeAssignmentIds"],
			"laboratoryAssignmentIds": plan["laboratoryAssignmentIds"],
			"assignedWorkerIds":       plan["assignedWorkerIds"],
		}
		if v, ok := plan["parentJourneyId"]; ok {
			out["parentJourneyId"] = v
		}
		if v, ok := plan["estimatedDeliveryAt"]; ok {
			out["estimatedDeliveryAt"] = v
		}
		writeData(w, 200, out)
		return
	default:
		writeData(w, 200, plan)
	}
}

func (a *App) handleCancelJourney(w http.ResponseWriter, r *http.Request) {
	s, _, err := a.requireAdminOrDispatcher(r.Context())
	if err != nil {
		writeErr(w, err)
		return
	}
	var req struct {
		JourneyID   string `json:"journeyId"`
		PlanVersion *int   `json:"planVersion"`
		Reason      string `json:"reason"`
	}
	if err := decode(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	plan, err := a.getJourney(r.Context(), req.JourneyID)
	if err != nil {
		writeErr(w, notFound())
		return
	}
	if req.PlanVersion != nil && plan["planVersion"].(int) != *req.PlanVersion {
		writeErr(w, httpapi.ErrConcurrent)
		return
	}
	// cancel unfinished assignments only
	_, _ = a.DB.Pool.Exec(r.Context(), `
		UPDATE assignments SET status='cancelled' WHERE journey_id=$1 AND status IN ('pending','offered','accepted','in_progress')`, req.JourneyID)
	_, _ = a.DB.Pool.Exec(r.Context(), `UPDATE journeys SET status='cancelled', plan_version = plan_version + 1 WHERE id=$1`, req.JourneyID)
	_ = a.releaseCapacityForJourney(r.Context(), req.JourneyID)
	sids := plan["sampleIds"].([]string)
	for _, sid := range sids {
		_, _ = a.DB.Pool.Exec(r.Context(), `
			UPDATE samples SET status='cancelled' WHERE id=$1 AND status NOT IN ('received','cancelled')`, sid)
	}
	a.audit(r.Context(), s.UserID, s.ActiveRole, "cancel_journey", "journey", req.JourneyID, true, map[string]interface{}{"reason": req.Reason})
	plan, _ = a.getJourney(r.Context(), req.JourneyID)
	writeData(w, 200, plan)
}

func (a *App) handleRerouteJourney(w http.ResponseWriter, r *http.Request) {
	s, _, err := a.requireAdminOrDispatcher(r.Context())
	if err != nil {
		writeErr(w, err)
		return
	}
	var req struct {
		JourneyID   string `json:"journeyId"`
		PlanVersion *int   `json:"planVersion"`
		Reason      string `json:"reason"`
	}
	if err := decode(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	plan, err := a.getJourney(r.Context(), req.JourneyID)
	if err != nil {
		writeErr(w, notFound())
		return
	}
	if req.PlanVersion != nil && plan["planVersion"].(int) != *req.PlanVersion {
		writeErr(w, httpapi.ErrConcurrent)
		return
	}
	sids := plan["sampleIds"].([]string)
	if len(sids) == 0 {
		writeErr(w, badRequest("invalid_json", "no samples"))
		return
	}
	// cancel unfinished, keep completed
	_, _ = a.DB.Pool.Exec(r.Context(), `
		UPDATE assignments SET status='cancelled' WHERE journey_id=$1 AND status IN ('pending','offered')`, req.JourneyID)
	_ = a.releaseCapacityForJourney(r.Context(), req.JourneyID)
	_, _ = a.DB.Pool.Exec(r.Context(), `
		UPDATE journeys SET status='superseded', plan_version = plan_version + 1, replan_status='replaced' WHERE id=$1`, req.JourneyID)

	sample, err := a.getSample(r.Context(), sids[0])
	if err != nil {
		writeErr(w, notFound())
		return
	}
	route, reason, _ := a.checkServiceability(r.Context(), serviceabilityInput{
		Origin: sample.Origin, OriginType: sample.OriginType, OriginNodeID: sample.OriginNodeID,
		SampleTypeID: sample.SampleTypeID, RequestedAt: Now(), DeliveryDeadline: sample.DeliveryDeadline,
		EarliestCollectionAt: Now(), LatestCollectionAt: sample.LatestCollectionAt,
	})
	if reason != "serviceable" || route == nil {
		_, _ = a.DB.Pool.Exec(r.Context(), `
			UPDATE samples SET status='expired', exception_reason=$1, exception_kind='deadline_unreachable', exception_at=$2 WHERE id=$3`,
			reason, Now(), sample.ID)
		a.audit(r.Context(), s.UserID, s.ActiveRole, "reroute_journey", "journey", req.JourneyID, false, map[string]interface{}{"reason": reason})
		writeErr(w, httpapi.E(409, "deadline_unreachable", "no valid route"))
		return
	}
	presealed := sample.Sealed
	if err := a.planJourneyForSample(r.Context(), sample.ID, route, presealed); err != nil {
		writeErr(w, errInternal)
		return
	}
	// mark parent
	newSample, _ := a.getSample(r.Context(), sample.ID)
	if newSample.ActiveJourneyID != nil {
		_, _ = a.DB.Pool.Exec(r.Context(), `UPDATE journeys SET parent_journey_id=$1 WHERE id=$2`, req.JourneyID, *newSample.ActiveJourneyID)
	}
	a.audit(r.Context(), s.UserID, s.ActiveRole, "reroute_journey", "journey", req.JourneyID, true, nil)
	if newSample.ActiveJourneyID != nil {
		plan, _ = a.getJourney(r.Context(), *newSample.ActiveJourneyID)
	}
	writeData(w, 200, plan)
}

