package app

import (
	"context"
	"net/http"
	"time"

	"labsample/internal/httpapi"
	"labsample/internal/models"
)

func (a *App) getAssignment(ctx context.Context, id string) (*models.Assignment, error) {
	asg := &models.Assignment{}
	var from, to, node, lab, worker, offered, expected *string
	var offerExp, accepted, completed *time.Time
	var declined []byte
	err := a.DB.Pool.QueryRow(ctx, `
		SELECT id, journey_id, sample_id, kind, status, sequence, from_location_id, to_location_id,
			node_id, laboratory_id, worker_id, offered_to, offer_expires_at, accepted_at, completed_at,
			declined_by, expected_sample_type_id, created_at
		FROM assignments WHERE id=$1`, id).Scan(
		&asg.ID, &asg.JourneyID, &asg.SampleID, &asg.Kind, &asg.Status, &asg.Sequence,
		&from, &to, &node, &lab, &worker, &offered, &offerExp, &accepted, &completed,
		&declined, &expected, &asg.CreatedAt)
	if err != nil {
		return nil, err
	}
	asg.FromLocationID = from
	asg.ToLocationID = to
	asg.NodeID = node
	asg.LaboratoryID = lab
	asg.WorkerID = worker
	asg.OfferedTo = offered
	asg.OfferExpiresAt = offerExp
	asg.AcceptedAt = accepted
	asg.CompletedAt = completed
	asg.DeclinedBy = FromJSON[[]string](declined)
	if asg.DeclinedBy == nil {
		asg.DeclinedBy = []string{}
	}
	asg.ExpectedSampleType = expected
	return asg, nil
}

func (a *App) offerAssignment(ctx context.Context, assignmentID string) error {
	asg, err := a.getAssignment(ctx, assignmentID)
	if err != nil {
		return err
	}
	if asg.Status != "pending" && asg.Status != "offered" {
		return nil
	}
	workerID, err := a.pickWorker(ctx, asg)
	if err != nil || workerID == "" {
		// no worker - if long enough, flag exception
		return a.maybeFlagNoWorker(ctx, asg)
	}
	exp := Now().Add(time.Duration(a.Cfg.OfferTimeoutSec) * time.Second)
	_, err = a.DB.Pool.Exec(ctx, `
		UPDATE assignments SET status='offered', offered_to=$1, offer_expires_at=$2 WHERE id=$3`,
		workerID, exp, assignmentID)
	if err != nil {
		return err
	}
	a.publishEvent(ctx, "assignment_offered", "assignment", assignmentID, map[string]interface{}{
		"workerId": workerID, "kind": asg.Kind, "sampleId": asg.SampleID,
	})
	return nil
}

func (a *App) maybeFlagNoWorker(ctx context.Context, asg *models.Assignment) error {
	// if pending/offered for > offer timeout * 3 and no worker, flag
	if time.Since(asg.CreatedAt) < time.Duration(a.Cfg.OfferTimeoutSec*3)*time.Second {
		return nil
	}
	_, _ = a.DB.Pool.Exec(ctx, `
		UPDATE samples SET status='exception', exception_reason=$1, exception_kind='no_qualified_worker', exception_at=$2
		WHERE id=$3 AND status NOT IN ('received','cancelled','exception')`,
		"no qualified worker available", Now(), asg.SampleID)
	return nil
}

func (a *App) pickWorker(ctx context.Context, asg *models.Assignment) (string, error) {
	var role string
	switch asg.Kind {
	case "collection":
		role = models.RoleCollectionProfessional
	case "transport":
		role = models.RoleDeliveryPartner
	case "node":
		role = models.RoleNodeHandler
	case "laboratory":
		role = models.RoleLaboratoryTeam
	default:
		return "", nil
	}
	rows, err := a.DB.Pool.Query(ctx, `
		SELECT id, roles, qualifications, certifications, available, capacity_units,
			decline_penalty_until, assigned_location_id
		FROM users WHERE active=true AND available=true`)
	if err != nil {
		return "", err
	}
	defer rows.Close()

	type cand struct {
		id       string
		workload int
		penalty  bool
	}
	var cands []cand
	now := Now()
	for rows.Next() {
		var id string
		var roles, quals, certs []byte
		var avail bool
		var cap int
		var penalty *time.Time
		var assigned *string
		if err := rows.Scan(&id, &roles, &quals, &certs, &avail, &cap, &penalty, &assigned); err != nil {
			continue
		}
		rlist := FromJSON[[]string](roles)
		if !ContainsStr(rlist, role) {
			continue
		}
		if ContainsStr(asg.DeclinedBy, id) {
			// temporary lower priority but still eligible after penalty
			if penalty != nil && penalty.After(now) {
				continue
			}
		}
		if asg.Kind == "node" || asg.Kind == "laboratory" {
			locID := asg.NodeID
			if asg.Kind == "laboratory" {
				locID = asg.LaboratoryID
			}
			if locID == nil || assigned == nil || *assigned != *locID {
				continue
			}
		}
		if asg.Kind == "collection" && asg.ExpectedSampleType != nil {
			st, err := a.getSampleType(ctx, *asg.ExpectedSampleType)
			if err == nil && st.QualifiedCollectorRequired {
				qlist := FromJSON[[]string](quals)
				clist := FromJSON[[]models.Certification](certs)
				ok := ContainsStr(qlist, st.RequiredQualification) || ContainsStr(qlist, st.Name)
				for _, c := range clist {
					if c.Active && (c.Code == st.RequiredQualification || c.Code == st.Name) {
						ok = true
					}
				}
				if !ok {
					continue
				}
			}
		}
		// workload
		var wl int
		_ = a.DB.Pool.QueryRow(ctx, `
			SELECT COUNT(*) FROM assignments
			WHERE (worker_id=$1 OR offered_to=$1) AND status IN ('offered','accepted','in_progress')`, id).Scan(&wl)
		if cap > 0 && wl >= cap {
			continue
		}
		cands = append(cands, cand{id: id, workload: wl, penalty: penalty != nil && penalty.After(now)})
	}
	if len(cands) == 0 {
		return "", nil
	}
	// pick lowest workload, non-penalty first
	best := cands[0]
	for _, c := range cands[1:] {
		if best.penalty && !c.penalty {
			best = c
			continue
		}
		if c.penalty == best.penalty && c.workload < best.workload {
			best = c
		}
	}
	return best.id, nil
}

func (a *App) offerNextAssignments(ctx context.Context, sampleID string) error {
	rows, err := a.DB.Pool.Query(ctx, `
		SELECT id, kind, status, sequence FROM assignments
		WHERE sample_id=$1 ORDER BY sequence`, sampleID)
	if err != nil {
		return err
	}
	defer rows.Close()
	type row struct {
		id, kind, status string
		seq              int
	}
	var list []row
	for rows.Next() {
		var r row
		_ = rows.Scan(&r.id, &r.kind, &r.status, &r.seq)
		list = append(list, r)
	}
	// find first incomplete; if previous completed, offer it
	for i, r := range list {
		if r.status == "completed" || r.status == "cancelled" {
			continue
		}
		if r.status == "pending" {
			// ensure previous done (except first)
			if i > 0 {
				prev := list[i-1]
				if prev.status != "completed" && prev.status != "cancelled" {
					// wait; but if prev is accepted/in_progress for transport chain after seal, ok to offer transport after collection complete only
					return nil
				}
			}
			return a.offerAssignment(ctx, r.id)
		}
		if r.status == "offered" || r.status == "accepted" || r.status == "in_progress" {
			return nil
		}
	}
	return nil
}

func (a *App) expireOffers(ctx context.Context) error {
	rows, err := a.DB.Pool.Query(ctx, `
		SELECT id, offered_to, declined_by FROM assignments
		WHERE status='offered' AND offer_expires_at IS NOT NULL AND offer_expires_at < NOW()`)
	if err != nil {
		return err
	}
	defer rows.Close()
	type exp struct {
		id, offered string
		declined    []byte
	}
	var list []exp
	for rows.Next() {
		var e exp
		var offered *string
		_ = rows.Scan(&e.id, &offered, &e.declined)
		if offered != nil {
			e.offered = *offered
		}
		list = append(list, e)
	}
	for _, e := range list {
		declined := FromJSON[[]string](e.declined)
		if declined == nil {
			declined = []string{}
		}
		if e.offered != "" && !ContainsStr(declined, e.offered) {
			declined = append(declined, e.offered)
		}
		_, _ = a.DB.Pool.Exec(ctx, `
			UPDATE assignments SET status='pending', offered_to=NULL, offer_expires_at=NULL, declined_by=$1::jsonb WHERE id=$2`,
			MustJSON(declined), e.id)
		// soft penalty
		if e.offered != "" {
			until := Now().Add(10 * time.Minute)
			_, _ = a.DB.Pool.Exec(ctx, `UPDATE users SET decline_penalty_until=$1 WHERE id=$2`, until, e.offered)
		}
		_ = a.offerAssignment(ctx, e.id)
	}
	return nil
}

func (a *App) handleAcceptAssignment(w http.ResponseWriter, r *http.Request) {
	s, me, err := a.requireRole(r.Context(),
		models.RoleCollectionProfessional, models.RoleDeliveryPartner,
		models.RoleNodeHandler, models.RoleLaboratoryTeam, models.RoleAdministrator)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req struct {
		AssignmentID string `json:"assignmentId"`
	}
	if err := decode(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	asg, err := a.getAssignment(r.Context(), req.AssignmentID)
	if err != nil {
		writeErr(w, notFound())
		return
	}
	if asg.Status != "offered" {
		writeErr(w, httpapi.E(409, "invalid_assignment_state", "not offered"))
		return
	}
	if asg.OfferedTo == nil || *asg.OfferedTo != me.ID {
		if s.ActiveRole != models.RoleAdministrator {
			writeErr(w, httpapi.E(403, "not_offered_to_user", "assignment offered to another worker"))
			return
		}
	}
	now := Now()
	_, err = a.DB.Pool.Exec(r.Context(), `
		UPDATE assignments SET status='accepted', worker_id=$1, accepted_at=$2, offered_to=$1 WHERE id=$3`,
		me.ID, now, asg.ID)
	if err != nil {
		writeErr(w, errInternal)
		return
	}
	// add worker to journey
	_, _ = a.DB.Pool.Exec(r.Context(), `
		UPDATE journeys SET assigned_worker_ids = (
			SELECT COALESCE(jsonb_agg(DISTINCT x), '[]'::jsonb) FROM (
				SELECT jsonb_array_elements_text(assigned_worker_ids) AS x
				UNION SELECT $1
			) s
		) WHERE id=$2`, me.ID, asg.JourneyID)
	a.audit(r.Context(), s.UserID, s.ActiveRole, "accept_assignment", "assignment", asg.ID, true, nil)
	asg, _ = a.getAssignment(r.Context(), asg.ID)
	writeData(w, 200, a.assignmentJSON(asg))
}

func (a *App) handleDeclineAssignment(w http.ResponseWriter, r *http.Request) {
	s, me, err := a.requireRole(r.Context(),
		models.RoleCollectionProfessional, models.RoleDeliveryPartner,
		models.RoleNodeHandler, models.RoleLaboratoryTeam)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req struct {
		AssignmentID string `json:"assignmentId"`
		Reason       string `json:"reason"`
	}
	if err := decode(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	asg, err := a.getAssignment(r.Context(), req.AssignmentID)
	if err != nil {
		writeErr(w, notFound())
		return
	}
	if asg.Status != "offered" || asg.OfferedTo == nil || *asg.OfferedTo != me.ID {
		writeErr(w, httpapi.E(403, "not_offered_to_user", "not offered to you"))
		return
	}
	declined := append(asg.DeclinedBy, me.ID)
	_, _ = a.DB.Pool.Exec(r.Context(), `
		UPDATE assignments SET status='pending', offered_to=NULL, offer_expires_at=NULL, declined_by=$1::jsonb WHERE id=$2`,
		MustJSON(declined), asg.ID)
	until := Now().Add(10 * time.Minute)
	_, _ = a.DB.Pool.Exec(r.Context(), `UPDATE users SET decline_penalty_until=$1 WHERE id=$2`, until, me.ID)
	_ = a.offerAssignment(r.Context(), asg.ID)
	a.audit(r.Context(), s.UserID, s.ActiveRole, "decline_assignment", "assignment", asg.ID, true, map[string]interface{}{"reason": req.Reason})
	writeData(w, 200, map[string]interface{}{"assignmentId": asg.ID, "status": "declined"})
}

func (a *App) assignmentJSON(asg *models.Assignment) map[string]interface{} {
	m := map[string]interface{}{
		"assignmentId": asg.ID,
		"journeyId":    asg.JourneyID,
		"sampleId":     asg.SampleID,
		"kind":         asg.Kind,
		"status":       asg.Status,
		"sequence":     asg.Sequence,
	}
	if asg.FromLocationID != nil {
		m["fromLocationId"] = *asg.FromLocationID
	}
	if asg.ToLocationID != nil {
		m["toLocationId"] = *asg.ToLocationID
	}
	if asg.NodeID != nil {
		m["nodeId"] = *asg.NodeID
	}
	if asg.LaboratoryID != nil {
		m["laboratoryId"] = *asg.LaboratoryID
	}
	if asg.WorkerID != nil {
		m["workerId"] = *asg.WorkerID
	}
	if asg.OfferedTo != nil {
		m["offeredTo"] = *asg.OfferedTo
	}
	if asg.OfferExpiresAt != nil {
		m["offerExpiresAt"] = FormatTime(*asg.OfferExpiresAt)
	}
	if asg.AcceptedAt != nil {
		m["acceptedAt"] = FormatTime(*asg.AcceptedAt)
	}
	return m
}

func (a *App) handleInitiateHandoff(w http.ResponseWriter, r *http.Request) {
	s, me, err := a.requireRole(r.Context(),
		models.RoleCollectionProfessional, models.RoleDeliveryPartner,
		models.RoleNodeHandler, models.RoleLaboratoryTeam, models.RoleAdministrator)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req struct {
		SampleID         string `json:"sampleId"`
		FromAssignmentID string `json:"fromAssignmentId"`
		ToAssignmentID   string `json:"toAssignmentId"`
		ReceiverID       string `json:"receiverId"`
	}
	if err := decode(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	sample, err := a.getSample(r.Context(), req.SampleID)
	if err != nil {
		writeErr(w, notFound())
		return
	}
	if !sample.Sealed {
		writeErr(w, httpapi.E(409, "not_sealed", "sample not sealed"))
		return
	}
	if sample.CurrentHolderID == nil || *sample.CurrentHolderID != me.ID {
		if s.ActiveRole != models.RoleAdministrator {
			writeErr(w, httpapi.ErrForbidden)
			return
		}
	}
	if sample.PendingHandoffID != nil {
		// return existing
		writeData(w, 200, map[string]interface{}{"handoffId": *sample.PendingHandoffID, "status": "pending"})
		return
	}
	toAsg, err := a.getAssignment(r.Context(), req.ToAssignmentID)
	if err != nil {
		writeErr(w, notFound())
		return
	}
	receiver := req.ReceiverID
	if receiver == "" && toAsg.WorkerID != nil {
		receiver = *toAsg.WorkerID
	}
	if receiver == "" && toAsg.OfferedTo != nil {
		receiver = *toAsg.OfferedTo
	}
	if receiver == "" {
		writeErr(w, badRequest("invalid_json", "receiver required"))
		return
	}
	id := NewID()
	now := Now()
	_, err = a.DB.Pool.Exec(r.Context(), `
		INSERT INTO handoffs (id, sample_id, from_assignment_id, to_assignment_id, sender_id, receiver_id, status, sender_confirmed, initiated_at)
		VALUES ($1,$2,$3,$4,$5,$6,'pending',true,$7)`,
		id, sample.ID, req.FromAssignmentID, req.ToAssignmentID, me.ID, receiver, now)
	if err != nil {
		writeErr(w, errInternal)
		return
	}
	_, _ = a.DB.Pool.Exec(r.Context(), `UPDATE samples SET pending_handoff_id=$1 WHERE id=$2`, id, sample.ID)
	a.audit(r.Context(), s.UserID, s.ActiveRole, "initiate_handoff", "handoff", id, true, nil)
	writeData(w, 200, map[string]interface{}{
		"handoffId": id, "status": "pending", "senderConfirmed": true, "receiverConfirmed": false,
	})
}

func (a *App) handleConfirmHandoff(w http.ResponseWriter, r *http.Request) {
	s, me, err := a.requireRole(r.Context(),
		models.RoleCollectionProfessional, models.RoleDeliveryPartner,
		models.RoleNodeHandler, models.RoleLaboratoryTeam, models.RoleAdministrator)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req struct {
		HandoffID string `json:"handoffId"`
		AsRole    string `json:"as"` // sender|receiver
	}
	if err := decode(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	var id, sampleID, senderID, receiverID, status string
	var senderConf, receiverConf bool
	var fromAsg, toAsg string
	err = a.DB.Pool.QueryRow(r.Context(), `
		SELECT id, sample_id, from_assignment_id, to_assignment_id, sender_id, receiver_id, status, sender_confirmed, receiver_confirmed
		FROM handoffs WHERE id=$1`, req.HandoffID).Scan(
		&id, &sampleID, &fromAsg, &toAsg, &senderID, &receiverID, &status, &senderConf, &receiverConf)
	if err != nil {
		writeErr(w, notFound())
		return
	}
	if status == "confirmed" {
		writeData(w, 200, map[string]interface{}{"handoffId": id, "status": "confirmed", "senderConfirmed": true, "receiverConfirmed": true})
		return
	}
	asRole := req.AsRole
	if asRole == "" {
		if me.ID == receiverID {
			asRole = "receiver"
		} else if me.ID == senderID {
			asRole = "sender"
		}
	}
	if asRole == "sender" {
		if me.ID != senderID && s.ActiveRole != models.RoleAdministrator {
			writeErr(w, httpapi.ErrForbidden)
			return
		}
		senderConf = true
		_, _ = a.DB.Pool.Exec(r.Context(), `UPDATE handoffs SET sender_confirmed=true WHERE id=$1`, id)
	} else {
		if me.ID != receiverID && s.ActiveRole != models.RoleAdministrator {
			writeErr(w, httpapi.ErrForbidden)
			return
		}
		receiverConf = true
		_, _ = a.DB.Pool.Exec(r.Context(), `UPDATE handoffs SET receiver_confirmed=true WHERE id=$1`, id)
	}
	if senderConf && receiverConf {
		now := Now()
		_, _ = a.DB.Pool.Exec(r.Context(), `
			UPDATE handoffs SET status='confirmed', confirmed_at=$1, sender_confirmed=true, receiver_confirmed=true WHERE id=$2`, now, id)
		_, _ = a.DB.Pool.Exec(r.Context(), `
			UPDATE samples SET current_holder_id=$1, pending_handoff_id=NULL, status='in_transit', location_recorded_at=$2 WHERE id=$3`,
			receiverID, now, sampleID)
		// complete from assignment if still open, accept to assignment
		_, _ = a.DB.Pool.Exec(r.Context(), `
			UPDATE assignments SET status='completed', completed_at=$1 WHERE id=$2 AND status IN ('accepted','in_progress','offered')`, now, fromAsg)
		_, _ = a.DB.Pool.Exec(r.Context(), `
			UPDATE assignments SET status='accepted', worker_id=$1, accepted_at=COALESCE(accepted_at,$2) WHERE id=$3 AND status IN ('pending','offered','accepted')`,
			receiverID, now, toAsg)
		_ = a.offerNextAssignments(r.Context(), sampleID)
		a.audit(r.Context(), s.UserID, s.ActiveRole, "confirm_handoff", "handoff", id, true, map[string]interface{}{"complete": true})
		writeData(w, 200, map[string]interface{}{"handoffId": id, "status": "confirmed", "senderConfirmed": true, "receiverConfirmed": true})
		return
	}
	a.audit(r.Context(), s.UserID, s.ActiveRole, "confirm_handoff", "handoff", id, true, map[string]interface{}{"complete": false})
	writeData(w, 200, map[string]interface{}{
		"handoffId": id, "status": "pending", "senderConfirmed": senderConf, "receiverConfirmed": receiverConf,
	})
}

func (a *App) handleUpdateAssignmentProgress(w http.ResponseWriter, r *http.Request) {
	s, me, err := a.requireRole(r.Context(),
		models.RoleCollectionProfessional, models.RoleDeliveryPartner,
		models.RoleNodeHandler, models.RoleLaboratoryTeam, models.RoleAdministrator)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req struct {
		AssignmentID string `json:"assignmentId"`
		Status       string `json:"status"`
		Note         string `json:"note"`
	}
	if err := decode(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	asg, err := a.getAssignment(r.Context(), req.AssignmentID)
	if err != nil {
		writeErr(w, notFound())
		return
	}
	if asg.WorkerID == nil || *asg.WorkerID != me.ID {
		if s.ActiveRole != models.RoleAdministrator {
			writeErr(w, httpapi.ErrForbidden)
			return
		}
	}
	status := req.Status
	if status == "" {
		status = "in_progress"
	}
	_, err = a.DB.Pool.Exec(r.Context(), `UPDATE assignments SET status=$1 WHERE id=$2`, status, asg.ID)
	if err != nil {
		writeErr(w, errInternal)
		return
	}
	a.audit(r.Context(), s.UserID, s.ActiveRole, "update_assignment_progress", "assignment", asg.ID, true, map[string]interface{}{"status": status, "note": req.Note})
	asg, _ = a.getAssignment(r.Context(), asg.ID)
	writeData(w, 200, a.assignmentJSON(asg))
}

func (a *App) handleRecordWorkerLocation(w http.ResponseWriter, r *http.Request) {
	s, me, err := a.requireRole(r.Context(),
		models.RoleCollectionProfessional, models.RoleDeliveryPartner,
		models.RoleNodeHandler, models.RoleLaboratoryTeam)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req struct {
		AssignmentID string            `json:"assignmentId"`
		Coordinate   models.Coordinate `json:"coordinate"`
		Sequence     *int              `json:"sequence"`
	}
	if err := decode(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	asg, err := a.getAssignment(r.Context(), req.AssignmentID)
	if err != nil {
		writeErr(w, notFound())
		return
	}
	if asg.WorkerID == nil || *asg.WorkerID != me.ID {
		writeErr(w, httpapi.ErrForbidden)
		return
	}
	now := Now()
	seq := 0
	if req.Sequence != nil {
		seq = *req.Sequence
	} else {
		_ = a.DB.Pool.QueryRow(r.Context(), `
			SELECT COALESCE(MAX(sequence),0)+1 FROM worker_location_updates WHERE assignment_id=$1`, asg.ID).Scan(&seq)
	}
	_, _ = a.DB.Pool.Exec(r.Context(), `
		INSERT INTO worker_location_updates (assignment_id, worker_id, lat, lon, sequence, recorded_at)
		VALUES ($1,$2,$3,$4,$5,$6)`,
		asg.ID, me.ID, req.Coordinate.Latitude, req.Coordinate.Longitude, seq, now)
	_, _ = a.DB.Pool.Exec(r.Context(), `
		UPDATE users SET latest_lat=$1, latest_lon=$2, location_recorded_at=$3 WHERE id=$4`,
		req.Coordinate.Latitude, req.Coordinate.Longitude, now, me.ID)
	// update sample location if holding
	_, _ = a.DB.Pool.Exec(r.Context(), `
		UPDATE samples SET latest_lat=$1, latest_lon=$2, location_recorded_at=$3
		WHERE current_holder_id=$4 AND id=$5`,
		req.Coordinate.Latitude, req.Coordinate.Longitude, now, me.ID, asg.SampleID)
	a.audit(r.Context(), s.UserID, s.ActiveRole, "record_worker_location", "assignment", asg.ID, true, nil)
	writeData(w, 200, map[string]interface{}{
		"assignmentId": asg.ID, "coordinate": req.Coordinate, "sequence": seq, "recordedAt": FormatTime(now),
	})
}

