package app

import (
	"net/http"
	"time"

	"labsample/internal/models"
)

func (a *App) handleListRoleWork(w http.ResponseWriter, r *http.Request) {
	s, me, err := a.requireRole(r.Context())
	if err != nil {
		writeErr(w, err)
		return
	}
	var req struct {
		Role *string `json:"role"`
	}
	_ = decode(r, &req)

	pending := []map[string]interface{}{}
	inProgress := []map[string]interface{}{}
	completed := []map[string]interface{}{}

	switch s.ActiveRole {
	case models.RoleRequester:
		rows, err := a.DB.Pool.Query(r.Context(), `
			SELECT id, status, request_id, delivery_deadline, active_journey_id FROM samples WHERE requester_id=$1 ORDER BY created_at DESC`, me.ID)
		if err == nil {
			defer rows.Close()
			for rows.Next() {
				var id, status, reqID string
				var deadline time.Time
				var jid *string
				_ = rows.Scan(&id, &status, &reqID, &deadline, &jid)
				item := map[string]interface{}{
					"type": "sample", "sampleId": id, "requestId": reqID, "status": status,
					"deliveryDeadline": FormatTime(deadline),
				}
				if jid != nil {
					item["journeyId"] = *jid
				}
				switch status {
				case "received", "cancelled", "expired":
					completed = append(completed, item)
				case "requested", "planned", "unserviceable":
					pending = append(pending, item)
				default:
					inProgress = append(inProgress, item)
				}
			}
		}
	case models.RoleAdministrator, models.RoleDispatcher:
		rows, err := a.DB.Pool.Query(r.Context(), `
			SELECT id, status, request_id, delivery_deadline, active_journey_id FROM samples ORDER BY created_at DESC LIMIT 500`)
		if err == nil {
			defer rows.Close()
			for rows.Next() {
				var id, status, reqID string
				var deadline time.Time
				var jid *string
				_ = rows.Scan(&id, &status, &reqID, &deadline, &jid)
				item := map[string]interface{}{
					"type": "sample", "sampleId": id, "requestId": reqID, "status": status,
					"deliveryDeadline": FormatTime(deadline),
				}
				if jid != nil {
					item["journeyId"] = *jid
				}
				switch status {
				case "received", "cancelled", "expired":
					completed = append(completed, item)
				case "requested", "planned", "unserviceable", "exception":
					pending = append(pending, item)
				default:
					inProgress = append(inProgress, item)
				}
			}
		}
	default:
		// worker assignments
		rows, err := a.DB.Pool.Query(r.Context(), `
			SELECT id, journey_id, sample_id, kind, status, sequence FROM assignments
			WHERE worker_id=$1 OR offered_to=$1 ORDER BY created_at DESC LIMIT 500`, me.ID)
		if err == nil {
			defer rows.Close()
			for rows.Next() {
				var id, jid, sid, kind, status string
				var seq int
				_ = rows.Scan(&id, &jid, &sid, &kind, &status, &seq)
				item := map[string]interface{}{
					"type": "assignment", "assignmentId": id, "journeyId": jid,
					"sampleId": sid, "kind": kind, "status": status, "sequence": seq,
				}
				switch status {
				case "completed", "cancelled":
					completed = append(completed, item)
				case "offered", "pending":
					pending = append(pending, item)
				default:
					inProgress = append(inProgress, item)
				}
			}
		}
	}
	writeData(w, 200, map[string]interface{}{
		"pending": pending, "inProgress": inProgress, "completed": completed,
	})
}

func (a *App) handleReadOperationsState(w http.ResponseWriter, r *http.Request) {
	s, _, err := a.requireAdminOrDispatcher(r.Context())
	if err != nil {
		writeErr(w, err)
		return
	}
	_ = s
	_ = decode(r, &struct{}{})

	// samples
	samples := []map[string]interface{}{}
	rows, err := a.DB.Pool.Query(r.Context(), `
		SELECT id, status, request_id, origin_lat, origin_lon, delivery_deadline,
			current_holder_id, active_journey_id, latest_lat, latest_lon, location_recorded_at
		FROM samples ORDER BY created_at DESC LIMIT 1000`)
	if err == nil {
		defer rows.Close()
		for rows.Next() {
			var id, status, reqID string
			var olat, olon float64
			var deadline time.Time
			var holder, jid *string
			var lat, lon *float64
			var locAt *time.Time
			_ = rows.Scan(&id, &status, &reqID, &olat, &olon, &deadline, &holder, &jid, &lat, &lon, &locAt)
			stale := locAt == nil || time.Since(*locAt) > time.Duration(a.Cfg.LocationStaleSec)*time.Second
			m := map[string]interface{}{
				"sampleId": id, "status": status, "locationStale": stale,
				"requestId": reqID, "origin": models.Coordinate{Latitude: olat, Longitude: olon},
				"deliveryDeadline": FormatTime(deadline),
			}
			if holder != nil {
				m["currentHolderId"] = *holder
			}
			if jid != nil {
				m["activeJourneyId"] = *jid
			}
			if lat != nil && lon != nil {
				m["latestLocation"] = models.Coordinate{Latitude: *lat, Longitude: *lon}
			}
			if locAt != nil {
				m["locationRecordedAt"] = FormatTime(*locAt)
			}
			samples = append(samples, m)
		}
	}

	// workers
	workers := []map[string]interface{}{}
	wrows, err := a.DB.Pool.Query(r.Context(), `
		SELECT id, full_name, roles, available, latest_lat, latest_lon, location_recorded_at
		FROM users WHERE active=true`)
	if err == nil {
		defer wrows.Close()
		for wrows.Next() {
			var id, name string
			var roles []byte
			var avail bool
			var lat, lon *float64
			var locAt *time.Time
			_ = wrows.Scan(&id, &name, &roles, &avail, &lat, &lon, &locAt)
			m := map[string]interface{}{
				"workerId": id, "fullName": name, "roles": FromJSON[[]string](roles), "available": avail,
			}
			if lat != nil && lon != nil {
				m["latestLocation"] = models.Coordinate{Latitude: *lat, Longitude: *lon}
			}
			if locAt != nil {
				m["locationRecordedAt"] = FormatTime(*locAt)
				m["locationStale"] = time.Since(*locAt) > time.Duration(a.Cfg.LocationStaleSec)*time.Second
			} else {
				m["locationStale"] = true
			}
			workers = append(workers, m)
		}
	}

	// locations
	locations := []map[string]interface{}{}
	lrows, err := a.DB.Pool.Query(r.Context(), `
		SELECT id, name, latitude, longitude, active, fn_collection_point, fn_transfer_point, fn_hub, fn_laboratory,
			capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
		FROM locations`)
	if err == nil {
		defer lrows.Close()
		for lrows.Next() {
			var id, name string
			var lat, lon float64
			var active, cp, tp, hub, lab bool
			var cu, ru, ccu, cru int
			_ = lrows.Scan(&id, &name, &lat, &lon, &active, &cp, &tp, &hub, &lab, &cu, &ru, &ccu, &cru)
			cap := models.Capacity{
				CapacityUnits: cu, ReservedUnits: ru, CooledCapacityUnits: ccu, CooledReservedUnits: cru,
			}.WithAvailable()
			locations = append(locations, map[string]interface{}{
				"locationId": id, "name": name,
				"coordinate": models.Coordinate{Latitude: lat, Longitude: lon},
				"active": active,
				"functions": models.LocationFunctions{CollectionPoint: cp, TransferPoint: tp, Hub: hub, Laboratory: lab},
				"capacity": cap,
			})
		}
	}

	// connections
	connections := []map[string]interface{}{}
	crows, err := a.DB.Pool.Query(r.Context(), `
		SELECT id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active,
			capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
		FROM connections`)
	if err == nil {
		defer crows.Close()
		for crows.Next() {
			var id, from, to string
			var mins int
			var cost float64
			var cooled, active bool
			var cu, ru, ccu, cru int
			_ = crows.Scan(&id, &from, &to, &mins, &cost, &cooled, &active, &cu, &ru, &ccu, &cru)
			cap := models.Capacity{
				CapacityUnits: cu, ReservedUnits: ru, CooledCapacityUnits: ccu, CooledReservedUnits: cru,
			}.WithAvailable()
			connections = append(connections, map[string]interface{}{
				"connectionId": id, "fromLocationId": from, "toLocationId": to,
				"travelMinutes": mins, "costUnits": cost, "cooled": cooled, "active": active, "capacity": cap,
			})
		}
	}

	// exceptions
	exceptions := []map[string]interface{}{}
	erows, err := a.DB.Pool.Query(r.Context(), `
		SELECT id, exception_reason, exception_kind, exception_at, status FROM samples
		WHERE status='exception' OR exception_reason IS NOT NULL ORDER BY exception_at DESC NULLS LAST LIMIT 200`)
	if err == nil {
		defer erows.Close()
		for erows.Next() {
			var id, status string
			var reason, kind *string
			var at *time.Time
			_ = erows.Scan(&id, &reason, &kind, &at, &status)
			m := map[string]interface{}{"sampleId": id, "status": status}
			if reason != nil {
				m["reason"] = *reason
			}
			if kind != nil {
				m["kind"] = *kind
			}
			if at != nil {
				m["at"] = FormatTime(*at)
			}
			exceptions = append(exceptions, m)
		}
	}

	// journeys summary
	journeys := []map[string]interface{}{}
	jrows, err := a.DB.Pool.Query(r.Context(), `
		SELECT id, status, route_mode, plan_version, sample_ids FROM journeys ORDER BY created_at DESC LIMIT 200`)
	if err == nil {
		defer jrows.Close()
		for jrows.Next() {
			var id, status, mode string
			var ver int
			var sids []byte
			_ = jrows.Scan(&id, &status, &mode, &ver, &sids)
			journeys = append(journeys, map[string]interface{}{
				"journeyId": id, "status": status, "routeMode": mode, "planVersion": ver,
				"sampleIds": FromJSON[[]string](sids),
			})
		}
	}

	writeData(w, 200, map[string]interface{}{
		"samples": samples, "workers": workers, "locations": locations,
		"connections": connections, "exceptions": exceptions, "journeys": journeys,
	})
}

func (a *App) handleReportDisruption(w http.ResponseWriter, r *http.Request) {
	s, _, err := a.requireAdminOrDispatcher(r.Context())
	if err != nil {
		writeErr(w, err)
		return
	}
	var req struct {
		ResourceType string `json:"resourceType"`
		ResourceID   string `json:"resourceId"`
		Reason       string `json:"reason"`
		AutoReplan   *bool  `json:"autoReplan"`
	}
	if err := decode(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	// deactivate resource
	switch req.ResourceType {
	case "location", "node", "laboratory":
		_, _ = a.DB.Pool.Exec(r.Context(), `UPDATE locations SET active=false WHERE id=$1`, req.ResourceID)
	case "connection", "route":
		_, _ = a.DB.Pool.Exec(r.Context(), `UPDATE connections SET active=false WHERE id=$1`, req.ResourceID)
	case "worker":
		_, _ = a.DB.Pool.Exec(r.Context(), `UPDATE users SET available=false WHERE id=$1`, req.ResourceID)
	}
	_ = a.bumpNetworkRevision(r.Context())

	// find affected samples
	affected := []string{}
	replacements := []string{}
	rows, err := a.DB.Pool.Query(r.Context(), `
		SELECT DISTINCT s.id, s.active_journey_id FROM samples s
		JOIN assignments a ON a.sample_id = s.id
		WHERE s.status NOT IN ('received','cancelled','expired')
		AND (
			a.worker_id::text=$1 OR a.offered_to::text=$1 OR a.from_location_id::text=$1
			OR a.to_location_id::text=$1 OR a.node_id::text=$1 OR a.laboratory_id::text=$1
			OR EXISTS (SELECT 1 FROM capacity_reservations cr WHERE cr.sample_id=s.id AND cr.resource_id::text=$1 AND cr.active)
		)`, req.ResourceID)
	if err == nil {
		defer rows.Close()
		for rows.Next() {
			var sid string
			var jid *string
			_ = rows.Scan(&sid, &jid)
			affected = append(affected, sid)
			if jid != nil {
				// replan
				sample, err := a.getSample(r.Context(), sid)
				if err != nil {
					continue
				}
				// keep holder, cancel unfinished only
				_, _ = a.DB.Pool.Exec(r.Context(), `
					UPDATE assignments SET status='cancelled'
					WHERE journey_id=$1 AND status IN ('pending','offered')`, *jid)
				_ = a.releaseCapacityForJourney(r.Context(), *jid)
				_, _ = a.DB.Pool.Exec(r.Context(), `
					UPDATE journeys SET status='superseded', replan_status='replaced', plan_version=plan_version+1 WHERE id=$1`, *jid)
				route, reason, _ := a.checkServiceability(r.Context(), serviceabilityInput{
					Origin: sample.Origin, OriginType: sample.OriginType, OriginNodeID: sample.OriginNodeID,
					SampleTypeID: sample.SampleTypeID, RequestedAt: Now(), DeliveryDeadline: sample.DeliveryDeadline,
					EarliestCollectionAt: Now(), LatestCollectionAt: sample.LatestCollectionAt,
				})
				if reason == "serviceable" && route != nil {
					_ = a.planJourneyForSample(r.Context(), sid, route, sample.Sealed)
					ns, _ := a.getSample(r.Context(), sid)
					if ns != nil && ns.ActiveJourneyID != nil {
						_, _ = a.DB.Pool.Exec(r.Context(), `UPDATE journeys SET parent_journey_id=$1 WHERE id=$2`, *jid, *ns.ActiveJourneyID)
						replacements = append(replacements, *ns.ActiveJourneyID)
					}
				} else {
					_, _ = a.DB.Pool.Exec(r.Context(), `
						UPDATE samples SET status='expired', exception_reason=$1, exception_kind='deadline_unreachable', exception_at=$2 WHERE id=$3`,
