package app

import (
	"encoding/json"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"time"

	"labsample/internal/httpapi"
	"labsample/internal/models"
)

func (a *App) registerRoutes(mux *http.ServeMux) {
	// readiness
	mux.HandleFunc("GET /ready", a.handleReady)

	// auth
	mux.HandleFunc("POST /api/authenticate-user", a.handleAuthenticate)
	mux.HandleFunc("POST /api/select-active-role", a.handleSelectRole)

	// users
	mux.HandleFunc("POST /api/create-user", a.handleCreateUser)
	mux.HandleFunc("POST /api/update-user-access", a.handleUpdateUserAccess)
	mux.HandleFunc("GET /api/read-user/{userId}", a.handleReadUser)
	mux.HandleFunc("POST /api/set-worker-availability", a.handleSetWorkerAvailability)

	// network
	mux.HandleFunc("POST /api/create-location", a.handleCreateLocation)
	mux.HandleFunc("POST /api/update-location", a.handleUpdateLocation)
	mux.HandleFunc("POST /api/set-location-status", a.handleSetLocationStatus)
	mux.HandleFunc("POST /api/set-location-function-status", a.handleSetLocationFunctionStatus)
	mux.HandleFunc("POST /api/create-connection", a.handleCreateConnection)
	mux.HandleFunc("POST /api/set-connection-status", a.handleSetConnectionStatus)
	mux.HandleFunc("POST /api/configure-capacity", a.handleConfigureCapacity)
	mux.HandleFunc("POST /api/configure-laboratory-acceptance", a.handleConfigureLabAcceptance)

	// sample types
	mux.HandleFunc("POST /api/create-sample-type", a.handleCreateSampleType)
	mux.HandleFunc("POST /api/update-sample-type", a.handleUpdateSampleType)

	// serviceability / requests
	mux.HandleFunc("POST /api/check-serviceability", a.handleCheckServiceability)
	mux.HandleFunc("POST /api/read-serviceability-snapshot", a.handleReadServiceabilitySnapshot)
	mux.HandleFunc("POST /api/create-collection-request", a.handleCreateCollectionRequest)
	mux.HandleFunc("POST /api/ingest-presealed-sample", a.handleIngestPresealed)

	// samples
	mux.HandleFunc("GET /api/read-sample-state/{sampleId}", a.handleReadSampleState)
	mux.HandleFunc("POST /api/read-sample-lifecycle", a.handleReadSampleLifecycle)
	mux.HandleFunc("POST /api/collect-and-seal-sample", a.handleCollectAndSeal)
	mux.HandleFunc("POST /api/confirm-laboratory-receipt", a.handleConfirmLabReceipt)
	mux.HandleFunc("POST /api/record-laboratory-exception", a.handleRecordLabException)
	mux.HandleFunc("POST /api/record-handling-checkpoint", a.handleRecordHandlingCheckpoint)

	// assignments / handoffs
	mux.HandleFunc("POST /api/accept-assignment", a.handleAcceptAssignment)
	mux.HandleFunc("POST /api/decline-assignment", a.handleDeclineAssignment)
	mux.HandleFunc("POST /api/initiate-handoff", a.handleInitiateHandoff)
	mux.HandleFunc("POST /api/confirm-handoff", a.handleConfirmHandoff)
	mux.HandleFunc("POST /api/update-assignment-progress", a.handleUpdateAssignmentProgress)
	mux.HandleFunc("POST /api/record-worker-location", a.handleRecordWorkerLocation)

	// journeys
	mux.HandleFunc("POST /api/read-journey-plan", a.handleReadJourneyPlan)
	mux.HandleFunc("POST /api/cancel-journey", a.handleCancelJourney)
	mux.HandleFunc("POST /api/reroute-journey", a.handleRerouteJourney)
	mux.HandleFunc("POST /api/edit-active-plan", a.handleEditActivePlan)
	mux.HandleFunc("POST /api/split-journey", a.handleSplitJourney)
	mux.HandleFunc("POST /api/merge-journeys", a.handleMergeJourneys)

	// ops
	mux.HandleFunc("POST /api/list-role-work", a.handleListRoleWork)
	mux.HandleFunc("POST /api/read-operations-state", a.handleReadOperationsState)
	mux.HandleFunc("POST /api/report-disruption", a.handleReportDisruption)
	mux.HandleFunc("POST /api/search-audit-trail", a.handleSearchAudit)

	// ui / events
	mux.HandleFunc("GET /api/ui/bootstrap", a.handleUIBootstrap)
	mux.HandleFunc("GET /api/events", a.handleEvents)

	// map assets
	mux.HandleFunc("GET /map/", a.handleMapAssets)

	// frontend static
	mux.HandleFunc("/", a.handleFrontend)
}

func (a *App) handleReady(w http.ResponseWriter, r *http.Request) {
	if !a.IsReady() {
		httpapi.WriteJSON(w, 503, map[string]string{"status": "not_ready"})
		return
	}
	httpapi.WriteJSON(w, 200, map[string]string{"status": "ready"})
}

func (a *App) handleEvents(w http.ResponseWriter, r *http.Request) {
	s := SessionFrom(r.Context())
	if s == nil {
		// middleware should have auth'd
		writeErr(w, errUnauthorized())
		return
	}
	flusher, ok := w.(http.Flusher)
	if !ok {
		writeErr(w, errInternal)
		return
	}
	w.Header().Set("Content-Type", "text/event-stream")
	w.Header().Set("Cache-Control", "no-cache")
	w.Header().Set("Connection", "keep-alive")
	ch := a.subscribe()
	defer a.unsubscribe(ch)

	// send hello
	hello, _ := json.Marshal(map[string]interface{}{"type": "connected", "at": FormatTime(Now())})
	_, _ = w.Write([]byte("data: " + string(hello) + "\n\n"))
	flusher.Flush()

	ticker := time.NewTicker(15 * time.Second)
	defer ticker.Stop()
	ctx := r.Context()
	for {
		select {
		case <-ctx.Done():
			return
		case ev, ok := <-ch:
			if !ok {
				return
			}
			b, _ := json.Marshal(ev)
			_, _ = w.Write([]byte("data: " + string(b) + "\n\n"))
			flusher.Flush()
		case <-ticker.C:
			_, _ = w.Write([]byte(": ping\n\n"))
			flusher.Flush()
		}
	}
}

func (a *App) handleMapAssets(w http.ResponseWriter, r *http.Request) {
	rel := strings.TrimPrefix(r.URL.Path, "/map/")
	if rel == "" || strings.Contains(rel, "..") {
		http.NotFound(w, r)
		return
	}
	base := a.Cfg.MapAssetsDir
	full := filepath.Join(base, rel)
	// also try common layout
	if _, err := os.Stat(full); err != nil {
		alts := []string{
			filepath.Join(base, "pmtiles", rel),
			filepath.Join("/opt/arena/map-assets", rel),
			filepath.Join("/workspace/map-assets", rel),
		}
		found := false
		for _, alt := range alts {
			if _, err := os.Stat(alt); err == nil {
				full = alt
				found = true
				break
			}
		}
		if !found {
			http.NotFound(w, r)
			return
		}
	}
	// content types
	switch {
	case strings.HasSuffix(full, ".json"):
		w.Header().Set("Content-Type", "application/json")
	case strings.HasSuffix(full, ".pmtiles"):
		w.Header().Set("Content-Type", "application/octet-stream")
	case strings.HasSuffix(full, ".pbf"):
		w.Header().Set("Content-Type", "application/x-protobuf")
	case strings.HasSuffix(full, ".png"):
		w.Header().Set("Content-Type", "image/png")
	}
	http.ServeFile(w, r, full)
}

func (a *App) handleFrontend(w http.ResponseWriter, r *http.Request) {
	if strings.HasPrefix(r.URL.Path, "/api/") {
		http.NotFound(w, r)
		return
	}
	root := a.Cfg.StaticDir
	path := r.URL.Path
	if path == "/" {
		path = "/index.html"
	}
	full := filepath.Join(root, path)
	if _, err := os.Stat(full); err != nil {
		// SPA fallback
		index := filepath.Join(root, "index.html")
		if _, err2 := os.Stat(index); err2 == nil {
			http.ServeFile(w, r, index)
			return
		}
		// minimal fallback HTML if frontend not built
		w.Header().Set("Content-Type", "text/html; charset=utf-8")
		_, _ = io.WriteString(w, minimalHTML)
		return
	}
	http.ServeFile(w, r, full)
}

const minimalHTML = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8"/>
<meta name="viewport" content="width=device-width, initial-scale=1.0"/>
<title>Lab Sample Pickup & Delivery</title>
<link href="https://unpkg.com/maplibre-gl@4.7.1/dist/maplibre-gl.css" rel="stylesheet"/>
<style>
:root{--bg:#0f172a;--card:#1e293b;--accent:#38bdf8;--text:#e2e8f0;--muted:#94a3b8;--ok:#22c55e;--bad:#ef4444}
*{box-sizing:border-box}body{margin:0;font-family:system-ui,sans-serif;background:var(--bg);color:var(--text)}
header{display:flex;align-items:center;gap:1rem;padding:.75rem 1.25rem;background:#020617;border-bottom:1px solid #334155}
header h1{font-size:1.1rem;margin:0;font-weight:600}
nav{display:flex;gap:.5rem;flex-wrap:wrap}
nav button,button.primary,button{background:var(--card);color:var(--text);border:1px solid #475569;border-radius:6px;padding:.4rem .75rem;cursor:pointer}
button.primary{background:var(--accent);color:#0f172a;border-color:var(--accent);font-weight:600}
button:hover{filter:brightness(1.1)}
main{display:grid;grid-template-columns:320px 1fr;height:calc(100vh - 54px)}
aside{border-right:1px solid #334155;overflow:auto;padding:1rem;background:#0b1220}
section.view{overflow:auto;padding:1rem;position:relative}
#map{position:absolute;inset:0}
.card{background:var(--card);border:1px solid #334155;border-radius:8px;padding:1rem;margin-bottom:1rem}
.card h2{margin:0 0 .75rem;font-size:1rem}
label{display:block;font-size:.75rem;color:var(--muted);margin:.4rem 0 .15rem}
input,select,textarea{width:100%;padding:.45rem .55rem;border-radius:6px;border:1px solid #475569;background:#020617;color:var(--text)}
.row{display:flex;gap:.5rem}.row>*{flex:1}
.msg{font-size:.85rem;margin-top:.5rem;color:var(--muted)}
.msg.ok{color:var(--ok)}.msg.err{color:var(--bad)}
table{width:100%;border-collapse:collapse;font-size:.85rem}
th,td{text-align:left;padding:.35rem .4rem;border-bottom:1px solid #334155}
.badge{display:inline-block;padding:.1rem .4rem;border-radius:999px;font-size:.7rem;background:#334155}
.hidden{display:none}
.login-wrap{max-width:380px;margin:10vh auto;padding:1.5rem}
#map-panel{position:relative;min-height:100%}
</style>
</head>
<body>
<div id="app"></div>
<script src="https://unpkg.com/maplibre-gl@4.7.1/dist/maplibre-gl.js"></script>
<script>
const API='/api';
let token='', user=null, activeRole='', bootstrap=null, map=null;

async function api(path, opts={}){
  const headers=Object.assign({'Content-Type':'application/json'}, opts.headers||{});
  if(token) headers['Authorization']='Bearer '+token;
  const res=await fetch(API+path, Object.assign({}, opts, {headers, body: opts.body?JSON.stringify(opts.body):undefined}));
  const text=await res.text();
  let data=null; try{data=JSON.parse(text)}catch(e){data={error:text}}
  if(!res.ok) throw Object.assign(new Error(data.error||res.statusText), {code:data.code, status:res.status, data});
  return data.data!==undefined?data.data:data;
}

function el(tag, attrs={}, children=[]){
  const e=document.createElement(tag);
  Object.entries(attrs).forEach(([k,v])=>{
    if(k==='className') e.className=v;
    else if(k==='onclick') e.onclick=v;
    else if(k.startsWith('on')) e.addEventListener(k.slice(2).toLowerCase(), v);
    else if(k==='text') e.textContent=v;
    else e.setAttribute(k,v);
  });
  (Array.isArray(children)?children:[children]).forEach(c=>{
    if(c==null) return;
    if(typeof c==='string') e.appendChild(document.createTextNode(c));
    else e.appendChild(c);
  });
  return e;
}

function renderLogin(){
  const root=document.getElementById('app'); root.innerHTML='';
  const msg=el('div',{className:'msg'});
  const userI=el('input',{id:'u', value:'admin'});
  const passI=el('input',{id:'p', type:'password', value:'admin'});
  const btn=el('button',{className:'primary', text:'Sign in', onclick:async()=>{
    msg.className='msg'; msg.textContent='Signing in...';
    try{
      const d=await api('/authenticate-user',{method:'POST', body:{username:userI.value, password:passI.value}});
      token=d.sessionToken; user={userId:d.userId, roles:d.roles}; activeRole=d.activeRole||'';
      localStorage.setItem('ls_token', token);
      if(!activeRole && d.roles && d.roles.length){
        activeRole=d.roles.includes('administrator')?'administrator':d.roles[0];
        await api('/select-active-role',{method:'POST', body:{role:activeRole}});
      }
      await loadApp();
    }catch(e){ msg.className='msg err'; msg.textContent=e.message||'Login failed'; }
  }});
  root.appendChild(el('div',{className:'login-wrap card'},[
    el('h2',{text:'Lab Sample Pickup & Delivery'}),
    el('label',{text:'Username'}), userI,
    el('label',{text:'Password'}), passI,
    el('div',{style:'margin-top:1rem'},[btn]), msg
  ]));
}

async function loadApp(){
  try{ bootstrap=await api('/ui/bootstrap'); activeRole=bootstrap.activeRole||activeRole; user=bootstrap.user; }
  catch(e){ token=''; localStorage.removeItem('ls_token'); return renderLogin(); }
  renderShell();
}

function renderShell(){
  const root=document.getElementById('app'); root.innerHTML='';
  const views={
    dashboard: renderDashboard,
    request: renderRequest,
    work: renderWork,
    ops: renderOps,
    network: renderNetwork,
    audit: renderAudit,
    users: renderUsers,
  };
  let current='dashboard';
  const main=el('main');
  const aside=el('aside');
  const section=el('section',{className:'view', id:'view'});
  const mapPanel=el('div',{id:'map-panel', className:'hidden'});
  mapPanel.appendChild(el('div',{id:'map'}));
  section.appendChild(mapPanel);
  const content=el('div',{id:'content'});
  section.appendChild(content);
  main.append(aside, section);

  const roleSel=el('select',{onchange:async(e)=>{
    try{ const d=await api('/select-active-role',{method:'POST', body:{role:e.target.value}}); activeRole=d.activeRole; bootstrap.activeRole=activeRole; show(current);}catch(err){alert(err.message)}
  }});
  (user.roles||[]).forEach(r=>{ const o=el('option',{value:r, text:r}); if(r===activeRole) o.selected=true; roleSel.appendChild(o); });

  const nav=el('nav');
  const tabs=[
    ['dashboard','Dashboard'],['request','Requests'],['work','My Work'],
    ['ops','Operations'],['network','Network'],['audit','Audit'],['users','Users']
  ];
  tabs.forEach(([id,label])=>{
    nav.appendChild(el('button',{text:label, onclick:()=>show(id)}));
  });

  const header=el('header',{},[
    el('h1',{text:'Lab Sample Network'}),
    nav,
    el('div',{style:'margin-left:auto;display:flex;gap:.5rem;align-items:center'},[
      el('span',{className:'badge', text:user.username||user.userId}),
      roleSel,
      el('button',{text:'Logout', onclick:()=>{token=''; localStorage.removeItem('ls_token'); renderLogin();}})
    ])
  ]);
  root.append(header, main);

  function show(id){
    current=id;
    content.innerHTML='';
    mapPanel.classList.toggle('hidden', id!=='ops' && id!=='dashboard');
    views[id](content);
    if(id==='ops'||id==='dashboard') setTimeout(initMap, 50);
  }
  show('dashboard');
}

function initMap(){
  const container=document.getElementById('map');
  if(!container) return;
  if(map){ map.resize(); return; }
  try{
    map=new maplibregl.Map({
      container:'map',
      style:'/map/style.json',
      center:[77.5946,12.9716],
      zoom:11
    });
    map.addControl(new maplibregl.NavigationControl());
  }catch(e){ console.warn('map', e); }
}

async function renderDashboard(root){
  root.appendChild(el('div',{className:'card'},[
    el('h2',{text:'Welcome'}),
    el('p',{text:'Role: '+(activeRole||'none')}),
    el('p',{text:'Use the navigation to manage collection requests, assignments, network and operations.'})
  ]));
  try{
    const snap=await api('/read-serviceability-snapshot',{method:'POST', body:{}});
    root.appendChild(el('div',{className:'card'},[
      el('h2',{text:'Serviceability'}),
      el('p',{text:'Version '+snap.version+' · '+snap.activeCollectionPointCount+' collection points · status '+snap.status})
    ]));
  }catch(e){}
}

async function renderRequest(root){
  const types=(bootstrap&&bootstrap.sampleTypes)||[];
  const msg=el('div',{className:'msg'});
  const lat=el('input',{value:'12.9716'}); const lon=el('input',{value:'77.5946'});
  const originType=el('select'); ['home','clinic','node'].forEach(o=>originType.appendChild(el('option',{value:o,text:o})));
  const st=el('select'); types.forEach(t=>st.appendChild(el('option',{value:t.sampleTypeId,text:t.name})));
  const deadline=el('input',{value: new Date(Date.now()+6*3600e3).toISOString()});
  const earliest=el('input',{value: new Date().toISOString()});
  const latest=el('input',{value: new Date(Date.now()+3*3600e3).toISOString()});

  async function check(){
    msg.textContent='Checking...';
    try{
      const d=await api('/check-serviceability',{method:'POST', body:{
        origin:{latitude:+lat.value, longitude:+lon.value}, originType:originType.value,
        sampleTypeId:st.value, requestedAt:new Date().toISOString(),
        deliveryDeadline:deadline.value, earliestCollectionAt:earliest.value, latestCollectionAt:latest.value
      }});
      msg.className='msg '+(d.serviceable?'ok':'err');
      msg.textContent=d.serviceable?('Serviceable → lab '+(d.targetLaboratoryId||'')+' ETA '+(d.estimatedArrivalAt||'')):('Unserviceable: '+d.reason);
    }catch(e){ msg.className='msg err'; msg.textContent=e.message; }
  }
  async function create(){
    msg.textContent='Creating...';
    try{
      const d=await api('/create-collection-request',{method:'POST', body:{
        origin:{latitude:+lat.value, longitude:+lon.value}, originType:originType.value,
        sampleTypeId:st.value, requestedAt:new Date().toISOString(),
        deliveryDeadline:deadline.value, earliestCollectionAt:earliest.value, latestCollectionAt:latest.value
      }});
      msg.className='msg ok'; msg.textContent='Created sample '+d.sampleId+' status='+d.state.status;
    }catch(e){ msg.className='msg err'; msg.textContent=e.message; }
  }
  root.appendChild(el('div',{className:'card'},[
    el('h2',{text:'Collection request'}),
    el('div',{className:'row'},[el('div',{},[el('label',{text:'Latitude'}),lat]), el('div',{},[el('label',{text:'Longitude'}),lon])]),
    el('label',{text:'Origin type'}), originType,
    el('label',{text:'Sample type'}), st,
    el('label',{text:'Earliest collection'}), earliest,
    el('label',{text:'Latest collection'}), latest,
    el('label',{text:'Delivery deadline'}), deadline,
    el('div',{className:'row', style:'margin-top:1rem'},[
      el('button',{text:'Check serviceability', onclick:check}),
      el('button',{className:'primary', text:'Create request', onclick:create})
    ]), msg
  ]));
}

async function renderWork(root){
  const msg=el('div',{className:'msg'});
  try{
    const d=await api('/list-role-work',{method:'POST', body:{}});
    function table(title, items){
      const t=el('table');
      t.appendChild(el('tr',{},[el('th',{text:'Type'}),el('th',{text:'ID'}),el('th',{text:'Status'}),el('th',{text:'Actions'})]));
      items.forEach(it=>{
        const id=it.assignmentId||it.sampleId||'';
        const actions=el('td');
        if(it.assignmentId && it.status==='offered'){
          actions.appendChild(el('button',{text:'Accept', onclick:async()=>{
            try{ await api('/accept-assignment',{method:'POST',body:{assignmentId:it.assignmentId}}); renderWork(root);}catch(e){alert(e.message)}
          }}));
          actions.appendChild(el('button',{text:'Decline', onclick:async()=>{
            try{ await api('/decline-assignment',{method:'POST',body:{assignmentId:it.assignmentId}}); renderWork(root);}catch(e){alert(e.message)}
          }}));
        }
        if(it.assignmentId && it.kind==='collection' && (it.status==='accepted'||it.status==='in_progress')){
          actions.appendChild(el('button',{text:'Collect & seal', onclick:async()=>{
            try{ await api('/collect-and-seal-sample',{method:'POST',body:{assignmentId:it.assignmentId, sampleId:it.sampleId}}); renderWork(root);}catch(e){alert(e.message)}
          }}));
        }
        if(it.assignmentId && it.kind==='laboratory' && (it.status==='accepted'||it.status==='in_progress')){
          actions.appendChild(el('button',{text:'Confirm receipt', onclick:async()=>{
            try{ await api('/confirm-laboratory-receipt',{method:'POST',body:{assignmentId:it.assignmentId, sampleId:it.sampleId}}); renderWork(root);}catch(e){alert(e.message)}
          }}));
        }
        t.appendChild(el('tr',{},[
          el('td',{text:it.type||it.kind||''}), el('td',{text:id.slice(0,8)}), el('td',{text:it.status||''}), actions
        ]));
      });
      root.appendChild(el('div',{className:'card'},[el('h2',{text:title+' ('+items.length+')'}), t]));
    }
    root.innerHTML='';
    table('Pending', d.pending||[]);
    table('In progress', d.inProgress||[]);
    table('Completed', d.completed||[]);
  }catch(e){ root.appendChild(el('div',{className:'msg err', text:e.message})); }
}

async function renderOps(root){
  try{
    const d=await api('/read-operations-state',{method:'POST', body:{}});
    const wrap=el('div',{className:'card'});
    wrap.appendChild(el('h2',{text:'Operations monitor'}));
    wrap.appendChild(el('p',{text:(d.samples||[]).length+' samples · '+(d.workers||[]).length+' workers · '+(d.exceptions||[]).length+' exceptions'}));
    const t=el('table');
    t.appendChild(el('tr',{},[el('th',{text:'Sample'}),el('th',{text:'Status'}),el('th',{text:'Holder'}),el('th',{text:'Stale'})]));
    (d.samples||[]).slice(0,50).forEach(s=>{
      t.appendChild(el('tr',{},[
        el('td',{text:(s.sampleId||'').slice(0,8)}), el('td',{text:s.status}),
        el('td',{text:(s.currentHolderId||'').slice(0,8)}), el('td',{text:String(s.locationStale)})
      ]));
      if(map && s.latestLocation){
        new maplibregl.Marker({color:s.locationStale?'#ef4444':'#22c55e'})
          .setLngLat([s.latestLocation.longitude, s.latestLocation.latitude]).addTo(map);
      }
    });
    wrap.appendChild(t);
    root.appendChild(wrap);
  }catch(e){ root.appendChild(el('div',{className:'msg err', text:e.message})); }
}

async function renderNetwork(root){
  const msg=el('div',{className:'msg'});
  const name=el('input',{value:'Collection Centre A'});
  const lat=el('input',{value:'12.9716'}); const lon=el('input',{value:'77.5946'});
  const fns=el('select'); ['collection_point','hub','laboratory','transfer_point'].forEach(f=>fns.appendChild(el('option',{value:f,text:f})));
  root.appendChild(el('div',{className:'card'},[
    el('h2',{text:'Create location'}),
    el('label',{text:'Name'}), name,
    el('div',{className:'row'},[el('div',{},[el('label',{text:'Lat'}),lat]), el('div',{},[el('label',{text:'Lon'}),lon])]),
    el('label',{text:'Function'}), fns,
    el('button',{className:'primary', style:'margin-top:.75rem', text:'Create', onclick:async()=>{
      try{
        const d=await api('/create-location',{method:'POST', body:{
          name:name.value, coordinate:{latitude:+lat.value,longitude:+lon.value},
          coverageKm:5, handlingMinutes:10, active:true, functions:[fns.value]
        }});
        msg.className='msg ok'; msg.textContent='Created '+d.locationId;
        bootstrap=await api('/ui/bootstrap');
      }catch(e){ msg.className='msg err'; msg.textContent=e.message; }
    }}), msg
  ]));
  const locs=(bootstrap&&bootstrap.locations)||[];
  const t=el('table');
  t.appendChild(el('tr',{},[el('th',{text:'Name'}),el('th',{text:'Active'}),el('th',{text:'Functions'})]));
  locs.forEach(l=>{
    t.appendChild(el('tr',{},[
      el('td',{text:l.name}), el('td',{text:String(l.active)}),
      el('td',{text:Object.entries(l.functions||{}).filter(([,v])=>v).map(([k])=>k).join(', ')})
    ]));
  });
  root.appendChild(el('div',{className:'card'},[el('h2',{text:'Locations'}), t]));
}

async function renderAudit(root){
  try{
    const d=await api('/search-audit-trail',{method:'POST', body:{limit:100, order:'newest_first'}});
    const t=el('table');
    t.appendChild(el('tr',{},[el('th',{text:'Time'}),el('th',{text:'Action'}),el('th',{text:'Entity'}),el('th',{text:'OK'})]));
    (d.entries||[]).forEach(e=>{
      t.appendChild(el('tr',{},[
        el('td',{text:(e.occurredAt||'').slice(0,19)}), el('td',{text:e.action}),
        el('td',{text:e.entityType+':'+String(e.entityId||'').slice(0,8)}), el('td',{text:String(e.success)})
      ]));
    });
    root.appendChild(el('div',{className:'card'},[el('h2',{text:'Audit trail ('+d.total+')'}), t]));
  }catch(e){ root.appendChild(el('div',{className:'msg err', text:e.message})); }
}

async function renderUsers(root){
  const msg=el('div',{className:'msg'});
  const username=el('input'); const pass=el('input',{type:'password', value:'password123'});
  const role=el('select'); ['requester','collection_professional','delivery_partner','node_handler','laboratory_team','dispatcher','administrator'].forEach(r=>role.appendChild(el('option',{value:r,text:r})));
  root.appendChild(el('div',{className:'card'},[
    el('h2',{text:'Create user'}),
    el('label',{text:'Username'}), username,
    el('label',{text:'Password'}), pass,
    el('label',{text:'Role'}), role,
    el('button',{className:'primary', style:'margin-top:.75rem', text:'Create', onclick:async()=>{
      try{
        const d=await api('/create-user',{method:'POST', body:{
          username:username.value, initialPassword:pass.value, roles:[role.value],
          qualifications: role.value==='collection_professional'?['Amber','Indigo','Frost','Pulse']:[],
          certifications: role.value==='collection_professional'?[
            {code:'Amber',active:true},{code:'Indigo',active:true},{code:'Frost',active:true},{code:'Pulse',active:true}
          ]:[],
          active:true, fullName:username.value
        }});
        msg.className='msg ok'; msg.textContent='Created '+d.userId;
      }catch(e){ msg.className='msg err'; msg.textContent=e.message; }
    }}), msg
  ]));
}

// boot
token=localStorage.getItem('ls_token')||'';
if(token) loadApp(); else renderLogin();
</script>
</body>
</html>
`

