package db

import (
        "context"
        "embed"
        "fmt"
        "time"

        "github.com/jackc/pgx/v5"
        "github.com/jackc/pgx/v5/pgxpool"
        "go.mongodb.org/mongo-driver/v2/mongo"
        "go.mongodb.org/mongo-driver/v2/mongo/options"
)

//go:embed schema.sql
var schemaFS embed.FS

type DB struct {
        Pool  *pgxpool.Pool
        Mongo *mongo.Client
        MongoDB *mongo.Database
}

func Connect(ctx context.Context, databaseURL, mongoURI string) (*DB, error) {
        cfg, err := pgxpool.ParseConfig(databaseURL)
        if err != nil {
                return nil, fmt.Errorf("parse db url: %w", err)
        }
        cfg.MaxConns = 20
        cfg.MinConns = 2
        cfg.MaxConnLifetime = time.Hour
        pool, err := pgxpool.NewWithConfig(ctx, cfg)
        if err != nil {
                return nil, fmt.Errorf("pg connect: %w", err)
        }
        if err := pool.Ping(ctx); err != nil {
                pool.Close()
                return nil, fmt.Errorf("pg ping: %w", err)
        }

        mclient, err := mongo.Connect(options.Client().ApplyURI(mongoURI))
        if err != nil {
                pool.Close()
                return nil, fmt.Errorf("mongo connect: %w", err)
        }
        mctx, cancel := context.WithTimeout(ctx, 10*time.Second)
        defer cancel()
        if err := mclient.Ping(mctx, nil); err != nil {
                pool.Close()
                _ = mclient.Disconnect(context.Background())
                return nil, fmt.Errorf("mongo ping: %w", err)
        }

        return &DB{Pool: pool, Mongo: mclient, MongoDB: mclient.Database("arena")}, nil
}

func (d *DB) Close() {
        if d.Pool != nil {
                d.Pool.Close()
        }
        if d.Mongo != nil {
                _ = d.Mongo.Disconnect(context.Background())
        }
}

func (d *DB) Migrate(ctx context.Context) error {
        sqlBytes, err := schemaFS.ReadFile("schema.sql")
        if err != nil {
                return err
        }
        _, err = d.Pool.Exec(ctx, string(sqlBytes))
        if err != nil {
                return fmt.Errorf("migrate: %w", err)
        }
        // Materialize MongoDB collections and indexes
        colls := []string{"audit_archive", "event_archive", "notes"}
        for _, name := range colls {
                _ = d.MongoDB.CreateCollection(ctx, name)
        }
        audit := d.MongoDB.Collection("audit_archive")
        _, _ = audit.Indexes().CreateMany(ctx, []mongo.IndexModel{
                {Keys: map[string]int{"entityType": 1, "entityId": 1}},
                {Keys: map[string]int{"occurredAt": -1}},
                {Keys: map[string]int{"actorId": 1}},
                {Keys: map[string]int{"action": 1}},
        })
        events := d.MongoDB.Collection("event_archive")
        _, _ = events.Indexes().CreateMany(ctx, []mongo.IndexModel{
                {Keys: map[string]int{"createdAt": -1}},
                {Keys: map[string]int{"entityType": 1, "entityId": 1}},
        })
        return nil
}

func (d *DB) Reset(ctx context.Context) error {
        tables := []string{
                "worker_location_updates", "handling_checkpoints", "disruptions",
                "serviceability_snapshots", "realtime_events", "idempotency_keys",
                "timeline_events", "audit_log", "capacity_reservations", "handoffs",
                "assignments", "journey_stops", "journeys", "samples", "lab_acceptances",
