                w.Header().Set("Access-Control-Allow-Origin", "*")
                w.Header().Set("Access-Control-Allow-Headers", "Content-Type, Authorization")
                w.Header().Set("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
                if r.Method == http.MethodOptions {
                        w.WriteHeader(204)
                        return
                }
                // Public endpoints
                if r.URL.Path == "/ready" || r.URL.Path == "/api/authenticate-user" ||
                        strings.HasPrefix(r.URL.Path, "/map/") || r.URL.Path == "/" ||
                        strings.HasPrefix(r.URL.Path, "/assets/") || r.URL.Path == "/index.html" ||
                        !strings.HasPrefix(r.URL.Path, "/api/") {
                        next.ServeHTTP(w, r)
                        return
                }
                token, err := auth.BearerToken(r)
                if err != nil {
                        httpapi.WriteError(w, httpapi.ErrUnauthorized)
                        return
                }
                sess, user, err := a.loadSession(r.Context(), token)
                if err != nil {
                        httpapi.WriteError(w, httpapi.ErrUnauthorized)
                        return
                }
                ctx := context.WithValue(r.Context(), ctxSession, sess)
                ctx = context.WithValue(ctx, ctxUser, user)
                next.ServeHTTP(w, r.WithContext(ctx))
        })
}

func (a *App) loadSession(ctx context.Context, token string) (*SessionInfo, *models.User, error) {
        var s SessionInfo
        var rolesJSON []byte
        var exp time.Time
        err := a.DB.Pool.QueryRow(ctx, `
                SELECT token, user_id, active_role, roles, expires_at FROM sessions WHERE token=$1`, token).
                Scan(&s.Token, &s.UserID, &s.ActiveRole, &rolesJSON, &exp)
        if err != nil {
                return nil, nil, err
        }
        if time.Now().UTC().After(exp) {
                return nil, nil, httpapi.ErrUnauthorized
        }
        s.Roles = FromJSON[[]string](rolesJSON)
        u, err := a.getUser(ctx, s.UserID)
        if err != nil || !u.Active {
                return nil, nil, httpapi.ErrUnauthorized
        }
        return &s, u, nil
}

func SessionFrom(ctx context.Context) *SessionInfo {
        v, _ := ctx.Value(ctxSession).(*SessionInfo)
        return v
}

func UserFrom(ctx context.Context) *models.User {
        v, _ := ctx.Value(ctxUser).(*models.User)
        return v
}

func (a *App) requireRole(ctx context.Context, roles ...string) (*SessionInfo, *models.User, error) {
        s := SessionFrom(ctx)
        u := UserFrom(ctx)
        if s == nil || u == nil {
                return nil, nil, httpapi.ErrUnauthorized
        }
        if s.ActiveRole == "" {
                return nil, nil, httpapi.ErrRoleNotSelected
        }
        if len(roles) == 0 {
                return s, u, nil
        }
        for _, r := range roles {
                if s.ActiveRole == r {
                        return s, u, nil
                }
        }
        // administrator can do dispatcher things when acting as administrator for admin-only;
        // but contract says permissions use selected role. So we enforce exact match.
        return nil, nil, httpapi.ErrForbidden
}

func (a *App) requireAnyRole(ctx context.Context, roles ...string) (*SessionInfo, *models.User, error) {
        return a.requireRole(ctx, roles...)
}

func (a *App) requireAdminOrDispatcher(ctx context.Context) (*SessionInfo, *models.User, error) {
        return a.requireRole(ctx, models.RoleAdministrator, models.RoleDispatcher)
}

func (a *App) requireAdmin(ctx context.Context) (*SessionInfo, *models.User, error) {
        return a.requireRole(ctx, models.RoleAdministrator)
}
