<script>
const API='/api';
let token='', user=null, activeRole='', bootstrap=null, map=null;

async function api(path, opts={}){
  const headers=Object.assign({'Content-Type':'application/json'}, opts.headers||{});
  if(token) headers['Authorization']='Bearer '+token;
  const res=await fetch(API+path, Object.assign({}, opts, {headers, body: opts.body?JSON.stringify(opts.body):undefined}));
  const text=await res.text();
  let data=null; try{data=JSON.parse(text)}catch(e){data={error:text}}
  if(!res.ok) throw Object.assign(new Error(data.error||res.statusText), {code:data.code, status:res.status, data});
  return data.data!==undefined?data.data:data;
}

function el(tag, attrs={}, children=[]){
  const e=document.createElement(tag);
  Object.entries(attrs).forEach(([k,v])=>{
    if(k==='className') e.className=v;
    else if(k==='onclick') e.onclick=v;
    else if(k.startsWith('on')) e.addEventListener(k.slice(2).toLowerCase(), v);
    else if(k==='text') e.textContent=v;
    else e.setAttribute(k,v);
  });
  (Array.isArray(children)?children:[children]).forEach(c=>{
    if(c==null) return;
    if(typeof c==='string') e.appendChild(document.createTextNode(c));
    else e.appendChild(c);
  });
  return e;
}

function renderLogin(){
