package app

import (
	"encoding/json"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"time"

	"labsample/internal/httpapi"
)

func (a *App) registerRoutes(mux *http.ServeMux) {
	// readiness
	mux.HandleFunc("GET /ready", a.handleReady)

	// auth
	mux.HandleFunc("POST /api/authenticate-user", a.handleAuthenticate)
	mux.HandleFunc("POST /api/select-active-role", a.handleSelectRole)

	// users
	mux.HandleFunc("POST /api/create-user", a.handleCreateUser)
	mux.HandleFunc("POST /api/update-user-access", a.handleUpdateUserAccess)
	mux.HandleFunc("GET /api/read-user/{userId}", a.handleReadUser)
	mux.HandleFunc("POST /api/set-worker-availability", a.handleSetWorkerAvailability)

	// network
	mux.HandleFunc("POST /api/create-location", a.handleCreateLocation)
	mux.HandleFunc("POST /api/update-location", a.handleUpdateLocation)
	mux.HandleFunc("POST /api/set-location-status", a.handleSetLocationStatus)
	mux.HandleFunc("POST /api/set-location-function-status", a.handleSetLocationFunctionStatus)
	mux.HandleFunc("POST /api/create-connection", a.handleCreateConnection)
	mux.HandleFunc("POST /api/set-connection-status", a.handleSetConnectionStatus)
	mux.HandleFunc("POST /api/configure-capacity", a.handleConfigureCapacity)
	mux.HandleFunc("POST /api/configure-laboratory-acceptance", a.handleConfigureLabAcceptance)

	// sample types
	mux.HandleFunc("POST /api/create-sample-type", a.handleCreateSampleType)
	mux.HandleFunc("POST /api/update-sample-type", a.handleUpdateSampleType)

	// serviceability / requests
	mux.HandleFunc("POST /api/check-serviceability", a.handleCheckServiceability)
	mux.HandleFunc("POST /api/read-serviceability-snapshot", a.handleReadServiceabilitySnapshot)
	mux.HandleFunc("POST /api/create-collection-request", a.handleCreateCollectionRequest)
	mux.HandleFunc("POST /api/ingest-presealed-sample", a.handleIngestPresealed)

	// samples
	mux.HandleFunc("GET /api/read-sample-state/{sampleId}", a.handleReadSampleState)
	mux.HandleFunc("POST /api/read-sample-lifecycle", a.handleReadSampleLifecycle)
	mux.HandleFunc("POST /api/collect-and-seal-sample", a.handleCollectAndSeal)
	mux.HandleFunc("POST /api/confirm-laboratory-receipt", a.handleConfirmLabReceipt)
	mux.HandleFunc("POST /api/record-laboratory-exception", a.handleRecordLabException)
	mux.HandleFunc("POST /api/record-handling-checkpoint", a.handleRecordHandlingCheckpoint)

	// assignments / handoffs
	mux.HandleFunc("POST /api/accept-assignment", a.handleAcceptAssignment)
	mux.HandleFunc("POST /api/decline-assignment", a.handleDeclineAssignment)
	mux.HandleFunc("POST /api/initiate-handoff", a.handleInitiateHandoff)
	mux.HandleFunc("POST /api/confirm-handoff", a.handleConfirmHandoff)
	mux.HandleFunc("POST /api/update-assignment-progress", a.handleUpdateAssignmentProgress)
	mux.HandleFunc("POST /api/record-worker-location", a.handleRecordWorkerLocation)

	// journeys
	mux.HandleFunc("POST /api/read-journey-plan", a.handleReadJourneyPlan)
	mux.HandleFunc("POST /api/cancel-journey", a.handleCancelJourney)
	mux.HandleFunc("POST /api/reroute-journey", a.handleRerouteJourney)
	mux.HandleFunc("POST /api/edit-active-plan", a.handleEditActivePlan)
	mux.HandleFunc("POST /api/split-journey", a.handleSplitJourney)
	mux.HandleFunc("POST /api/merge-journeys", a.handleMergeJourneys)

	// ops
	mux.HandleFunc("POST /api/list-role-work", a.handleListRoleWork)
	mux.HandleFunc("POST /api/read-operations-state", a.handleReadOperationsState)
	mux.HandleFunc("POST /api/report-disruption", a.handleReportDisruption)
	mux.HandleFunc("POST /api/search-audit-trail", a.handleSearchAudit)

	// ui / events
	mux.HandleFunc("GET /api/ui/bootstrap", a.handleUIBootstrap)
	mux.HandleFunc("GET /api/events", a.handleEvents)

	// map assets
	mux.HandleFunc("GET /map/", a.handleMapAssets)

	// frontend static
	mux.HandleFunc("/", a.handleFrontend)
}

func (a *App) handleReady(w http.ResponseWriter, r *http.Request) {
	if !a.IsReady() {
		httpapi.WriteJSON(w, 503, map[string]string{"status": "starting"})
		return
	}
	httpapi.WriteJSON(w, 200, map[string]string{"status": "ready"})
}

func (a *App) handleEvents(w http.ResponseWriter, r *http.Request) {
	s := SessionFrom(r.Context())
	if s == nil {
		// middleware should have auth'd
		writeErr(w, errUnauthorized())
		return
	}
	flusher, ok := w.(http.Flusher)
	if !ok {
		writeErr(w, errInternal)
		return
	}
	w.Header().Set("Content-Type", "text/event-stream")
	w.Header().Set("Cache-Control", "no-cache")
	w.Header().Set("Connection", "keep-alive")
	ch := a.subscribe()
	defer a.unsubscribe(ch)

	// send hello
	hello, _ := json.Marshal(map[string]interface{}{"type": "connected", "at": FormatTime(Now())})
	_, _ = w.Write([]byte("data: " + string(hello) + "\n\n"))
	flusher.Flush()

	ticker := time.NewTicker(15 * time.Second)
	defer ticker.Stop()
	ctx := r.Context()
	for {
		select {
		case <-ctx.Done():
			return
		case ev, ok := <-ch:
			if !ok {
				return
			}
			b, _ := json.Marshal(ev)
			_, _ = w.Write([]byte("data: " + string(b) + "\n\n"))
			flusher.Flush()
		case <-ticker.C:
			_, _ = w.Write([]byte(": ping\n\n"))
			flusher.Flush()
		}
	}
}

func (a *App) handleMapAssets(w http.ResponseWriter, r *http.Request) {
	rel := strings.TrimPrefix(r.URL.Path, "/map/")
	if rel == "" || strings.Contains(rel, "..") {
		http.NotFound(w, r)
		return
	}
	base := a.Cfg.MapAssetsDir
	full := filepath.Join(base, rel)
	if _, err := os.Stat(full); err != nil {
		alts := []string{
			filepath.Join(base, "pmtiles", rel),
			filepath.Join("/opt/arena/map-assets", rel),
			filepath.Join("/workspace/map-assets", rel),
		}
		found := false
		for _, alt := range alts {
			if _, err := os.Stat(alt); err == nil {
				full = alt
				found = true
				break
			}
		}
		if !found {
			http.NotFound(w, r)
			return
		}
	}
	// Rewrite style.json so offline PMTiles resolve through this server.
	if strings.HasSuffix(full, "style.json") || rel == "style.json" {
		b, err := os.ReadFile(full)
		if err != nil {
			http.NotFound(w, r)
			return
		}
		s := string(b)
		s = strings.ReplaceAll(s, "/map-assets/", "/map/")
		s = strings.ReplaceAll(s, "pmtiles:///map/bangalore.pmtiles", "pmtiles://http://127.0.0.1:8080/map/bangalore.pmtiles")
		// Prefer relative host-based pmtiles URL that works with protocol handler
		s = strings.ReplaceAll(s, "pmtiles://http://127.0.0.1:8080/map/bangalore.pmtiles", "pmtiles:///map/bangalore.pmtiles")
		w.Header().Set("Content-Type", "application/json")
		w.Header().Set("Access-Control-Allow-Origin", "*")
		_, _ = w.Write([]byte(s))
		return
	}
	switch {
	case strings.HasSuffix(full, ".json"):
		w.Header().Set("Content-Type", "application/json")
	case strings.HasSuffix(full, ".pmtiles"):
		w.Header().Set("Content-Type", "application/octet-stream")
		w.Header().Set("Accept-Ranges", "bytes")
	case strings.HasSuffix(full, ".pbf"):
		w.Header().Set("Content-Type", "application/x-protobuf")
	case strings.HasSuffix(full, ".png"):
		w.Header().Set("Content-Type", "image/png")
	}
	http.ServeFile(w, r, full)
}

func (a *App) handleFrontend(w http.ResponseWriter, r *http.Request) {
	if strings.HasPrefix(r.URL.Path, "/api/") {
		http.NotFound(w, r)
		return
	}
	root := a.Cfg.StaticDir
	path := r.URL.Path
	if path == "/" {
		path = "/index.html"
	}
	full := filepath.Join(root, path)
	if _, err := os.Stat(full); err != nil {
		// SPA fallback
		index := filepath.Join(root, "index.html")
		if _, err2 := os.Stat(index); err2 == nil {
			http.ServeFile(w, r, index)
			return
		}
		// minimal fallback HTML if frontend not built
		w.Header().Set("Content-Type", "text/html; charset=utf-8")
		_, _ = io.WriteString(w, minimalHTML)
		return
	}
	http.ServeFile(w, r, full)
}

