// seedBangaloreNetwork creates a default operational network around Bangalore
// when no locations exist yet. Safe to call repeatedly.
func (a *App) seedBangaloreNetwork(ctx context.Context) error {
	var n int
	if err := a.DB.Pool.QueryRow(ctx, `SELECT COUNT(*) FROM locations`).Scan(&n); err != nil {
		return err
	}
	if n > 0 {
		return nil
	}
