		lat, lon float64
		cp, tp, hub, lab bool
		accept            []string
	}
	// Central Bangalore points within ~5km of each other for serviceability
	locs := []loc{
		{NewID(), "Indiranagar Collection Centre", 12.9784, 77.6408, true, true, false, false, nil},
		{NewID(), "Koramangala Hub", 12.9352, 77.6245, true, true, true, false, nil},
		{NewID(), "MG Road Transfer", 12.9750, 77.6063, false, true, false, false, nil},
		{NewID(), "City Lab Whitefield Gate", 12.9698, 77.7499, false, true, false, true, []string{"Amber", "Indigo", "Frost", "Pulse"}},
		{NewID(), "Central Diagnostics Lab", 12.9716, 77.5946, true, true, true, true, []string{"Amber", "Indigo", "Frost", "Pulse"}},
	}

	for _, l := range locs {
		_, err := a.DB.Pool.Exec(ctx, `
			INSERT INTO locations (
				id, name, latitude, longitude, coverage_km, handling_minutes, active,
