                httpapi.WriteError(w, err)
                return
        }
        u, err := a.getUser(r.Context(), req.UserID)
        if err != nil {
                httpapi.WriteError(w, httpapi.ErrNotFound)
                return
        }
        if req.Qualifications == nil {
                req.Qualifications = u.Qualifications
        }
        if req.Certifications == nil {
                req.Certifications = u.Certifications
        }
        for _, c := range req.Certifications {
                if c.Code == "" {
                        httpapi.WriteError(w, httpapi.E(400, "invalid_certification", "invalid certification"))
                        return
                }
        }
        _, err = a.DB.Pool.Exec(r.Context(), `
                UPDATE users SET roles=$1::jsonb, qualifications=$2::jsonb, certifications=$3::jsonb, active=$4, assigned_location_id=$5
                WHERE id=$6`,
                MustJSON(req.Roles), MustJSON(req.Qualifications), MustJSON(req.Certifications),
                req.Active, req.AssignedLocationID, req.UserID)
        if err != nil {
                httpapi.WriteError(w, httpapi.E(500, "internal_error", "update failed"))
                return
        }
        u, _ = a.getUser(r.Context(), req.UserID)
        a.audit(r.Context(), s.UserID, s.ActiveRole, "update_user_access", "user", req.UserID, true, nil)
        httpapi.WriteData(w, 201, a.userJSON(u))
}

func (a *App) handleReadUser(w http.ResponseWriter, r *http.Request) {
        s, me, err := a.requireRole(r.Context())
        if err != nil {
                // allow any authenticated with role; if role not selected still allow self read? contract needs role
                httpapi.WriteError(w, err)
                return
        }
        userID := r.PathValue("userId")
        if s.ActiveRole != models.RoleAdministrator && s.ActiveRole != models.RoleDispatcher && me.ID != userID {
                httpapi.WriteError(w, httpapi.ErrForbidden)
                return
        }
        u, err := a.getUser(r.Context(), userID)
        if err != nil {
                httpapi.WriteError(w, httpapi.ErrNotFound)
                return
        }
        httpapi.WriteData(w, 200, a.userJSON(u))
}

func (a *App) handleSetWorkerAvailability(w http.ResponseWriter, r *http.Request) {
        s, me, err := a.requireRole(r.Context(),
                models.RoleAdministrator, models.RoleDispatcher,
                models.RoleCollectionProfessional, models.RoleDeliveryPartner,
                models.RoleNodeHandler, models.RoleLaboratoryTeam)
        if err != nil {
                httpapi.WriteError(w, err)
                return
        }
        var req struct {
                WorkerID      string `json:"workerId"`
                Available     bool   `json:"available"`
                CapacityUnits int    `json:"capacityUnits"`
        }
        if err := httpapi.DecodeJSON(r, &req); err != nil {
                httpapi.WriteError(w, err)
                return
        }
        if s.ActiveRole != models.RoleAdministrator && s.ActiveRole != models.RoleDispatcher && me.ID != req.WorkerID {
                httpapi.WriteError(w, httpapi.ErrForbidden)
                return
        }
        _, err = a.DB.Pool.Exec(r.Context(), `UPDATE users SET available=$1, capacity_units=$2 WHERE id=$3`,
                req.Available, req.CapacityUnits, req.WorkerID)
        if err != nil {
                httpapi.WriteError(w, httpapi.ErrNotFound)
                return
        }
        a.audit(r.Context(), s.UserID, s.ActiveRole, "set_worker_availability", "user", req.WorkerID, true, nil)
        httpapi.WriteData(w, 200, map[string]interface{}{
                "workerId": req.WorkerID, "available": req.Available, "capacityUnits": req.CapacityUnits,
        })
