	if key == "" {
		return nil, false
	}
	var resp []byte
	err := a.DB.Pool.QueryRow(ctx, `
		SELECT response FROM idempotency_keys
		WHERE actor_id=$1 AND action=$2 AND key=$3`, userID, operation, key).Scan(&resp)
	if err != nil {
		return nil, false
	}
	var out map[string]interface{}
	if err := json.Unmarshal(resp, &out); err != nil {
		return nil, false
	}
	return out, true
}

func (a *App) saveIdempotency(ctx context.Context, userID, operation, key string, response map[string]interface{}) {
	if key == "" {
		return
	}
	b, _ := json.Marshal(response)
	_, _ = a.DB.Pool.Exec(ctx, `
		INSERT INTO idempotency_keys (key, actor_id, action, response, status_code, created_at)
		VALUES ($1,$2,$3,$4,$5,$6)
		ON CONFLICT (key, actor_id, action) DO UPDATE SET response=EXCLUDED.response, status_code=EXCLUDED.status_code`,
