action.file_text:
:root {
  --bg: #0f172a;
  --card: #1e293b;
  --accent: #38bdf8;
  --text: #e2e8f0;
  --muted: #94a3b8;
  --ok: #22c55e;
  --bad: #ef4444;
  --border: #334155;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
  background: var(--bg);
  color: var(--text);
}
header.app-header {
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 0.75rem 1.25rem;
  background: #020617;
  border-bottom: 1px solid var(--border);
  flex-wrap: wrap;
}
header h1 { font-size: 1.1rem; margin: 0; font-weight: 600; }
nav { display: flex; gap: 0.5rem; flex-wrap: wrap; }
button, .btn {
  background: var(--card);
  color: var(--text);
  border: 1px solid #475569;
  border-radius: 6px;
  padding: 0.4rem 0.75rem;
  cursor: pointer;
  font: inherit;
}
button.primary, .btn.primary {
  background: var(--accent);
  color: #0f172a;
  border-color: var(--accent);
  font-weight: 600;
}
button:hover { filter: brightness(1.08); }
button:disabled { opacity: 0.5; cursor: not-allowed; }
main.layout {
  display: grid;
  grid-template-columns: 340px 1fr;
  height: calc(100vh - 58px);
}
@media (max-width: 900px) {
  main.layout { grid-template-columns: 1fr; height: auto; min-height: calc(100vh - 58px); }
}
aside.sidebar {
  border-right: 1px solid var(--border);
  overflow: auto;
  padding: 1rem;
  background: #0b1220;
}
section.view {
  overflow: auto;
  padding: 1rem;
  position: relative;
  min-height: 420px;
}
.card {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 1rem;
  margin-bottom: 1rem;
}
.card h2 { margin: 0 0 0.75rem; font-size: 1rem; }
label {
  display: block;
  font-size: 0.75rem;
  color: var(--muted);
  margin: 0.45rem 0 0.15rem;
}
input, select, textarea {
  width: 100%;
  padding: 0.45rem 0.55rem;
  border-radius: 6px;
  border: 1px solid #475569;
  background: #020617;
  color: var(--text);
  font: inherit;
}
.row { display: flex; gap: 0.5rem; flex-wrap: wrap; }
.row > * { flex: 1; min-width: 120px; }
.msg { font-size: 0.85rem; margin-top: 0.5rem; color: var(--muted); }
.msg.ok { color: var(--ok); }
.msg.err { color: var(--bad); }
table { width: 100%; border-collapse: collapse; font-size: 0.85rem; }
th, td { text-align: left; padding: 0.35rem 0.4rem; border-bottom: 1px solid var(--border); vertical-align: top; }
.badge {
  display: inline-block;
  padding: 0.1rem 0.45rem;
  border-radius: 999px;
  font-size: 0.7rem;
  background: #334155;
}
.login-wrap {
  max-width: 400px;
  margin: 10vh auto;
  padding: 1.5rem;
}
#map {
  width: 100%;
  height: 360px;
  border-radius: 8px;
  border: 1px solid var(--border);
}
.stack { display: flex; flex-direction: column; gap: 0.75rem; }
.actions { display: flex; gap: 0.4rem; flex-wrap: wrap; margin-top: 0.5rem; }
.muted { color: var(--muted); font-size: 0.85rem; }
.stale { color: var(--bad); font-weight: 600; }
.fresh { color: var(--ok); }
.role-banner {
  background: #0c4a6e;
  border: 1px solid #0284c7;
  border-radius: 8px;
  padding: 0.75rem 1rem;
  margin-bottom: 1rem;
}

