function MapPanel({ ops }: { ops?: OperationsState }) {
  const ref = useRef<HTMLDivElement>(null)
  const mapRef = useRef<MapLibreMap | null>(null)
  const markers = useRef<Marker[]>([])

  useEffect(() => {
    if (!ref.current || mapRef.current) return
    try {
      const map = new maplibregl.Map({
        container: ref.current,
        style: '/map/style.json',
        center: [77.5946, 12.9716],
        zoom: 11,
      })
      map.addControl(new maplibregl.NavigationControl())
      mapRef.current = map
    } catch (e) {
      console.warn('map init failed', e)
    }
    return () => {
      markers.current.forEach((m) => m.remove())
      mapRef.current?.remove()
      mapRef.current = null
    }
  }, [])

  useEffect(() => {
    const map = mapRef.current
    if (!map || !ops) return
    markers.current.forEach((m) => m.remove())
    markers.current = []
    ;(ops.locations || []).forEach((loc: any) => {
      const c = loc.coordinate
      if (!c) return
      const el = document.createElement('div')
      el.title = loc.name
      el.style.width = '12px'
      el.style.height = '12px'
      el.style.borderRadius = '50%'
      el.style.background = loc.active ? '#38bdf8' : '#64748b'
      el.style.border = '2px solid #fff'
      const m = new maplibregl.Marker({ element: el }).setLngLat([c.longitude, c.latitude]).addTo(map)
      markers.current.push(m)
    })
    ;(ops.samples || []).forEach((s: any) => {
      const loc = s.latestLocation || s.origin
      if (!loc) return
      const m = new maplibregl.Marker({ color: s.locationStale ? '#ef4444' : '#22c55e' })
        .setLngLat([loc.longitude, loc.latitude])
        .addTo(map)
      markers.current.push(m)
    })
    ;(ops.workers || []).forEach((w: any) => {
      const loc = w.latestLocation
      if (!loc) return
      const m = new maplibregl.Marker({ color: '#a78bfa' }).setLngLat([loc.longitude, loc.latitude]).addTo(map)
      markers.current.push(m)
    })
  }, [ops])

  return (
    <div className="card">
      <h2>Live map (Bangalore offline tiles)</h2>
      <div id="map" ref={ref} role="img" aria-label="Network map" />
      <p className="muted">Blue nodes · green fresh samples · red stale samples · purple workers</p>
    </div>
  )
}

function RequestsView({
  activeRole,
  sampleTypes,
  setSampleTypes,
  onCreated,
}: {
  activeRole: string
  sampleTypes: SampleType[]
  setSampleTypes: (t: SampleType[]) => void
  onCreated: (sampleId: string) => void
}) {
  const now = useMemo(() => new Date(), [])
  const [originType, setOriginType] = useState('home')
  const [lat, setLat] = useState('12.9716')
  const [lon, setLon] = useState('77.5946')
  const [sampleTypeId, setSampleTypeId] = useState('')
  const [sampleTypeName, setSampleTypeName] = useState('Amber')
  const [earliest, setEarliest] = useState(toLocalInputValue(now))
  const [latest, setLatest] = useState(toLocalInputValue(new Date(now.getTime() + 4 * 3600_000)))
  const [deadline, setDeadline] = useState(toLocalInputValue(new Date(now.getTime() + 12 * 3600_000)))
  const [msg, setMsg] = useState('')
  const [msgOk, setMsgOk] = useState(false)
  const [typesLoaded, setTypesLoaded] = useState(false)

  // Ensure we have sample type IDs — admin can list via bootstrap seed; try snapshot / create known types by name via ops
  useEffect(() => {
    if (typesLoaded) return
    ;(async () => {
      try {
        // Attempt to read via admin network bootstrap: create-sample-type is admin only; seed should have types.
        // We store type list in localStorage after first successful check response that echoes type.
        const cached = localStorage.getItem('ls_sample_types')
        if (cached) {
          const parsed = JSON.parse(cached)
          if (Array.isArray(parsed) && parsed.length) {
            setSampleTypes(parsed)
            setSampleTypeId(parsed[0].sampleTypeId)
            setTypesLoaded(true)
            return
          }
        }
      } catch {
        /* ignore */
      }
      // If administrator, try to ensure default types exist by calling create (may 409)
      if (activeRole === 'administrator') {
        const defaults = [
          { name: 'Amber', containerType: 'standard', temperatureMinC: 2, temperatureMaxC: 25, qualifiedCollectorRequired: true, requiredQualification: 'Amber' },
          { name: 'Indigo', containerType: 'standard', temperatureMinC: 2, temperatureMaxC: 25, qualifiedCollectorRequired: true, requiredQualification: 'Indigo', incompatibleSampleTypeNames: ['Amber'] },
          { name: 'Frost', containerType: 'cooled', temperatureMinC: 2, temperatureMaxC: 8, qualifiedCollectorRequired: true, requiredQualification: 'Frost', requiresCooled: true },
          { name: 'Pulse', containerType: 'standard', temperatureMinC: 2, temperatureMaxC: 25, qualifiedCollectorRequired: true, requiredQualification: 'Pulse', timeCritical: true },
        ]
        const found: SampleType[] = []
        for (const d of defaults) {
          try {
            const res = await api<any>('/create-sample-type', {
              method: 'POST',
              body: {
                name: d.name,
                qualifiedCollectorRequired: d.qualifiedCollectorRequired,
                requiredQualification: d.requiredQualification,
                containerType: d.containerType,
                temperatureMinC: d.temperatureMinC,
                temperatureMaxC: d.temperatureMaxC,
                incompatibleSampleTypeIds: [],
                active: true,
              },
            })
            found.push({ sampleTypeId: res.sampleTypeId, name: res.name || d.name })
          } catch {
            /* already exists — ignore */
          }
        }
        if (found.length) {
          setSampleTypes(found)
          setSampleTypeId(found[0].sampleTypeId)
          localStorage.setItem('ls_sample_types', JSON.stringify(found))
        }
      }
      setTypesLoaded(true)
    })()
  }, [activeRole, typesLoaded, setSampleTypes])

  async function resolveTypeId(): Promise<string> {
    if (sampleTypeId) return sampleTypeId
    const match = sampleTypes.find((t) => t.name.toLowerCase() === sampleTypeName.toLowerCase())
    if (match) return match.sampleTypeId
    throw new Error('Select a sample type (or sign in as administrator once to seed types)')
  }

  async function check() {
    setMsg('')
    try {
      const st = await resolveTypeId()
      const body = {
        origin: { latitude: Number(lat), longitude: Number(lon) },
        originType,
        sampleTypeId: st,
        requestedAt: new Date().toISOString(),
        earliestCollectionAt: fromLocalInputValue(earliest),
        latestCollectionAt: fromLocalInputValue(latest),
        deliveryDeadline: fromLocalInputValue(deadline),
      }
      const d = await api<any>('/check-serviceability', { method: 'POST', body })
      setMsgOk(d.serviceable || d.serviceability === 'serviceable')
      setMsg(
        `Serviceability: ${d.serviceability || (d.serviceable ? 'serviceable' : 'unserviceable')}` +
          (d.reason || d.serviceabilityReason ? ` — ${d.reason || d.serviceabilityReason}` : '') +
          (d.version ? ` (version ${d.version})` : ''),
      )
    } catch (e: any) {
      setMsgOk(false)
      setMsg(e.message || 'Check failed')
    }
  }

  async function create() {
    setMsg('')
    try {
      const st = await resolveTypeId()
      const body = {
        origin: { latitude: Number(lat), longitude: Number(lon) },
        originType,
        sampleTypeId: st,
        requestedAt: new Date().toISOString(),
        earliestCollectionAt: fromLocalInputValue(earliest),
        latestCollectionAt: fromLocalInputValue(latest),
        deliveryDeadline: fromLocalInputValue(deadline),
        idempotencyKey: idemKey('req'),
      }
      const d = await api<any>('/create-collection-request', { method: 'POST', body })
      setMsgOk(true)
      setMsg(`Created sample ${d.sampleId} (${d.serviceability})`)
      if (d.sampleId) onCreated(d.sampleId)
    } catch (e: any) {
      setMsgOk(false)
      setMsg(e.message || 'Create failed')
    }
  }

  return (
    <div className="card">
      <h2>Collection request</h2>
      <p className="muted">Serviceability is a dry run — it does not create a request or reserve capacity.</p>
      <div className="row">
        <Field id="origin-type" label="Origin type">
          <select value={originType} onChange={(e) => setOriginType(e.target.value)} aria-label="Origin type">
            <option value="home">home</option>
            <option value="clinic">clinic</option>
            <option value="node">node</option>
          </select>
        </Field>
        <Field id="sample-type" label="Sample type">
          {sampleTypes.length ? (
            <select
              value={sampleTypeId}
              onChange={(e) => setSampleTypeId(e.target.value)}
              aria-label="Sample type"
            >
              {sampleTypes.map((t) => (
                <option key={t.sampleTypeId} value={t.sampleTypeId}>
                  {t.name}
                </option>
              ))}
            </select>
          ) : (
            <input
              value={sampleTypeName}
              onChange={(e) => setSampleTypeName(e.target.value)}
              aria-label="Sample type"
              placeholder="Amber"
            />
          )}
        </Field>
      </div>
      <div className="row">
        <Field id="origin-lat" label="Latitude">
          <input value={lat} onChange={(e) => setLat(e.target.value)} aria-label="Latitude" />
        </Field>
        <Field id="origin-lon" label="Longitude">
          <input value={lon} onChange={(e) => setLon(e.target.value)} aria-label="Longitude" />
        </Field>
      </div>
      <div className="row">
        <Field id="earliest-collection" label="Earliest collection">
          <input type="datetime-local" value={earliest} onChange={(e) => setEarliest(e.target.value)} aria-label="Earliest collection" />
        </Field>
        <Field id="latest-collection" label="Latest collection">
          <input type="datetime-local" value={latest} onChange={(e) => setLatest(e.target.value)} aria-label="Latest collection" />
        </Field>
        <Field id="delivery-deadline" label="Delivery deadline">
          <input type="datetime-local" value={deadline} onChange={(e) => setDeadline(e.target.value)} aria-label="Delivery deadline" />
        </Field>
      </div>
      <div className="actions">
        <button type="button" onClick={check}>
          Check serviceability
        </button>
        <button type="button" className="primary" onClick={create}>
          Create request
        </button>
      </div>
      {msg && <div className={`msg ${msgOk ? 'ok' : 'err'}`}>{msg}</div>}
    </div>
  )
}

function WorkView({ onOpenSample, reloadBoot }: { onOpenSample: (id: string) => void; reloadBoot: () => void }) {
  const [work, setWork] = useState<{ pending: any[]; inProgress: any[]; completed: any[] } | null>(null)
  const [msg, setMsg] = useState('')
  const [lat, setLat] = useState('12.9716')
  const [lon, setLon] = useState('77.5946')

  const load = useCallback(async () => {
    const d = await api<any>('/list-role-work', { method: 'POST', body: {} })
    setWork(d)
  }, [])

  useEffect(() => {
    load().catch((e) => setMsg(e.message))
  }, [load])

  async function accept(id: string) {
    await api('/accept-assignment', { method: 'POST', body: { assignmentId: id, idempotencyKey: idemKey('accept') } })
    await load()
    reloadBoot()
  }
  async function decline(id: string) {
    await api('/decline-assignment', { method: 'POST', body: { assignmentId: id, idempotencyKey: idemKey('decline') } })
    await load()
  }
  async function collect(it: any) {
    await api('/collect-and-seal-sample', {
      method: 'POST',
      body: {
        assignmentId: it.assignmentId,
        sampleId: it.sampleId,
        sealedAt: new Date().toISOString(),
        containerType: 'standard',
        temperatureC: 5,
        coordinate: { latitude: Number(lat), longitude: Number(lon) },
        idempotencyKey: idemKey('seal'),
      },
    })
    await load()
  }
  async function confirmReceipt(it: any) {
    await api('/confirm-laboratory-receipt', {
      method: 'POST',
      body: {
        assignmentId: it.assignmentId,
        sampleId: it.sampleId,
        receivedAt: new Date().toISOString(),
        idempotencyKey: idemKey('recv'),
      },
    })
    await load()
  }
  async function recordLocation() {
    await api('/record-worker-location', {
      method: 'POST',
      body: {
        coordinate: { latitude: Number(lat), longitude: Number(lon) },
        recordedAt: new Date().toISOString(),
      },
    })
    setMsg('Location recorded')
  }

  function renderTable(title: string, items: any[]) {
    return (
      <div className="card" key={title}>
        <h2>
          {title} ({items.length})
        </h2>
        <table>
          <thead>
            <tr>
              <th>Type</th>
              <th>ID</th>
              <th>Status</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {items.map((it, i) => {
              const id = it.assignmentId || it.sampleId || it.journeyId || String(i)
              return (
                <tr key={id + i}>
                  <td>{it.type || it.kind || ''}</td>
                  <td>{String(id).slice(0, 8)}</td>
                  <td>{it.status}</td>
                  <td>
                    <div className="actions">
                      {it.sampleId && (
                        <button type="button" onClick={() => onOpenSample(it.sampleId)}>
                          Open
                        </button>
                      )}
                      {it.assignmentId && it.status === 'offered' && (
                        <>
                          <button type="button" className="primary" onClick={() => accept(it.assignmentId).catch((e) => setMsg(e.message))}>
                            Accept
                          </button>
                          <button type="button" onClick={() => decline(it.assignmentId).catch((e) => setMsg(e.message))}>
                            Decline
                          </button>
                        </>
                      )}
                      {it.assignmentId && it.kind === 'collection' && (it.status === 'accepted' || it.status === 'in_progress') && (
                        <button type="button" className="primary" onClick={() => collect(it).catch((e) => setMsg(e.message))}>
                          Collect & seal
                        </button>
                      )}
                      {it.assignmentId && it.kind === 'laboratory' && (it.status === 'accepted' || it.status === 'in_progress') && (
                        <button type="button" className="primary" onClick={() => confirmReceipt(it).catch((e) => setMsg(e.message))}>
                          Confirm receipt
                        </button>
                      )}
                    </div>
                  </td>
                </tr>
              )
            })}
            {!items.length && (
              <tr>
                <td colSpan={4} className="muted">
                  None
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    )
  }

  return (
    <div className="stack">
      <div className="card">
        <h2>Worker location</h2>
        <div className="row">
          <Field id="worker-lat" label="Latitude">
            <input value={lat} onChange={(e) => setLat(e.target.value)} aria-label="Latitude" />
          </Field>
          <Field id="worker-lon" label="Longitude">
            <input value={lon} onChange={(e) => setLon(e.target.value)} aria-label="Longitude" />
          </Field>
        </div>
        <div className="actions">
          <button type="button" onClick={() => recordLocation().catch((e) => setMsg(e.message))}>
            Record location
          </button>
          <button type="button" onClick={() => load().catch((e) => setMsg(e.message))}>
            Refresh work
          </button>
        </div>
        {msg && <div className="msg">{msg}</div>}
      </div>
      {work && (
        <>
          {renderTable('Pending', work.pending || [])}
          {renderTable('In progress', work.inProgress || [])}
          {renderTable('Completed', work.completed || [])}
        </>
      )}
    </div>
  )
}

function OpsView() {
  const [ops, setOps] = useState<OperationsState | null>(null)
  const [msg, setMsg] = useState('')
  const [resourceType, setResourceType] = useState('worker')
  const [resourceId, setResourceId] = useState('')
  const [reason, setReason] = useState('unavailable')

  const load = useCallback(async () => {
    const d = await api<OperationsState>('/read-operations-state', { method: 'POST', body: {} })
    setOps(d)
  }, [])

  useEffect(() => {
    load().catch((e) => setMsg(e.message))
    const t = setInterval(() => load().catch(() => {}), 15000)
    return () => clearInterval(t)
  }, [load])

  async function reportDisruption() {
    try {
      const d = await api<any>('/report-disruption', {
        method: 'POST',
        body: { resourceType, resourceId, reason, autoReplan: true, idempotencyKey: idemKey('dis') },
      })
      setMsg(`Disruption ${d.disruptionId}: ${d.replanStatus}, affected ${d.affectedSampleIds?.length || 0}`)
      await load()
