function MapPanel({ ops }: { ops?: OperationsState }) {
  const ref = useRef<HTMLDivElement>(null)
  const mapRef = useRef<MapLibreMap | null>(null)
  const markers = useRef<Marker[]>([])

  useEffect(() => {
    if (!ref.current || mapRef.current) return
    try {
      const map = new maplibregl.Map({
        container: ref.current,
        style: '/map/style.json',
        center: [77.5946, 12.9716],
        zoom: 11,
      })
      map.addControl(new maplibregl.NavigationControl())
      mapRef.current = map
    } catch (e) {
      console.warn('map init failed', e)
    }
    return () => {
      markers.current.forEach((m) => m.remove())
      mapRef.current?.remove()
      mapRef.current = null
    }
  }, [])

  useEffect(() => {
    const map = mapRef.current
    if (!map || !ops) return
    markers.current.forEach((m) => m.remove())
    markers.current = []
    ;(ops.locations || []).forEach((loc: any) => {
      const c = loc.coordinate
      if (!c) return
      const el = document.createElement('div')
      el.title = loc.name
      el.style.width = '12px'
      el.style.height = '12px'
      el.style.borderRadius = '50%'
      el.style.background = loc.active ? '#38bdf8' : '#64748b'
      el.style.border = '2px solid #fff'
      const m = new maplibregl.Marker({ element: el }).setLngLat([c.longitude, c.latitude]).addTo(map)
      markers.current.push(m)
    })
    ;(ops.samples || []).forEach((s: any) => {
      const loc = s.latestLocation || s.origin
      if (!loc) return
      const m = new maplibregl.Marker({ color: s.locationStale ? '#ef4444' : '#22c55e' })
        .setLngLat([loc.longitude, loc.latitude])
        .addTo(map)
      markers.current.push(m)
    })
    ;(ops.workers || []).forEach((w: any) => {
      const loc = w.latestLocation
      if (!loc) return
      const m = new maplibregl.Marker({ color: '#a78bfa' }).setLngLat([loc.longitude, loc.latitude]).addTo(map)
      markers.current.push(m)
    })
  }, [ops])

  return (
    <div className="card">
      <h2>Live map (Bangalore offline tiles)</h2>
      <div id="map" ref={ref} role="img" aria-label="Network map" />
      <p className="muted">Blue nodes · green fresh samples · red stale samples · purple workers</p>
    </div>
  )
}

function RequestsView({
  activeRole,
  sampleTypes,
  setSampleTypes,
  onCreated,
}: {
  activeRole: string
  sampleTypes: SampleType[]
  setSampleTypes: (t: SampleType[]) => void
  onCreated: (sampleId: string) => void
}) {
  const now = useMemo(() => new Date(), [])
  const [originType, setOriginType] = useState('home')
  const [lat, setLat] = useState('12.9716')
  const [lon, setLon] = useState('77.5946')
  const [sampleTypeId, setSampleTypeId] = useState('')
  const [sampleTypeName, setSampleTypeName] = useState('Amber')
  const [earliest, setEarliest] = useState(toLocalInputValue(now))
  const [latest, setLatest] = useState(toLocalInputValue(new Date(now.getTime() + 4 * 3600_000)))
  const [deadline, setDeadline] = useState(toLocalInputValue(new Date(now.getTime() + 12 * 3600_000)))
  const [msg, setMsg] = useState('')
  const [msgOk, setMsgOk] = useState(false)
  const [typesLoaded, setTypesLoaded] = useState(false)

  // Ensure we have sample type IDs — admin can list via bootstrap seed; try snapshot / create known types by name via ops
  useEffect(() => {
    if (typesLoaded) return
    ;(async () => {
      try {
        // Attempt to read via admin network bootstrap: create-sample-type is admin only; seed should have types.
        // We store type list in localStorage after first successful check response that echoes type.
        const cached = localStorage.getItem('ls_sample_types')
        if (cached) {
          const parsed = JSON.parse(cached)
          if (Array.isArray(parsed) && parsed.length) {
            setSampleTypes(parsed)
            setSampleTypeId(parsed[0].sampleTypeId)
            setTypesLoaded(true)
            return
          }
        }
      } catch {
        /* ignore */
      }
      // If administrator, try to ensure default types exist by calling create (may 409)
      if (activeRole === 'administrator') {
        const defaults = [
          { name: 'Amber', containerType: 'standard', temperatureMinC: 2, temperatureMaxC: 25, qualifiedCollectorRequired: true, requiredQualification: 'Amber' },
          { name: 'Indigo', containerType: 'standard', temperatureMinC: 2, temperatureMaxC: 25, qualifiedCollectorRequired: true, requiredQualification: 'Indigo', incompatibleSampleTypeNames: ['Amber'] },
          { name: 'Frost', containerType: 'cooled', temperatureMinC: 2, temperatureMaxC: 8, qualifiedCollectorRequired: true, requiredQualification: 'Frost', requiresCooled: true },
          { name: 'Pulse', containerType: 'standard', temperatureMinC: 2, temperatureMaxC: 25, qualifiedCollectorRequired: true, requiredQualification: 'Pulse', timeCritical: true },
        ]
        const found: SampleType[] = []
        for (const d of defaults) {
          try {
            const res = await api<any>('/create-sample-type', {
              method: 'POST',
              body: {
                name: d.name,
                qualifiedCollectorRequired: d.qualifiedCollectorRequired,
                requiredQualification: d.requiredQualification,
                containerType: d.containerType,
                temperatureMinC: d.temperatureMinC,
                temperatureMaxC: d.temperatureMaxC,
                incompatibleSampleTypeIds: [],
                active: true,
              },
            })
            found.push({ sampleTypeId: res.sampleTypeId, name: res.name || d.name })
          } catch {
            /* already exists — ignore */
          }
        }
        if (found.length) {
          setSampleTypes(found)
          setSampleTypeId(found[0].sampleTypeId)
          localStorage.setItem('ls_sample_types', JSON.stringify(found))
        }
      }
      setTypesLoaded(true)
    })()
  }, [activeRole, typesLoaded, setSampleTypes])

  async function resolveTypeId(): Promise<string> {
    if (sampleTypeId) return sampleTypeId
    const match = sampleTypes.find((t) => t.name.toLowerCase() === sampleTypeName.toLowerCase())
    if (match) return match.sampleTypeId
    throw new Error('Select a sample type (or sign in as administrator once to seed types)')
  }

  async function check() {
    setMsg('')
    try {
      const st = await resolveTypeId()
      const body = {
        origin: { latitude: Number(lat), longitude: Number(lon) },
        originType,
        sampleTypeId: st,
        requestedAt: new Date().toISOString(),
        earliestCollectionAt: fromLocalInputValue(earliest),
        latestCollectionAt: fromLocalInputValue(latest),
        deliveryDeadline: fromLocalInputValue(deadline),
      }
      const d = await api<any>('/check-serviceability', { method: 'POST', body })
      setMsgOk(d.serviceable || d.serviceability === 'serviceable')
      setMsg(
        `Serviceability: ${d.serviceability || (d.serviceable ? 'serviceable' : 'unserviceable')}` +
          (d.reason || d.serviceabilityReason ? ` — ${d.reason || d.serviceabilityReason}` : '') +
          (d.version ? ` (version ${d.version})` : ''),
      )
    } catch (e: any) {
      setMsgOk(false)
      setMsg(e.message || 'Check failed')
    }
  }

  async function create() {
    setMsg('')
    try {
      const st = await resolveTypeId()
      const body = {
        origin: { latitude: Number(lat), longitude: Number(lon) },
        originType,
        sampleTypeId: st,
        requestedAt: new Date().toISOString(),
        earliestCollectionAt: fromLocalInputValue(earliest),
        latestCollectionAt: fromLocalInputValue(latest),
        deliveryDeadline: fromLocalInputValue(deadline),
        idempotencyKey: idemKey('req'),
      }
      const d = await api<any>('/create-collection-request', { method: 'POST', body })
      setMsgOk(true)
      setMsg(`Created sample ${d.sampleId} (${d.serviceability})`)
      if (d.sampleId) onCreated(d.sampleId)
    } catch (e: any) {
      setMsgOk(false)
      setMsg(e.message || 'Create failed')
    }
  }

  return (
    <div className="card">
      <h2>Collection request</h2>
      <p className="muted">Serviceability is a dry run — it does not create a request or reserve capacity.</p>
      <div className="row">
        <Field id="origin-type" label="Origin type">
          <select value={originType} onChange={(e) => setOriginType(e.target.value)} aria-label="Origin type">
            <option value="home">home</option>
            <option value="clinic">clinic</option>
            <option value="node">node</option>
          </select>
        </Field>
        <Field id="sample-type" label="Sample type">
          {sampleTypes.length ? (
            <select
              value={sampleTypeId}
              onChange={(e) => setSampleTypeId(e.target.value)}
              aria-label="Sample type"
            >
              {sampleTypes.map((t) => (
                <option key={t.sampleTypeId} value={t.sampleTypeId}>
                  {t.name}
                </option>
              ))}
            </select>
          ) : (
            <input
              value={sampleTypeName}
              onChange={(e) => setSampleTypeName(e.target.value)}
              aria-label="Sample type"
              placeholder="Amber"
            />
          )}
        </Field>
      </div>
      <div className="row">
        <Field id="origin-lat" label="Latitude">
          <input value={lat} onChange={(e) => setLat(e.target.value)} aria-label="Latitude" />
        </Field>
        <Field id="origin-lon" label="Longitude">
          <input value={lon} onChange={(e) => setLon(e.target.value)} aria-label="Longitude" />
        </Field>
      </div>
      <div className="row">
        <Field id="earliest-collection" label="Earliest collection">
          <input type="datetime-local" value={earliest} onChange={(e) => setEarliest(e.target.value)} aria-label="Earliest collection" />
        </Field>
        <Field id="latest-collection" label="Latest collection">
          <input type="datetime-local" value={latest} onChange={(e) => setLatest(e.target.value)} aria-label="Latest collection" />
        </Field>
        <Field id="delivery-deadline" label="Delivery deadline">
          <input type="datetime-local" value={deadline} onChange={(e) => setDeadline(e.target.value)} aria-label="Delivery deadline" />
        </Field>
      </div>
      <div className="actions">
        <button type="button" onClick={check}>
          Check serviceability
        </button>
        <button type="button" className="primary" onClick={create}>
          Create request
        </button>
      </div>
      {msg && <div className={`msg ${msgOk ? 'ok' : 'err'}`}>{msg}</div>}
    </div>
  )
}

function WorkView({ onOpenSample, reloadBoot }: { onOpenSample: (id: string) => void; reloadBoot: () => void }) {
  const [work, setWork] = useState<{ pending: any[]; inProgress: any[]; completed: any[] } | null>(null)
  const [msg, setMsg] = useState('')
  const [lat, setLat] = useState('12.9716')
  const [lon, setLon] = useState('77.5946')

  const load = useCallback(async () => {
    const d = await api<any>('/list-role-work', { method: 'POST', body: {} })
    setWork(d)
  }, [])

  useEffect(() => {
    load().catch((e) => setMsg(e.message))
  }, [load])

  async function accept(id: string) {
    await api('/accept-assignment', { method: 'POST', body: { assignmentId: id, idempotencyKey: idemKey('accept') } })
    await load()
    reloadBoot()
  }
  async function decline(id: string) {
    await api('/decline-assignment', { method: 'POST', body: { assignmentId: id, idempotencyKey: idemKey('decline') } })
    await load()
  }
  async function collect(it: any) {
    await api('/collect-and-seal-sample', {
      method: 'POST',
      body: {
        assignmentId: it.assignmentId,
        sampleId: it.sampleId,
        sealedAt: new Date().toISOString(),
        containerType: 'standard',
        temperatureC: 5,
        coordinate: { latitude: Number(lat), longitude: Number(lon) },
        idempotencyKey: idemKey('seal'),
      },
    })
    await load()
  }
  async function confirmReceipt(it: any) {
    await api('/confirm-laboratory-receipt', {
      method: 'POST',
      body: {
        assignmentId: it.assignmentId,
        sampleId: it.sampleId,
        receivedAt: new Date().toISOString(),
        idempotencyKey: idemKey('recv'),
      },
    })
    await load()
  }
  async function recordLocation() {
    await api('/record-worker-location', {
      method: 'POST',
      body: {
        coordinate: { latitude: Number(lat), longitude: Number(lon) },
        recordedAt: new Date().toISOString(),
      },
    })
    setMsg('Location recorded')
  }

  function renderTable(title: string, items: any[]) {
    return (
      <div className="card" key={title}>
        <h2>
          {title} ({items.length})
        </h2>
        <table>
          <thead>
            <tr>
              <th>Type</th>
              <th>ID</th>
              <th>Status</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {items.map((it, i) => {
              const id = it.assignmentId || it.sampleId || it.journeyId || String(i)
              return (
                <tr key={id + i}>
                  <td>{it.type || it.kind || ''}</td>
                  <td>{String(id).slice(0, 8)}</td>
                  <td>{it.status}</td>
                  <td>
                    <div className="actions">
                      {it.sampleId && (
                        <button type="button" onClick={() => onOpenSample(it.sampleId)}>
                          Open
                        </button>
                      )}
                      {it.assignmentId && it.status === 'offered' && (
                        <>
                          <button type="button" className="primary" onClick={() => accept(it.assignmentId).catch((e) => setMsg(e.message))}>
                            Accept
                          </button>
                          <button type="button" onClick={() => decline(it.assignmentId).catch((e) => setMsg(e.message))}>
                            Decline
                          </button>
                        </>
                      )}
                      {it.assignmentId && it.kind === 'collection' && (it.status === 'accepted' || it.status === 'in_progress') && (
                        <button type="button" className="primary" onClick={() => collect(it).catch((e) => setMsg(e.message))}>
                          Collect & seal
                        </button>
                      )}
                      {it.assignmentId && it.kind === 'laboratory' && (it.status === 'accepted' || it.status === 'in_progress') && (
                        <button type="button" className="primary" onClick={() => confirmReceipt(it).catch((e) => setMsg(e.message))}>
                          Confirm receipt
                        </button>
                      )}
                    </div>
                  </td>
                </tr>
              )
            })}
            {!items.length && (
              <tr>
                <td colSpan={4} className="muted">
                  None
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    )
  }

  return (
    <div className="stack">
      <div className="card">
        <h2>Worker location</h2>
        <div className="row">
          <Field id="worker-lat" label="Latitude">
            <input value={lat} onChange={(e) => setLat(e.target.value)} aria-label="Latitude" />
          </Field>
          <Field id="worker-lon" label="Longitude">
            <input value={lon} onChange={(e) => setLon(e.target.value)} aria-label="Longitude" />
          </Field>
        </div>
        <div className="actions">
          <button type="button" onClick={() => recordLocation().catch((e) => setMsg(e.message))}>
            Record location
          </button>
          <button type="button" onClick={() => load().catch((e) => setMsg(e.message))}>
            Refresh work
          </button>
        </div>
        {msg && <div className="msg">{msg}</div>}
      </div>
      {work && (
        <>
          {renderTable('Pending', work.pending || [])}
          {renderTable('In progress', work.inProgress || [])}
          {renderTable('Completed', work.completed || [])}
        </>
      )}
    </div>
  )
}

function OpsView() {
  const [ops, setOps] = useState<OperationsState | null>(null)
  const [msg, setMsg] = useState('')
  const [resourceType, setResourceType] = useState('worker')
  const [resourceId, setResourceId] = useState('')
  const [reason, setReason] = useState('unavailable')

  const load = useCallback(async () => {
    const d = await api<OperationsState>('/read-operations-state', { method: 'POST', body: {} })
    setOps(d)
  }, [])

  useEffect(() => {
    load().catch((e) => setMsg(e.message))
    const t = setInterval(() => load().catch(() => {}), 15000)
    return () => clearInterval(t)
  }, [load])

  async function reportDisruption() {
    try {
      const d = await api<any>('/report-disruption', {
        method: 'POST',
        body: { resourceType, resourceId, reason, autoReplan: true, idempotencyKey: idemKey('dis') },
      })
      setMsg(`Disruption ${d.disruptionId}: ${d.replanStatus}, affected ${d.affectedSampleIds?.length || 0}`)
      await load()
    } catch (e: any) {
      setMsg(e.message)
    }
  }

  return (
    <div className="stack">
      <MapPanel ops={ops || undefined} />
      <div className="card">
        <h2>Operations monitor</h2>
        {ops ? (
          <p>
            {(ops.samples || []).length} samples · {(ops.workers || []).length} workers · {(ops.exceptions || []).length}{' '}
            exceptions · {(ops.locations || []).length} locations
          </p>
        ) : (
          <p className="muted">Loading…</p>
        )}
        {msg && <div className="msg">{msg}</div>}
        <table>
          <thead>
            <tr>
              <th>Sample</th>
              <th>Status</th>
              <th>Holder</th>
              <th>Location</th>
              <th>Stale</th>
            </tr>
          </thead>
          <tbody>
            {(ops?.samples || []).slice(0, 50).map((s) => (
              <tr key={s.sampleId}>
                <td>{String(s.sampleId).slice(0, 8)}</td>
                <td>{s.status}</td>
                <td>{s.currentHolderId ? String(s.currentHolderId).slice(0, 8) : '—'}</td>
                <td>
                  {s.latestLocation
                    ? `${s.latestLocation.latitude.toFixed(4)}, ${s.latestLocation.longitude.toFixed(4)}`
                    : '—'}
                </td>
                <td className={s.locationStale ? 'stale' : 'fresh'}>{String(!!s.locationStale)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <div className="card">
        <h2>Exceptions</h2>
        <table>
          <thead>
            <tr>
              <th>Sample</th>
              <th>Kind</th>
              <th>Reason</th>
              <th>Status</th>
            </tr>
          </thead>
          <tbody>
            {(ops?.exceptions || []).map((e, i) => (
              <tr key={i}>
                <td>{String(e.sampleId || '').slice(0, 8)}</td>
                <td>{e.kind || '—'}</td>
                <td>{e.reason || '—'}</td>
                <td>{e.status}</td>
              </tr>
            ))}
            {!(ops?.exceptions || []).length && (
              <tr>
                <td colSpan={4} className="muted">
                  No exceptions
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
      <div className="card">
        <h2>Report disruption / replan</h2>
        <div className="row">
          <Field id="resource-type" label="Resource type">
            <select value={resourceType} onChange={(e) => setResourceType(e.target.value)} aria-label="Resource type">
              <option value="worker">worker</option>
              <option value="location">location</option>
              <option value="connection">connection</option>
              <option value="laboratory">laboratory</option>
            </select>
          </Field>
          <Field id="resource-id" label="Resource ID">
            <input value={resourceId} onChange={(e) => setResourceId(e.target.value)} aria-label="Resource ID" />
          </Field>
          <Field id="disruption-reason" label="Reason">
            <input value={reason} onChange={(e) => setReason(e.target.value)} aria-label="Reason" />
          </Field>
        </div>
        <div className="actions">
          <button type="button" className="primary" onClick={reportDisruption}>
            Report & replan
          </button>
        </div>
      </div>
    </div>
  )
}

function NetworkView({
  activeRole,
  locations,
  onRefresh,
}: {
  activeRole: string
  locations: any[]
  onRefresh: () => void
}) {
  const [name, setName] = useState('Collection Centre')
  const [lat, setLat] = useState('12.9716')
  const [lon, setLon] = useState('77.5946')
  const [fn, setFn] = useState('collection_point')
  const [msg, setMsg] = useState('')
  const [opsLocs, setOpsLocs] = useState(locations)

  useEffect(() => setOpsLocs(locations), [locations])

  async function createLocation() {
    try {
      const d = await api<any>('/create-location', {
        method: 'POST',
        body: {
          name,
          coordinate: { latitude: Number(lat), longitude: Number(lon) },
          coverageKm: 5,
          handlingMinutes: 10,
          active: true,
          functions: [fn],
        },
      })
      setMsg('Created ' + d.locationId)
      onRefresh()
      try {
        const ops = await api<OperationsState>('/read-operations-state', { method: 'POST', body: {} })
        setOpsLocs(ops.locations || [])
      } catch {
        /* ignore */
      }
    } catch (e: any) {
      setMsg(e.message)
    }
  }

  async function toggleActive(loc: any) {
    try {
      await api('/set-location-status', {
        method: 'POST',
        body: { locationId: loc.locationId, active: !loc.active },
      })
      onRefresh()
      const ops = await api<OperationsState>('/read-operations-state', { method: 'POST', body: {} })
      setOpsLocs(ops.locations || [])
    } catch (e: any) {
      setMsg(e.message)
    }
  }

  return (
    <div className="stack">
      {(activeRole === 'administrator' || activeRole === 'dispatcher') && (
        <div className="card">
          <h2>Create location</h2>
          <Field id="loc-name" label="Name">
            <input value={name} onChange={(e) => setName(e.target.value)} aria-label="Name" />
          </Field>
          <div className="row">
            <Field id="loc-lat" label="Latitude">
              <input value={lat} onChange={(e) => setLat(e.target.value)} aria-label="Latitude" />
            </Field>
            <Field id="loc-lon" label="Longitude">
              <input value={lon} onChange={(e) => setLon(e.target.value)} aria-label="Longitude" />
            </Field>
            <Field id="loc-function" label="Function">
              <select value={fn} onChange={(e) => setFn(e.target.value)} aria-label="Function">
                <option value="collection_point">collection_point</option>
                <option value="transfer_point">transfer_point</option>
                <option value="hub">hub</option>
                <option value="laboratory">laboratory</option>
              </select>
            </Field>
          </div>
          <div className="actions">
            <button type="button" className="primary" onClick={createLocation}>
              Create location
            </button>
          </div>
          {msg && <div className="msg">{msg}</div>}
        </div>
      )}
      <div className="card">
        <h2>Locations</h2>
        <table>
          <thead>
            <tr>
              <th>Name</th>
              <th>Active</th>
              <th>Functions</th>
              <th>Capacity</th>
              <th></th>
            </tr>
          </thead>
          <tbody>
            {opsLocs.map((l) => (
              <tr key={l.locationId}>
                <td>{l.name}</td>
                <td>{String(l.active)}</td>
                <td>
                  {Object.entries(l.functions || {})
                    .filter(([, v]) => v)
                    .map(([k]) => k)
                    .join(', ')}
                </td>
                <td>
                  {l.capacity
                    ? `${l.capacity.availableUnits}/${l.capacity.capacityUnits} (cooled ${l.capacity.cooledAvailableUnits}/${l.capacity.cooledCapacityUnits})`
                    : '—'}
                </td>
                <td>
                  {(activeRole === 'administrator' || activeRole === 'dispatcher') && (
                    <button type="button" onClick={() => toggleActive(l)}>
                      {l.active ? 'Deactivate' : 'Activate'}
                    </button>
                  )}
                </td>
              </tr>
            ))}
            {!opsLocs.length && (
              <tr>
                <td colSpan={5} className="muted">
                  No locations loaded (need dispatcher/admin operations view)
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  )
}

function AuditView() {
  const [q, setQ] = useState('')
  const [entityId, setEntityId] = useState('')
  const [entries, setEntries] = useState<any[]>([])
  const [total, setTotal] = useState(0)
  const [msg, setMsg] = useState('')

  async function search() {
    try {
      const body: any = { limit: 100, order: 'newest_first' }
      if (q) body.action = q
      if (entityId) body.entityId = entityId
      const d = await api<any>('/search-audit-trail', { method: 'POST', body })
      setEntries(d.entries || [])
      setTotal(d.total || 0)
    } catch (e: any) {
      setMsg(e.message)
    }
  }

  useEffect(() => {
    search().catch(() => {})
  }, [])

  return (
    <div className="card">
      <h2>Audit trail</h2>
      <div className="row">
        <Field id="audit-action" label="Action filter">
          <input value={q} onChange={(e) => setQ(e.target.value)} aria-label="Action filter" placeholder="e.g. accept_assignment" />
        </Field>
        <Field id="audit-entity-id" label="Entity ID">
          <input value={entityId} onChange={(e) => setEntityId(e.target.value)} aria-label="Entity ID" />
        </Field>
      </div>
      <div className="actions">
        <button type="button" className="primary" onClick={search}>
          Search
        </button>
      </div>
      {msg && <div className="msg err">{msg}</div>}
      <p className="muted">Total: {total}</p>
      <table>
        <thead>
          <tr>
            <th>Time</th>
            <th>Action</th>
            <th>Role</th>
            <th>Entity</th>
            <th>OK</th>
          </tr>
        </thead>
        <tbody>
          {entries.map((e) => (
            <tr key={e.auditId}>
              <td>{String(e.occurredAt || '').slice(0, 19)}</td>
              <td>{e.action}</td>
              <td>{e.role || e.actorRole}</td>
              <td>
                {e.entityType}:{String(e.entityId || '').slice(0, 8)}
              </td>
              <td>{String(e.success)}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

function UsersView({ activeRole, locations }: { activeRole: string; locations: any[] }) {
  const [username, setUsername] = useState('')
  const [password, setPassword] = useState('password123')
  const [fullName, setFullName] = useState('')
  const [role, setRole] = useState<Role>('requester')
  const [assignedLocationId, setAssignedLocationId] = useState('')
  const [msg, setMsg] = useState('')

  if (activeRole !== 'administrator') {
    return (
      <div className="card">
        <h2>Users</h2>
        <p className="muted">Only administrators can manage users, roles and certifications.</p>
      </div>
    )
  }

  async function createUser() {
    try {
      const body: any = {
        username,
        initialPassword: password,
        fullName: fullName || username,
        roles: [role],
        qualifications: role === 'collection_professional' ? ['Amber', 'Indigo', 'Frost', 'Pulse'] : [],
        certifications:
          role === 'collection_professional'
            ? [
                { code: 'Amber', active: true },
                { code: 'Indigo', active: true },
                { code: 'Frost', active: true },
                { code: 'Pulse', active: true },
              ]
            : [],
        active: true,
      }
      if (assignedLocationId && (role === 'node_handler' || role === 'laboratory_team')) {
        body.assignedLocationId = assignedLocationId
      }
      const d = await api<any>('/create-user', { method: 'POST', body })
      setMsg('Created user ' + d.userId)
    } catch (e: any) {
      setMsg(e.message)
    }
  }

  return (
    <div className="card">
      <h2>Create user</h2>
      <Field id="new-username" label="Username">
        <input value={username} onChange={(e) => setUsername(e.target.value)} aria-label="Username" />
      </Field>
      <Field id="new-password" label="Password">
        <input type="password" value={password} onChange={(e) => setPassword(e.target.value)} aria-label="Password" />
      </Field>
      <Field id="new-fullname" label="Full name">
        <input value={fullName} onChange={(e) => setFullName(e.target.value)} aria-label="Full name" />
      </Field>
      <Field id="new-role" label="Role">
        <select value={role} onChange={(e) => setRole(e.target.value)} aria-label="Role">
          {ALL_ROLES.map((r) => (
            <option key={r} value={r}>
              {r}
            </option>
          ))}
        </select>
      </Field>
      {(role === 'node_handler' || role === 'laboratory_team') && (
        <Field id="assigned-location" label="Assigned location">
          <select value={assignedLocationId} onChange={(e) => setAssignedLocationId(e.target.value)} aria-label="Assigned location">
            <option value="">—</option>
            {locations.map((l) => (
              <option key={l.locationId} value={l.locationId}>
                {l.name}
              </option>
            ))}
          </select>
        </Field>
      )}
      <div className="actions">
        <button type="button" className="primary" onClick={createUser}>
          Create user
        </button>
      </div>
      {msg && <div className="msg">{msg}</div>}
    </div>
  )
}

function SampleDetail({
  sampleId,
  activeRole,
  onChanged,
}: {
  sampleId: string
  activeRole: string
  onChanged: () => void
}) {
  const [state, setState] = useState<any>(null)
  const [life, setLife] = useState<any>(null)
  const [journey, setJourney] = useState<any>(null)
  const [msg, setMsg] = useState('')
  const [container, setContainer] = useState('standard')
  const [temp, setTemp] = useState('5')

  const load = useCallback(async () => {
    const s = await api<any>(`/read-sample-state/${sampleId}`)
    setState(s)
    try {
      const lc = await api<any>('/read-sample-lifecycle', { method: 'POST', body: { sampleId } })
      setLife(lc)
    } catch {
      /* ignore */
    }
    if (s.activeJourneyId) {
      try {
        const j = await api<any>('/read-journey-plan', { method: 'POST', body: { journeyId: s.activeJourneyId } })
        setJourney(j)
      } catch {
        /* ignore */
      }
    }
  }, [sampleId])

  useEffect(() => {
    load().catch((e) => setMsg(e.message))
  }, [load])

  async function checkpoint() {
    try {
      await api('/record-handling-checkpoint', {
        method: 'POST',
        body: {
          sampleId,
          containerType: container,
          temperatureC: Number(temp),
          recordedAt: new Date().toISOString(),
          idempotencyKey: idemKey('chk'),
        },
      })
      setMsg('Checkpoint recorded')
      await load()
      onChanged()
    } catch (e: any) {
      setMsg(e.message)
    }
  }

  if (!state) return <div className="card">Loading sample… {msg && <span className="msg err">{msg}</span>}</div>

  return (
    <div className="stack">
      <div className="card">
        <h2>Sample {String(state.sampleId).slice(0, 8)}</h2>
        <p>
          Status: <span className="badge">{state.state?.status}</span> · Serviceability: {state.serviceability}
        </p>
        <p className={state.locationStale ? 'stale' : 'fresh'}>
          Location stale: {String(!!state.locationStale)}
          {state.latestLocation &&
            ` · ${state.latestLocation.latitude.toFixed(5)}, ${state.latestLocation.longitude.toFixed(5)}`}
          {state.locationRecordedAt && ` · updated ${state.locationRecordedAt}`}
        </p>
        <p className="muted">
          Deadline {state.deliveryDeadline} · Origin {state.originType} ({state.origin?.latitude}, {state.origin?.longitude})
        </p>
        {msg && <div className="msg">{msg}</div>}
      </div>
      <div className="card">
        <h2>Handling checkpoint</h2>
        <div className="row">
          <Field id="chk-container" label="Container type">
            <input value={container} onChange={(e) => setContainer(e.target.value)} aria-label="Container type" />
          </Field>
          <Field id="chk-temp" label="Temperature °C">
            <input value={temp} onChange={(e) => setTemp(e.target.value)} aria-label="Temperature °C" />
          </Field>
        </div>
        <div className="actions">
          <button type="button" onClick={checkpoint}>
            Record checkpoint
          </button>
          <button type="button" onClick={() => load()}>
            Refresh
          </button>
        </div>
      </div>
      {life && (
        <div className="card">
          <h2>Lifecycle</h2>
          <p>
            Sealed: {String(life.sealed)} · Holder: {life.currentHolderId ? String(life.currentHolderId).slice(0, 8) : '—'}
          </p>
          {life.exception && (
            <p className="stale">
              Exception ({life.exception.kind}): {life.exception.reason}
            </p>
          )}
        </div>
      )}
      {journey && (
        <div className="card">
          <h2>Journey plan v{journey.planVersion}</h2>
          <p className="muted">
            Mode {journey.routeMode} · status {journey.status}
          </p>
          <table>
            <thead>
              <tr>
                <th>Seq</th>
                <th>Kind</th>
                <th>From</th>
                <th>To</th>
                <th>Status</th>
              </tr>
            </thead>
            <tbody>
              {(journey.legs || journey.assignments || []).map((leg: any, i: number) => (
                <tr key={leg.assignmentId || i}>
                  <td>{leg.sequence ?? i}</td>
                  <td>{leg.kind}</td>
                  <td>{leg.fromLocationId ? String(leg.fromLocationId).slice(0, 8) : '—'}</td>
                  <td>{leg.toLocationId ? String(leg.toLocationId).slice(0, 8) : '—'}</td>
                  <td>{leg.status}</td>
                </tr>
              ))}
            </tbody>
          </table>
          {(activeRole === 'administrator' || activeRole === 'dispatcher') && journey.journeyId && (
            <div className="actions">
              <button
                type="button"
                onClick={async () => {
                  try {
                    await api('/reroute-journey', {
                      method: 'POST',
                      body: {
                        journeyId: journey.journeyId,
                        expectedPlanVersion: journey.planVersion,
                        idempotencyKey: idemKey('reroute'),
                      },
                    })
                    setMsg('Rerouted')
                    await load()
                  } catch (e: any) {
                    setMsg(e.message)
                  }
                }}
              >
                Reroute unfinished
              </button>
              <button
                type="button"
                onClick={async () => {
                  try {
                    await api('/cancel-journey', {
                      method: 'POST',
                      body: {
                        journeyId: journey.journeyId,
                        expectedPlanVersion: journey.planVersion,
                        reason: 'cancelled_by_dispatcher',
                        idempotencyKey: idemKey('cancel'),
                      },
                    })
                    setMsg('Cancelled')
                    await load()
                  } catch (e: any) {
                    setMsg(e.message)
                  }
                }}
              >
                Cancel journey
              </button>
            </div>
          )}
        </div>
      )}
      <div className="card">
        <h2>Status timeline</h2>
        <table>
          <thead>
            <tr>
              <th>Time</th>
              <th>Action</th>
              <th>Role</th>
              <th>OK</th>
            </tr>
          </thead>
          <tbody>
            {(state.timeline || []).map((t: any) => (
              <tr key={t.eventId}>
                <td>{String(t.occurredAt || '').slice(0, 19)}</td>
                <td>{t.action}</td>
                <td>{t.role}</td>
                <td>{String(t.success)}</td>
              </tr>
            ))}
            {!(state.timeline || []).length && (
              <tr>
                <td colSpan={4} className="muted">
                  No timeline events
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  )
}

