        asg, err := a.getAssignment(r.Context(), req.AssignmentID)
        if err != nil || asg.Kind != "collection" {
                writeErr(w, notFound())
                return
        }
        if asg.WorkerID == nil || *asg.WorkerID != me.ID {
                if s.ActiveRole != models.RoleAdministrator {
                        writeErr(w, httpapi.ErrForbidden)
                        return
                }
        }
        if asg.Status != "accepted" && asg.Status != "in_progress" {
                writeErr(w, httpapi.E(409, "invalid_assignment_state", "assignment not accepted"))
                return
        }
        sample, err := a.getSample(r.Context(), req.SampleID)
        if err != nil || sample.ID != asg.SampleID {
                writeErr(w, notFound())
                return
        }
        // qualification check
        st, _ := a.getSampleType(r.Context(), sample.SampleTypeID)
        if st != nil && st.QualifiedCollectorRequired {
                ok := ContainsStr(me.Qualifications, st.RequiredQualification) || ContainsStr(me.Qualifications, st.Name)
                for _, c := range me.Certifications {
                        if c.Active && (c.Code == st.RequiredQualification || c.Code == st.Name) {
                                ok = true
                        }
                }
                if !ok && s.ActiveRole != models.RoleAdministrator {
                        writeErr(w, httpapi.E(403, "not_qualified", "collector not qualified"))
                        return
                }
        }
        now := Now()
        if req.SealedAt != "" {
                if t, err := ParseTime(req.SealedAt); err == nil {
                        now = t
                }
        }
        // collection window
        if now.Before(sample.EarliestCollectionAt) || now.After(sample.LatestCollectionAt) {
                writeErr(w, httpapi.E(409, "outside_collection_window", "outside collection window"))
                return
        }
        lat, lon := sample.Origin.Latitude, sample.Origin.Longitude
        if req.Coordinate != nil {
                lat, lon = req.Coordinate.Latitude, req.Coordinate.Longitude
        }
        _, err = a.DB.Pool.Exec(r.Context(), `
                UPDATE samples SET status='sealed', sealed=true, sealed_at=$1, current_holder_id=$2,
                        latest_lat=$3, latest_lon=$4, location_recorded_at=$1 WHERE id=$5`,
                now, me.ID, lat, lon, sample.ID)
        if err != nil {
                writeErr(w, errInternal)
                return
        }
        _, _ = a.DB.Pool.Exec(r.Context(), `
                UPDATE assignments SET status='completed', completed_at=$1 WHERE id=$2`, now, asg.ID)
        // activate next assignment offer
        _ = a.offerNextAssignments(r.Context(), sample.ID)
        a.audit(r.Context(), s.UserID, s.ActiveRole, "collect_and_seal_sample", "sample", sample.ID, true, nil)
        sample, _ = a.getSample(r.Context(), sample.ID)
        writeData(w, 200, a.sampleStateJSON(r.Context(), sample))
}

