def do(path, old, new, label, count=1):
    p = Path(path)
    t = p.read_text()
    n = t.count(old)
    if n == 0:
        print(f'FAIL {label}')
        return False
    t = t.replace(old, new, count if count else n)
    p.write_text(t)
    print(f'OK {label} ({n} found, replaced {min(n, count if count else n)})')
    return True

