package app

import (
        "context"
        "log"
)

// seedBangaloreNetwork creates a default operational network around Bangalore
// when no locations exist yet. Safe to call repeatedly.
func (a *App) seedBangaloreNetwork(ctx context.Context) error {
        var n int
        if err := a.DB.Pool.QueryRow(ctx, `SELECT COUNT(*) FROM locations`).Scan(&n); err != nil {
                return err
        }
        if n > 0 {
                return nil
        }
        log.Printf("seeding Bangalore demo network")

        type loc struct {
                id, name string
                lat, lon float64
                cp, tp, hub, lab bool
                accept            []string
        }
        // Central Bangalore points within ~5km of each other for serviceability
        locs := []loc{
                {NewID(), "Indiranagar Collection Centre", 12.9784, 77.6408, true, true, false, false, nil},
