func (a *App) handleUIBootstrap(w http.ResponseWriter, r *http.Request) {
        s := SessionFrom(r.Context())
        u := UserFrom(r.Context())
        if s == nil || u == nil {
                writeErr(w, errUnauthorized())
                return
        }
        roleSelectionRequired := s.ActiveRole == "" || !ContainsStr(u.Roles, s.ActiveRole)
        userOut := map[string]interface{}{
                "userId":                 u.ID,
                "username":               u.Username,
                "roles":                  u.Roles,
                "activeRole":             s.ActiveRole,
                "roleSelectionRequired":  roleSelectionRequired,
        }
        if u.FullName != "" {
                userOut["fullName"] = u.FullName
        }
        out := map[string]interface{}{
                "user":       userOut,
                "serverTime": FormatTime(Now()),
        }
        // requester samples for requester role
        if s.ActiveRole == models.RoleRequester || s.ActiveRole == models.RoleAdministrator || s.ActiveRole == models.RoleDispatcher {
                samples := []map[string]interface{}{}
                q := `SELECT id FROM samples`
                args := []interface{}{}
                if s.ActiveRole == models.RoleRequester {
                        q += ` WHERE requester_id=$1`
                        args = append(args, u.ID)
                }
                q += ` ORDER BY created_at DESC LIMIT 100`
                rows, err := a.DB.Pool.Query(r.Context(), q, args...)
                if err == nil {
                        defer rows.Close()
                        for rows.Next() {
                                var id string
                                _ = rows.Scan(&id)
                                smp, err := a.getSample(r.Context(), id)
                                if err == nil {
                                        samples = append(samples, a.sampleStateJSON(r.Context(), smp))
                                }
                        }
                }
                out["requesterSamples"] = samples
        }
        if s.ActiveRole == models.RoleAdministrator || s.ActiveRole == models.RoleDispatcher {
                out["operations"] = a.buildOperationsState(r.Context())
        }
        writeData(w, 200, out)
}

