func (a *App) handleListRoleWork(w http.ResponseWriter, r *http.Request) {
        s, me, err := a.requireRole(r.Context())
        if err != nil {
                writeErr(w, err)
                return
        }
        var req struct {
                Role *string `json:"role"`
        }
        _ = decode(r, &req)

        pending := []map[string]interface{}{}
        inProgress := []map[string]interface{}{}
        completed := []map[string]interface{}{}

        switch s.ActiveRole {
        case models.RoleRequester:
                rows, err := a.DB.Pool.Query(r.Context(), `
                        SELECT id, status, request_id, delivery_deadline, active_journey_id FROM samples WHERE requester_id=$1 ORDER BY created_at DESC`, me.ID)
                if err == nil {
                        defer rows.Close()
                        for rows.Next() {
                                var id, status, reqID string
                                var deadline time.Time
                                var jid *string
                                _ = rows.Scan(&id, &status, &reqID, &deadline, &jid)
                                item := map[string]interface{}{
                                        "kind": "sample", "sampleId": id, "requestId": reqID, "status": status,
                                        "deliveryDeadline": FormatTime(deadline),
                                }
                                if jid != nil {
                                        item["journeyId"] = *jid
                                }
                                switch status {
                                case "received", "cancelled", "expired":
                                        completed = append(completed, item)
                                case "requested", "planned", "unserviceable":
                                        pending = append(pending, item)
                                default:
                                        inProgress = append(inProgress, item)
                                }
                        }
                }
        case models.RoleAdministrator, models.RoleDispatcher:
                rows, err := a.DB.Pool.Query(r.Context(), `
                        SELECT id, status, request_id, delivery_deadline, active_journey_id FROM samples ORDER BY created_at DESC LIMIT 500`)
