import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import maplibregl, { Map as MapLibreMap, Marker } from 'maplibre-gl'
import { Protocol } from 'pmtiles'
import 'maplibre-gl/dist/maplibre-gl.css'
import { api, fromLocalInputValue, getToken, idemKey, setToken, toLocalInputValue } from './api'

// Register PMTiles protocol once for offline Bangalore basemap.
let pmtilesRegistered = false
function ensurePmtilesProtocol() {
  if (pmtilesRegistered) return
  const protocol = new Protocol()
  maplibregl.addProtocol('pmtiles', protocol.tile)
  pmtilesRegistered = true
}

type Role =
  | 'administrator'
  | 'dispatcher'
  | 'requester'
  | 'collection_professional'
  | 'delivery_partner'
  | 'node_handler'
  | 'laboratory_team'
  | string

type Bootstrap = {
  user: {
    userId: string
    username: string
    fullName?: string
    roles: Role[]
    activeRole: Role
    roleSelectionRequired: boolean
  }
  serverTime: string
  requesterSamples?: any[]
  operations?: OperationsState
}

type OperationsState = {
  samples?: any[]
  workers?: any[]
  locations?: any[]
  connections?: any[]
  exceptions?: any[]
  journeys?: any[]
}

type SampleType = {
  sampleTypeId: string
  name: string
  containerType?: string
  temperatureMinC?: number
  temperatureMaxC?: number
}

type TabId = 'dashboard' | 'requests' | 'work' | 'ops' | 'network' | 'audit' | 'users' | 'sample'

const ALL_ROLES: Role[] = [
  'administrator',
  'dispatcher',
  'requester',
  'collection_professional',
  'delivery_partner',
  'node_handler',
  'laboratory_team',
]

function Field({
  id,
  label,
  children,
}: {
  id: string
  label: string
  children: React.ReactElement
}) {
  return (
    <div>
      <label htmlFor={id}>{label}</label>
      {React.cloneElement(children, { id, name: id, 'aria-label': label })}
    </div>
  )
}

export default function App() {
  const [token, setTok] = useState(getToken())
  const [boot, setBoot] = useState<Bootstrap | null>(null)
  const [error, setError] = useState('')
  const [tab, setTab] = useState<TabId>('dashboard')
  const [sampleTypes, setSampleTypes] = useState<SampleType[]>([])
  const [locations, setLocations] = useState<any[]>([])
  const [selectedSampleId, setSelectedSampleId] = useState('')

  const loadBootstrap = useCallback(async () => {
    const data = await api<Bootstrap>('/ui/bootstrap')
    setBoot(data)
    return data
  }, [])

  useEffect(() => {
    if (!token) {
      setBoot(null)
      return
    }
    loadBootstrap().catch(() => {
      setToken('')
      setTok('')
      setBoot(null)
    })
  }, [token, loadBootstrap])

  // Discover sample types / locations via ops or seed endpoints indirectly
  useEffect(() => {
    if (!boot) return
    ;(async () => {
      try {
        if (boot.operations?.locations) {
          setLocations(boot.operations.locations)
        }
        // admin/dispatcher can read ops for richer data
        if (boot.user.activeRole === 'administrator' || boot.user.activeRole === 'dispatcher') {
          const ops = await api<OperationsState>('/read-operations-state', { method: 'POST', body: {} })
          setLocations(ops.locations || [])
        }
      } catch {
        /* ignore */
      }
      // Fallback known names from seed via create-collection form options filled after first serviceability snapshot
      try {
        const snap = await api<any>('/read-serviceability-snapshot', { method: 'POST', body: {} })
        // snapshot may include sampleTypes
        if (Array.isArray(snap?.sampleTypes)) setSampleTypes(snap.sampleTypes)
        if (Array.isArray(snap?.regions) && !locations.length) {
          /* regions only */
        }
      } catch {
        /* requester may not have snapshot */
      }
    })()
  }, [boot])

  async function onLogin(username: string, password: string) {
    setError('')
    try {
      const d = await api<{ sessionToken: string; userId: string; roles: Role[]; activeRole: string }>(
        '/authenticate-user',
        { method: 'POST', body: { username, password } },
      )
      setToken(d.sessionToken)
      setTok(d.sessionToken)
      let role = d.activeRole
      if (!role && d.roles?.length) {
        role = d.roles.includes('administrator') ? 'administrator' : d.roles[0]
        await api('/select-active-role', { method: 'POST', body: { role } })
      }
      await loadBootstrap()
    } catch (e: any) {
      setError(e.message || 'Login failed')
    }
  }

  async function switchRole(role: string) {
    setError('')
    try {
      await api('/select-active-role', { method: 'POST', body: { role } })
      await loadBootstrap()
    } catch (e: any) {
      setError(e.message || 'Role switch failed')
    }
  }

  function logout() {
    setToken('')
    setTok('')
    setBoot(null)
  }

  if (!token || !boot) {
    return <LoginView onLogin={onLogin} error={error} />
  }

  const user = boot.user
  const activeRole = user.activeRole

  if (user.roleSelectionRequired || !activeRole) {
    return (
      <div className="login-wrap card">
        <h2>Select active role</h2>
        <p className="muted">Choose the role you are currently working under. This does not change your assigned roles.</p>
        <Field id="active-role" label="Active role">
          <select
            defaultValue=""
            onChange={(e) => e.target.value && switchRole(e.target.value)}
            aria-label="Active role"
          >
            <option value="" disabled>
              Select a role…
            </option>
            {(user.roles || []).map((r) => (
              <option key={r} value={r}>
                {r}
              </option>
            ))}
          </select>
        </Field>
        {error && <div className="msg err">{error}</div>}
        <div className="actions">
          <button type="button" onClick={logout}>
            Sign out
          </button>
        </div>
      </div>
    )
  }

  return (
    <div>
      <header className="app-header">
        <h1>Lab Sample Pickup & Delivery</h1>
        <nav aria-label="Main">
          {(
            [
              ['dashboard', 'Dashboard'],
              ['requests', 'Requests'],
              ['work', 'My Work'],
              ['ops', 'Operations'],
              ['network', 'Network'],
              ['audit', 'Audit'],
              ['users', 'Users'],
            ] as [TabId, string][]
          ).map(([id, label]) => (
            <button key={id} type="button" className={tab === id ? 'primary' : ''} onClick={() => setTab(id)}>
              {label}
            </button>
          ))}
        </nav>
        <div style={{ marginLeft: 'auto', display: 'flex', gap: '0.5rem', alignItems: 'center' }}>
          <span className="badge" title={user.userId}>
            {user.username}
          </span>
          <Field id="header-active-role" label="Active role">
            <select
              value={activeRole}
              onChange={(e) => switchRole(e.target.value)}
              aria-label="Active role"
              style={{ minWidth: 180 }}
            >
              {(user.roles || []).map((r) => (
                <option key={r} value={r}>
                  {r}
                </option>
              ))}
            </select>
          </Field>
          <button type="button" onClick={logout}>
            Sign out
          </button>
        </div>
      </header>
      <main className="layout">
        <aside className="sidebar">
          <div className="card">
            <h2>Session</h2>
            <p className="muted">
              {user.fullName || user.username}
              <br />
              Role: <strong>{activeRole}</strong>
            </p>
            <p className="muted">Server time: {boot.serverTime}</p>
          </div>
          <QuickSampleLookup
            sampleId={selectedSampleId}
            onOpen={(id) => {
              setSelectedSampleId(id)
              setTab('sample')
            }}
          />
        </aside>
        <section className="view" aria-live="polite">
          {error && <div className="msg err">{error}</div>}
          {tab === 'dashboard' && (
            <Dashboard
              boot={boot}
              activeRole={activeRole}
              onOpenSample={(id) => {
                setSelectedSampleId(id)
                setTab('sample')
              }}
            />
          )}
          {tab === 'requests' && (
            <RequestsView
              activeRole={activeRole}
              sampleTypes={sampleTypes}
              setSampleTypes={setSampleTypes}
              onCreated={(id) => {
                setSelectedSampleId(id)
                setTab('sample')
                loadBootstrap()
              }}
            />
          )}
          {tab === 'work' && (
            <WorkView
              onOpenSample={(id) => {
                setSelectedSampleId(id)
                setTab('sample')
              }}
              reloadBoot={loadBootstrap}
            />
          )}
          {tab === 'ops' && <OpsView />}
          {tab === 'network' && <NetworkView activeRole={activeRole} locations={locations} onRefresh={loadBootstrap} />}
          {tab === 'audit' && <AuditView />}
          {tab === 'users' && <UsersView activeRole={activeRole} locations={locations} />}
          {tab === 'sample' && selectedSampleId && (
            <SampleDetail sampleId={selectedSampleId} activeRole={activeRole} onChanged={loadBootstrap} />
          )}
        </section>
      </main>
    </div>
  )
}

function LoginView({
  onLogin,
  error,
}: {
  onLogin: (u: string, p: string) => void
  error: string
}) {
  const [username, setUsername] = useState('admin')
  const [password, setPassword] = useState('')
  const [busy, setBusy] = useState(false)
  return (
    <div className="login-wrap card">
      <h2>Sign in</h2>
      <p className="muted">Lab Sample Pickup & Delivery System</p>
      <Field id="login-username" label="Username">
        <input
          value={username}
          onChange={(e) => setUsername(e.target.value)}
          autoComplete="username"
          aria-label="Username"
        />
      </Field>
      <Field id="login-password" label="Password">
        <input
          type="password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          autoComplete="current-password"
          aria-label="Password"
        />
      </Field>
      <div className="actions">
        <button
          type="button"
          className="primary"
          disabled={busy}
          onClick={async () => {
            setBusy(true)
            try {
              await onLogin(username, password)
            } finally {
              setBusy(false)
            }
          }}
        >
          Sign in
        </button>
      </div>
      {error && <div className="msg err">{error}</div>}
    </div>
  )
}

function QuickSampleLookup({ sampleId, onOpen }: { sampleId: string; onOpen: (id: string) => void }) {
  const [id, setId] = useState(sampleId)
  useEffect(() => setId(sampleId), [sampleId])
  return (
    <div className="card">
      <h2>Sample lookup</h2>
      <Field id="sample-lookup-id" label="Sample ID">
        <input value={id} onChange={(e) => setId(e.target.value)} aria-label="Sample ID" placeholder="UUID" />
      </Field>
      <div className="actions">
        <button type="button" className="primary" onClick={() => id && onOpen(id.trim())}>
          Open sample
        </button>
      </div>
    </div>
  )
}

function Dashboard({
  boot,
  activeRole,
  onOpenSample,
}: {
  boot: Bootstrap
  activeRole: string
  onOpenSample: (id: string) => void
}) {
  const samples = boot.requesterSamples || boot.operations?.samples || []
  return (
    <div className="stack">
      <div className="card">
        <h2>Dashboard</h2>
        <p>
          Working as <span className="badge">{activeRole}</span>
        </p>
        <p className="muted">
          Track custody, assignments, capacity and laboratory receipt. Location freshness is highlighted when stale.
        </p>
      </div>
      <MapPanel ops={boot.operations} />
      <div className="card">
        <h2>Recent samples</h2>
        <table>
          <thead>
            <tr>
              <th>Sample</th>
              <th>Status</th>
              <th>Stale</th>
              <th></th>
            </tr>
          </thead>
          <tbody>
            {samples.slice(0, 20).map((s: any) => (
              <tr key={s.sampleId}>
                <td>{String(s.sampleId || '').slice(0, 8)}</td>
                <td>{s.status || s.state?.status}</td>
                <td className={s.locationStale ? 'stale' : 'fresh'}>{String(!!s.locationStale)}</td>
                <td>
                  <button type="button" onClick={() => onOpenSample(s.sampleId)}>
                    View
                  </button>
                </td>
              </tr>
            ))}
            {!samples.length && (
              <tr>
                <td colSpan={4} className="muted">
                  No samples yet
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  )
}

function MapPanel({ ops }: { ops?: OperationsState }) {
  const ref = useRef<HTMLDivElement>(null)
  const mapRef = useRef<MapLibreMap | null>(null)
  const markers = useRef<Marker[]>([])

  useEffect(() => {
    if (!ref.current || mapRef.current) return
    try {
      const map = new maplibregl.Map({
        container: ref.current,
        style: '/map/style.json',
        center: [77.5946, 12.9716],
        zoom: 11,
      })
      map.addControl(new maplibregl.NavigationControl())
      mapRef.current = map
    } catch (e) {
      console.warn('map init failed', e)
    }
    return () => {
      markers.current.forEach((m) => m.remove())
      mapRef.current?.remove()
      mapRef.current = null
    }
  }, [])

  useEffect(() => {
    const map = mapRef.current
    if (!map || !ops) return
    markers.current.forEach((m) => m.remove())
    markers.current = []
    ;(ops.locations || []).forEach((loc: any) => {
      const c = loc.coordinate
      if (!c) return
      const el = document.createElement('div')
      el.title = loc.name
      el.style.width = '12px'
      el.style.height = '12px'
      el.style.borderRadius = '50%'
      el.style.background = loc.active ? '#38bdf8' : '#64748b'
      el.style.border = '2px solid #fff'
      const m = new maplibregl.Marker({ element: el }).setLngLat([c.longitude, c.latitude]).addTo(map)
      markers.current.push(m)
    })
    ;(ops.samples || []).forEach((s: any) => {
      const loc = s.latestLocation || s.origin
      if (!loc) return
      const m = new maplibregl.Marker({ color: s.locationStale ? '#ef4444' : '#22c55e' })
        .setLngLat([loc.longitude, loc.latitude])
        .addTo(map)
      markers.current.push(m)
    })
    ;(ops.workers || []).forEach((w: any) => {
      const loc = w.latestLocation
      if (!loc) return
      const m = new maplibregl.Marker({ color: '#a78bfa' }).setLngLat([loc.longitude, loc.latitude]).addTo(map)
      markers.current.push(m)
    })
  }, [ops])

  return (
    <div className="card">
      <h2>Live map (Bangalore offline tiles)</h2>
      <div id="map" ref={ref} role="img" aria-label="Network map" />
      <p className="muted">Blue nodes · green fresh samples · red stale samples · purple workers</p>
    </div>
  )
}

function RequestsView({
  activeRole,
  sampleTypes,
  setSampleTypes,
  onCreated,
}: {
  activeRole: string
  sampleTypes: SampleType[]
  setSampleTypes: (t: SampleType[]) => void
  onCreated: (sampleId: string) => void
}) {
  const now = useMemo(() => new Date(), [])
  const [originType, setOriginType] = useState('home')
  const [lat, setLat] = useState('12.9716')
  const [lon, setLon] = useState('77.5946')
  const [sampleTypeId, setSampleTypeId] = useState('')
  const [sampleTypeName, setSampleTypeName] = useState('Amber')
  const [earliest, setEarliest] = useState(toLocalInputValue(now))
  const [latest, setLatest] = useState(toLocalInputValue(new Date(now.getTime() + 4 * 3600_000)))
  const [deadline, setDeadline] = useState(toLocalInputValue(new Date(now.getTime() + 12 * 3600_000)))
  const [msg, setMsg] = useState('')
  const [msgOk, setMsgOk] = useState(false)
  const [typesLoaded, setTypesLoaded] = useState(false)

  // Ensure we have sample type IDs — admin can list via bootstrap seed; try snapshot / create known types by name via ops
  useEffect(() => {
    if (typesLoaded) return
    ;(async () => {
      try {
        // Attempt to read via admin network bootstrap: create-sample-type is admin only; seed should have types.
        // We store type list in localStorage after first successful check response that echoes type.
        const cached = localStorage.getItem('ls_sample_types')
        if (cached) {
          const parsed = JSON.parse(cached)
          if (Array.isArray(parsed) && parsed.length) {
            setSampleTypes(parsed)
            setSampleTypeId(parsed[0].sampleTypeId)
            setTypesLoaded(true)
            return
          }
        }
      } catch {
        /* ignore */
      }
      // If administrator, try to ensure default types exist by calling create (may 409)
      if (activeRole === 'administrator') {
        const defaults = [
          { name: 'Amber', containerType: 'standard', temperatureMinC: 2, temperatureMaxC: 25, qualifiedCollectorRequired: true, requiredQualification: 'Amber' },
          { name: 'Indigo', containerType: 'standard', temperatureMinC: 2, temperatureMaxC: 25, qualifiedCollectorRequired: true, requiredQualification: 'Indigo', incompatibleSampleTypeNames: ['Amber'] },
          { name: 'Frost', containerType: 'cooled', temperatureMinC: 2, temperatureMaxC: 8, qualifiedCollectorRequired: true, requiredQualification: 'Frost', requiresCooled: true },
          { name: 'Pulse', containerType: 'standard', temperatureMinC: 2, temperatureMaxC: 25, qualifiedCollectorRequired: true, requiredQualification: 'Pulse', timeCritical: true },
        ]
        const found: SampleType[] = []
        for (const d of defaults) {
          try {
            const res = await api<any>('/create-sample-type', {
              method: 'POST',
              body: {
                name: d.name,
                qualifiedCollectorRequired: d.qualifiedCollectorRequired,
                requiredQualification: d.requiredQualification,
                containerType: d.containerType,
                temperatureMinC: d.temperatureMinC,
                temperatureMaxC: d.temperatureMaxC,
                incompatibleSampleTypeIds: [],
                active: true,
              },
            })
            found.push({ sampleTypeId: res.sampleTypeId, name: res.name || d.name })
          } catch {
            /* already exists — ignore */
          }
        }
        if (found.length) {
          setSampleTypes(found)
          setSampleTypeId(found[0].sampleTypeId)
          localStorage.setItem('ls_sample_types', JSON.stringify(found))
        }
      }
      setTypesLoaded(true)
    })()
  }, [activeRole, typesLoaded, setSampleTypes])

  async function resolveTypeId(): Promise<string> {
    if (sampleTypeId) return sampleTypeId
    const match = sampleTypes.find((t) => t.name.toLowerCase() === sampleTypeName.toLowerCase())
    if (match) return match.sampleTypeId
    throw new Error('Select a sample type (or sign in as administrator once to seed types)')
  }

  async function check() {
    setMsg('')
    try {
      const st = await resolveTypeId()
      const body = {
        origin: { latitude: Number(lat), longitude: Number(lon) },
        originType,
        sampleTypeId: st,
        requestedAt: new Date().toISOString(),
        earliestCollectionAt: fromLocalInputValue(earliest),
        latestCollectionAt: fromLocalInputValue(latest),
        deliveryDeadline: fromLocalInputValue(deadline),
      }
      const d = await api<any>('/check-serviceability', { method: 'POST', body })
      setMsgOk(d.serviceable || d.serviceability === 'serviceable')
      setMsg(
        `Serviceability: ${d.serviceability || (d.serviceable ? 'serviceable' : 'unserviceable')}` +
          (d.reason || d.serviceabilityReason ? ` — ${d.reason || d.serviceabilityReason}` : '') +
          (d.version ? ` (version ${d.version})` : ''),
      )
    } catch (e: any) {
      setMsgOk(false)
      setMsg(e.message || 'Check failed')
    }
  }

  async function create() {
    setMsg('')
    try {
      const st = await resolveTypeId()
      const body = {
        origin: { latitude: Number(lat), longitude: Number(lon) },
        originType,
        sampleTypeId: st,
        requestedAt: new Date().toISOString(),
        earliestCollectionAt: fromLocalInputValue(earliest),
        latestCollectionAt: fromLocalInputValue(latest),
        deliveryDeadline: fromLocalInputValue(deadline),
        idempotencyKey: idemKey('req'),
      }
      const d = await api<any>('/create-collection-request', { method: 'POST', body })
      setMsgOk(true)
      setMsg(`Created sample ${d.sampleId} (${d.serviceability})`)
      if (d.sampleId) onCreated(d.sampleId)
    } catch (e: any) {
      setMsgOk(false)
      setMsg(e.message || 'Create failed')
    }
  }

  return (
    <div className="card">
      <h2>Collection request</h2>
      <p className="muted">Serviceability is a dry run — it does not create a request or reserve capacity.</p>
      <div className="row">
        <Field id="origin-type" label="Origin type">
          <select value={originType} onChange={(e) => setOriginType(e.target.value)} aria-label="Origin type">
            <option value="home">home</option>
            <option value="clinic">clinic</option>
            <option value="node">node</option>
          </select>
        </Field>
        <Field id="sample-type" label="Sample type">
          {sampleTypes.length ? (
            <select
              value={sampleTypeId}
              onChange={(e) => setSampleTypeId(e.target.value)}
              aria-label="Sample type"
            >
              {sampleTypes.map((t) => (
                <option key={t.sampleTypeId} value={t.sampleTypeId}>
                  {t.name}
                </option>
              ))}
            </select>
          ) : (
            <input
              value={sampleTypeName}
              onChange={(e) => setSampleTypeName(e.target.value)}
              aria-label="Sample type"
              placeholder="Amber"
            />
          )}
        </Field>
      </div>
      <div className="row">
        <Field id="origin-lat" label="Latitude">
          <input value={lat} onChange={(e) => setLat(e.target.value)} aria-label="Latitude" />
        </Field>
        <Field id="origin-lon" label="Longitude">
          <input value={lon} onChange={(e) => setLon(e.target.value)} aria-label="Longitude" />
        </Field>
      </div>
      <div className="row">
        <Field id="earliest-collection" label="Earliest collection">
          <input type="datetime-local" value={earliest} onChange={(e) => setEarliest(e.target.value)} aria-label="Earliest collection" />
        </Field>
        <Field id="latest-collection" label="Latest collection">
          <input type="datetime-local" value={latest} onChange={(e) => setLatest(e.target.value)} aria-label="Latest collection" />
        </Field>
        <Field id="delivery-deadline" label="Delivery deadline">
          <input type="datetime-local" value={deadline} onChange={(e) => setDeadline(e.target.value)} aria-label="Delivery deadline" />
        </Field>
      </div>
      <div className="actions">
        <button type="button" onClick={check}>
          Check serviceability
        </button>
        <button type="button" className="primary" onClick={create}>
          Create request
        </button>
      </div>
      {msg && <div className={`msg ${msgOk ? 'ok' : 'err'}`}>{msg}</div>}
    </div>
  )
}

function WorkView({ onOpenSample, reloadBoot }: { onOpenSample: (id: string) => void; reloadBoot: () => void }) {
  const [work, setWork] = useState<{ pending: any[]; inProgress: any[]; completed: any[] } | null>(null)
  const [msg, setMsg] = useState('')
  const [lat, setLat] = useState('12.9716')
  const [lon, setLon] = useState('77.5946')

  const load = useCallback(async () => {
    const d = await api<any>('/list-role-work', { method: 'POST', body: {} })
    setWork(d)
  }, [])

  useEffect(() => {
    load().catch((e) => setMsg(e.message))
  }, [load])

  async function accept(id: string) {
    await api('/accept-assignment', { method: 'POST', body: { assignmentId: id, idempotencyKey: idemKey('accept') } })
    await load()
    reloadBoot()
  }
  async function decline(id: string) {
    await api('/decline-assignment', { method: 'POST', body: { assignmentId: id, idempotencyKey: idemKey('decline') } })
    await load()
  }
  async function collect(it: any) {
    await api('/collect-and-seal-sample', {
      method: 'POST',
      body: {
        assignmentId: it.assignmentId,
        sampleId: it.sampleId,
        sealedAt: new Date().toISOString(),
        containerType: 'standard',
        temperatureC: 5,
        coordinate: { latitude: Number(lat), longitude: Number(lon) },
        idempotencyKey: idemKey('seal'),
      },
    })
    await load()
  }
  async function confirmReceipt(it: any) {
    await api('/confirm-laboratory-receipt', {
      method: 'POST',
      body: {
        assignmentId: it.assignmentId,
        sampleId: it.sampleId,
        receivedAt: new Date().toISOString(),
        idempotencyKey: idemKey('recv'),
      },
    })
    await load()
  }
  async function recordLocation() {
    await api('/record-worker-location', {
      method: 'POST',
      body: {
        coordinate: { latitude: Number(lat), longitude: Number(lon) },
        recordedAt: new Date().toISOString(),
      },
    })
    setMsg('Location recorded')
  }

  function renderTable(title: string, items: any[]) {
    return (
      <div className="card" key={title}>
        <h2>
          {title} ({items.length})
        </h2>
        <table>
          <thead>
            <tr>
              <th>Type</th>
              <th>ID</th>
              <th>Status</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {items.map((it, i) => {
              const id = it.assignmentId || it.sampleId || it.journeyId || String(i)
              return (
                <tr key={id + i}>
                  <td>{it.type || it.kind || ''}</td>
                  <td>{String(id).slice(0, 8)}</td>
                  <td>{it.status}</td>
                  <td>
                    <div className="actions">
                      {it.sampleId && (
                        <button type="button" onClick={() => onOpenSample(it.sampleId)}>
                          Open
                        </button>
                      )}
                      {it.assignmentId && it.status === 'offered' && (
                        <>
                          <button type="button" className="primary" onClick={() => accept(it.assignmentId).catch((e) => setMsg(e.message))}>
                            Accept
                          </button>
                          <button type="button" onClick={() => decline(it.assignmentId).catch((e) => setMsg(e.message))}>
                            Decline
                          </button>
                        </>
                      )}
                      {it.assignmentId && it.kind === 'collection' && (it.status === 'accepted' || it.status === 'in_progress') && (
                        <button type="button" className="primary" onClick={() => collect(it).catch((e) => setMsg(e.message))}>
                          Collect & seal
                        </button>
                      )}
                      {it.assignmentId && it.kind === 'laboratory' && (it.status === 'accepted' || it.status === 'in_progress') && (
                        <button type="button" className="primary" onClick={() => confirmReceipt(it).catch((e) => setMsg(e.message))}>
                          Confirm receipt
                        </button>
                      )}
                    </div>
                  </td>
                </tr>
              )
            })}
            {!items.length && (
              <tr>
                <td colSpan={4} className="muted">
                  None
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    )
  }

  return (
    <div className="stack">
      <div className="card">
        <h2>Worker location</h2>
        <div className="row">
          <Field id="worker-lat" label="Latitude">
            <input value={lat} onChange={(e) => setLat(e.target.value)} aria-label="Latitude" />
          </Field>
          <Field id="worker-lon" label="Longitude">
            <input value={lon} onChange={(e) => setLon(e.target.value)} aria-label="Longitude" />
          </Field>
        </div>
        <div className="actions">
          <button type="button" onClick={() => recordLocation().catch((e) => setMsg(e.message))}>
            Record location
          </button>
          <button type="button" onClick={() => load().catch((e) => setMsg(e.message))}>
            Refresh work
          </button>
        </div>
        {msg && <div className="msg">{msg}</div>}
      </div>
      {work && (
        <>
          {renderTable('Pending', work.pending || [])}
          {renderTable('In progress', work.inProgress || [])}
          {renderTable('Completed', work.completed || [])}
        </>
      )}
    </div>
  )
}

