        </table>
      </div>
      <div className="card">
        <h2>Exceptions</h2>
        <table>
          <thead>
            <tr>
              <th>Sample</th>
              <th>Kind</th>
              <th>Reason</th>
              <th>Status</th>
            </tr>
          </thead>
          <tbody>
            {(ops?.exceptions || []).map((e, i) => (
              <tr key={i}>
                <td>{String(e.sampleId || '').slice(0, 8)}</td>
                <td>{e.kind || '—'}</td>
                <td>{e.reason || '—'}</td>
                <td>{e.status}</td>
              </tr>
            ))}
            {!(ops?.exceptions || []).length && (
              <tr>
                <td colSpan={4} className="muted">
                  No exceptions
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
      <div className="card">
        <h2>Report disruption / replan</h2>
        <div className="row">
          <Field id="resource-type" label="Resource type">
            <select value={resourceType} onChange={(e) => setResourceType(e.target.value)} aria-label="Resource type">
              <option value="worker">worker</option>
              <option value="location">location</option>
              <option value="connection">connection</option>
              <option value="laboratory">laboratory</option>
            </select>
          </Field>
          <Field id="resource-id" label="Resource ID">
            <input value={resourceId} onChange={(e) => setResourceId(e.target.value)} aria-label="Resource ID" />
          </Field>
          <Field id="disruption-reason" label="Reason">
            <input value={reason} onChange={(e) => setReason(e.target.value)} aria-label="Reason" />
          </Field>
        </div>
        <div className="actions">
          <button type="button" className="primary" onClick={reportDisruption}>
            Report & replan
          </button>
        </div>
      </div>
    </div>
  )
}

function NetworkView({
  activeRole,
  locations,
  onRefresh,
}: {
  activeRole: string
  locations: any[]
  onRefresh: () => void
}) {
  const [name, setName] = useState('Collection Centre')
  const [lat, setLat] = useState('12.9716')
  const [lon, setLon] = useState('77.5946')
  const [fn, setFn] = useState('collection_point')
  const [msg, setMsg] = useState('')
  const [opsLocs, setOpsLocs] = useState(locations)

  useEffect(() => setOpsLocs(locations), [locations])

  async function createLocation() {
    try {
      const d = await api<any>('/create-location', {
        method: 'POST',
        body: {
          name,
          coordinate: { latitude: Number(lat), longitude: Number(lon) },
          coverageKm: 5,
          handlingMinutes: 10,
          active: true,
          functions: [fn],
        },
      })
      setMsg('Created ' + d.locationId)
      onRefresh()
      try {
        const ops = await api<OperationsState>('/read-operations-state', { method: 'POST', body: {} })
        setOpsLocs(ops.locations || [])
      } catch {
        /* ignore */
      }
    } catch (e: any) {
      setMsg(e.message)
    }
  }

  async function toggleActive(loc: any) {
    try {
      await api('/set-location-status', {
        method: 'POST',
        body: { locationId: loc.locationId, active: !loc.active },
      })
      onRefresh()
      const ops = await api<OperationsState>('/read-operations-state', { method: 'POST', body: {} })
      setOpsLocs(ops.locations || [])
    } catch (e: any) {
      setMsg(e.message)
    }
  }

  return (
    <div className="stack">
      {(activeRole === 'administrator' || activeRole === 'dispatcher') && (
        <div className="card">
          <h2>Create location</h2>
          <Field id="loc-name" label="Name">
            <input value={name} onChange={(e) => setName(e.target.value)} aria-label="Name" />
          </Field>
          <div className="row">
            <Field id="loc-lat" label="Latitude">
              <input value={lat} onChange={(e) => setLat(e.target.value)} aria-label="Latitude" />
            </Field>
            <Field id="loc-lon" label="Longitude">
              <input value={lon} onChange={(e) => setLon(e.target.value)} aria-label="Longitude" />
            </Field>
            <Field id="loc-function" label="Function">
              <select value={fn} onChange={(e) => setFn(e.target.value)} aria-label="Function">
                <option value="collection_point">collection_point</option>
                <option value="transfer_point">transfer_point</option>
                <option value="hub">hub</option>
                <option value="laboratory">laboratory</option>
              </select>
            </Field>
          </div>
          <div className="actions">
            <button type="button" className="primary" onClick={createLocation}>
              Create location
            </button>
          </div>
          {msg && <div className="msg">{msg}</div>}
        </div>
      )}
      <div className="card">
        <h2>Locations</h2>
        <table>
          <thead>
            <tr>
              <th>Name</th>
              <th>Active</th>
              <th>Functions</th>
              <th>Capacity</th>
              <th></th>
            </tr>
          </thead>
          <tbody>
            {opsLocs.map((l) => (
              <tr key={l.locationId}>
                <td>{l.name}</td>
                <td>{String(l.active)}</td>
                <td>
                  {Object.entries(l.functions || {})
                    .filter(([, v]) => v)
                    .map(([k]) => k)
                    .join(', ')}
                </td>
                <td>
                  {l.capacity
                    ? `${l.capacity.availableUnits}/${l.capacity.capacityUnits} (cooled ${l.capacity.cooledAvailableUnits}/${l.capacity.cooledCapacityUnits})`
                    : '—'}
                </td>
                <td>
                  {(activeRole === 'administrator' || activeRole === 'dispatcher') && (
                    <button type="button" onClick={() => toggleActive(l)}>
                      {l.active ? 'Deactivate' : 'Activate'}
                    </button>
                  )}
                </td>
              </tr>
            ))}
            {!opsLocs.length && (
              <tr>
                <td colSpan={5} className="muted">
                  No locations loaded (need dispatcher/admin operations view)
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  )
}

