#!/usr/bin/env python3
"""Broad smoke coverage of contract endpoints against a running server."""
import json, time, urllib.request, urllib.error, uuid
from datetime import datetime, timedelta, timezone

BASE = "http://127.0.0.1:8080"
errs = []
oks = []

def req(method, path, body=None, token=None, expect=None, label=None):
    url = BASE + path
    data = None
    headers = {"Content-Type": "application/json", "Accept": "application/json"}
    if token:
        headers["Authorization"] = f"Bearer {token}"
    if body is not None:
        data = json.dumps(body).encode()
    r = urllib.request.Request(url, data=data, headers=headers, method=method)
    try:
        with urllib.request.urlopen(r, timeout=30) as resp:
            raw = resp.read().decode()
            code = resp.status
            try:
                j = json.loads(raw) if raw else {}
            except Exception:
                j = {"_raw": raw}
    except urllib.error.HTTPError as e:
        code = e.code
        raw = e.read().decode()
        try:
            j = json.loads(raw) if raw else {}
        except Exception:
            j = {"_raw": raw}
    tag = label or f"{method} {path}"
    ok = True
    if expect is not None:
        if isinstance(expect, (list, tuple, set)):
            ok = code in expect
        else:
            ok = code == expect
    if ok:
        oks.append(f"OK {tag} {code}")
        print(f"OK {tag} {code}")
    else:
        errs.append(f"FAIL {tag} got {code} body={str(j)[:300]}")
        print(f"FAIL {tag} got {code} body={str(j)[:300]}")
    return code, j

def data(j):
    return j.get("data", j)

def now_iso(delta_h=0):
    return (datetime.now(timezone.utc) + timedelta(hours=delta_h)).strftime("%Y-%m-%dT%H:%M:%SZ")

def main():
    # ready
    req("GET", "/ready", expect=200)

    # login admin
    code, j = req("POST", "/api/authenticate-user",
                  {"username": "admin", "password": "Admin123!"}, expect=200)
    admin_tok = data(j).get("accessToken") or data(j).get("token")
    assert admin_tok, j

    code, boot = req("GET", "/api/ui/bootstrap", token=admin_tok, expect=200)
    boot_d = data(boot)
    sample_types = boot_d.get("sampleTypes") or []
    if not sample_types:
        # try ops state
        code, ops = req("POST", "/api/read-operations-state", {}, token=admin_tok, expect=[200, 201])
        print("ops keys", list(data(ops).keys())[:20] if isinstance(data(ops), dict) else data(ops))

    # list sample types via bootstrap or DB through create if needed
    # get amber type
    amber = None
    for st in sample_types:
        if st.get("name") == "Amber":
            amber = st
            break
    if not amber and sample_types:
        amber = sample_types[0]
    if not amber:
        # fetch via serviceability needs id - create dummy read by querying via create sample type later
        pass

    # select role
    req("POST", "/api/select-active-role", {"role": "administrator"}, token=admin_tok, expect=[200, 201])

    # create users
    suf = str(int(time.time()) % 100000)
    users = {}
    for uname, roles, quals, loc_key in [
        (f"req_{suf}", ["requester"], [], None),
        (f"col_{suf}", ["collection_professional"], ["Amber", "Indigo", "Frost", "Pulse"], None),
        (f"cou_{suf}", ["delivery_partner"], [], None),
        (f"node_{suf}", ["node_handler"], [], "node"),
        (f"lab_{suf}", ["laboratory_team"], [], "lab"),
        (f"disp_{suf}", ["dispatcher"], [], None),
    ]:
        body = {
            "username": uname,
            "initialPassword": "Pass123!",
            "fullName": uname,
            "email": f"{uname}@ex.com",
            "roles": roles,
            "qualifications": quals,
            "certifications": [{"code": q, "active": True} for q in quals],
            "active": True,
        }
        users[uname] = body

    # need location ids from ops
    code, ops = req("POST", "/api/read-operations-state", {}, token=admin_tok, expect=[200, 201])
    ops_d = data(ops)
    locs = ops_d.get("locations") or ops_d.get("nodes") or []
    print("ops top keys", list(ops_d.keys()) if isinstance(ops_d, dict) else type(ops_d))
    print("n locations", len(locs) if isinstance(locs, list) else locs)

    coll_node = None
    lab_node = None
    hub = None
    for loc in locs if isinstance(locs, list) else []:
        fn = loc.get("functions") or {}
        if fn.get("collectionPoint") or fn.get("collection"):
            coll_node = loc
        if fn.get("laboratory"):
            lab_node = loc
        if fn.get("hub") or fn.get("transferPoint"):
            hub = loc
    print("coll", coll_node and coll_node.get("locationId"), "lab", lab_node and lab_node.get("locationId"))

    # sample types from ops
    sts = ops_d.get("sampleTypes") or sample_types or []
    for st in sts:
        if st.get("name") == "Amber":
            amber = st
    if not amber and sts:
        amber = sts[0]
    print("amber", amber)

    # assign node/lab workers
    for uname, body in list(users.items()):
        if "node_handler" in body["roles"] and coll_node:
            body["assignedLocationId"] = coll_node.get("locationId") or coll_node.get("id")
        if "laboratory_team" in body["roles"] and lab_node:
            body["assignedLocationId"] = lab_node.get("locationId") or lab_node.get("id")
        code, j = req("POST", "/api/create-user", body, token=admin_tok, expect=[201, 200, 409])
        users[uname]["id"] = data(j).get("userId")
        print("created", uname, users[uname].get("id"))

    # set availability for workers
    for uname in users:
        uid = users[uname].get("id")
        if not uid:
            continue
        if any(r in users[uname]["roles"] for r in ("collection_professional", "delivery_partner", "node_handler", "laboratory_team")):
            req("POST", "/api/set-worker-availability",
                {"workerId": uid, "available": True, "capacityUnits": 5},
                token=admin_tok, expect=[200, 201])

    # read user
    if users[f"req_{suf}"].get("id"):
        req("GET", f"/api/read-user/{users[f'req_{suf}']['id']}", token=admin_tok, expect=200)

    # update user access
    if users[f"disp_{suf}"].get("id"):
        req("POST", "/api/update-user-access", {
            "userId": users[f"disp_{suf}"]["id"],
            "roles": ["dispatcher", "requester"],
            "active": True,
            "qualifications": [],
            "certifications": [],
        }, token=admin_tok, expect=[200, 201])

    # create sample type
    code, j = req("POST", "/api/create-sample-type", {
        "name": f"Custom_{suf}",
        "qualifiedCollectorRequired": True,
        "requiredQualification": "Amber",
        "containerType": "standard",
        "temperatureMinC": 2,
        "temperatureMaxC": 8,
        "incompatibleSampleTypes": [],
        "requiresCooledRoute": False,
        "batchingAllowed": True,
    }, token=admin_tok, expect=[201, 200, 409, 400])
    custom_st = data(j).get("sampleTypeId") or data(j).get("id")

    if custom_st:
        req("POST", "/api/update-sample-type", {
            "sampleTypeId": custom_st,
            "name": f"Custom_{suf}_v2",
            "containerType": "standard",
            "temperatureMinC": 2,
            "temperatureMaxC": 10,
            "qualifiedCollectorRequired": True,
            "requiredQualification": "Amber",
            "incompatibleSampleTypes": [],
            "requiresCooledRoute": False,
            "batchingAllowed": True,
        }, token=admin_tok, expect=[200, 201, 400])

    # create location
    code, j = req("POST", "/api/create-location", {
        "name": f"TestNode_{suf}",
        "coordinate": {"latitude": 12.98, "longitude": 77.60},
        "functions": {"collectionPoint": True, "transferPoint": True, "hub": False, "laboratory": False},
        "active": True,
        "handlingMinutes": 10,
        "regularCapacity": 20,
        "cooledCapacity": 5,
    }, token=admin_tok, expect=[201, 200, 400])
    new_loc = data(j).get("locationId") or data(j).get("id")
    print("new_loc", new_loc, j)

    if new_loc:
        req("POST", "/api/update-location", {
            "locationId": new_loc,
            "name": f"TestNode_{suf}_u",
            "coordinate": {"latitude": 12.981, "longitude": 77.601},
            "functions": {"collectionPoint": True, "transferPoint": True, "hub": False, "laboratory": False},
            "active": True,
            "handlingMinutes": 12,
        }, token=admin_tok, expect=[200, 201, 400])
        req("POST", "/api/set-location-status", {
            "locationId": new_loc,
            "active": True,
        }, token=admin_tok, expect=[200, 201, 400])
        req("POST", "/api/set-location-function-status", {
            "locationId": new_loc,
            "function": "collectionPoint",
            "active": True,
        }, token=admin_tok, expect=[200, 201, 400])
        req("POST", "/api/configure-capacity", {
            "targetType": "location",
            "targetId": new_loc,
            "regularCapacity": 25,
            "cooledCapacity": 8,
        }, token=admin_tok, expect=[200, 201, 400])

    # connection between coll and lab if possible
    if coll_node and lab_node:
        c_from = coll_node.get("locationId") or coll_node.get("id")
        c_to = lab_node.get("locationId") or lab_node.get("id")
        code, j = req("POST", "/api/create-connection", {
            "fromLocationId": c_from,
            "toLocationId": new_loc or c_to,
            "travelMinutes": 25,
            "active": True,
            "regularCapacity": 10,
            "cooledCapacity": 4,
            "bidirectional": True,
        }, token=admin_tok, expect=[201, 200, 400, 409])
        conn_id = data(j).get("connectionId") or data(j).get("id")
        print("conn", conn_id)
        if conn_id:
            req("POST", "/api/set-connection-status", {
                "connectionId": conn_id,
                "active": True,
            }, token=admin_tok, expect=[200, 201, 400])
            req("POST", "/api/configure-capacity", {
                "targetType": "connection",
                "targetId": conn_id,
                "regularCapacity": 12,
                "cooledCapacity": 5,
            }, token=admin_tok, expect=[200, 201, 400])

    if lab_node and amber:
        req("POST", "/api/configure-laboratory-acceptance", {
            "laboratoryId": lab_node.get("locationId") or lab_node.get("id"),
            "sampleTypeId": amber.get("sampleTypeId") or amber.get("id"),
            "accepts": True,
        }, token=admin_tok, expect=[200, 201, 400])

    # serviceability snapshot
    req("POST", "/api/read-serviceability-snapshot", {}, token=admin_tok, expect=[200, 201])

    # requester flow
    code, j = req("POST", "/api/authenticate-user",
                  {"username": f"req_{suf}", "password": "Pass123!"}, expect=200)
    req_tok = data(j).get("accessToken") or data(j).get("token")
    req("POST", "/api/select-active-role", {"role": "requester"}, token=req_tok, expect=[200, 201])

    origin = {"latitude": 12.97, "longitude": 77.59}
    st_id = (amber or {}).get("sampleTypeId") or (amber or {}).get("id")
    if not st_id:
        print("NO SAMPLE TYPE - abort journey portion")
    else:
        code, j = req("POST", "/api/check-serviceability", {
            "origin": origin,
            "originType": "home",
            "sampleTypeId": st_id,
            "requestedAt": now_iso(),
            "deliveryDeadline": now_iso(8),
            "earliestCollectionAt": now_iso(),
            "latestCollectionAt": now_iso(3),
        }, token=req_tok, expect=[200, 201])
        print("serviceable", data(j))

        code, j = req("POST", "/api/create-collection-request", {
            "origin": origin,
            "originType": "home",
            "requestedAt": now_iso(),
            "deliveryDeadline": now_iso(8),
            "earliestCollectionAt": now_iso(),
            "latestCollectionAt": now_iso(3),
            "sampleTypeId": st_id,
            "containerType": amber.get("containerType") or "standard",
            "temperatureMinC": amber.get("temperatureMinC", 2),
            "temperatureMaxC": amber.get("temperatureMaxC", 25),
            "idempotencyKey": str(uuid.uuid4()),
        }, token=req_tok, expect=[201, 200])
        sample_id = data(j).get("sampleId")
        print("sample", sample_id, "keys", list(data(j).keys()))
        journey_id = data(j).get("journeyId") or data(j).get("activeJourneyId")
        asg_ids = data(j).get("assignmentIds") or []

        if sample_id:
            req("GET", f"/api/read-sample-state/{sample_id}", token=req_tok, expect=200)
            req("POST", "/api/read-sample-lifecycle", {"sampleId": sample_id}, token=req_tok, expect=[200, 201])

        # collector
        code, j = req("POST", "/api/authenticate-user",
                      {"username": f"col_{suf}", "password": "Pass123!"}, expect=200)
        col_tok = data(j).get("accessToken") or data(j).get("token")
        req("POST", "/api/select-active-role", {"role": "collection_professional"}, token=col_tok, expect=[200, 201])
        code, j = req("POST", "/api/list-role-work", {}, token=col_tok, expect=[200, 201])
        work = data(j)
        pending = work.get("pending") or work.get("offered") or []
        print("collector pending", pending)
        col_asg = None
        for item in pending:
            if item.get("kind") == "collection" or item.get("status") in ("offered", "pending"):
                col_asg = item.get("assignmentId")
                break
        if not col_asg and asg_ids:
            col_asg = asg_ids[0]

        if col_asg:
            # decline then re-offer path: create second sample? skip for main path
            req("POST", "/api/accept-assignment", {
                "assignmentId": col_asg,
                "idempotencyKey": str(uuid.uuid4()),
            }, token=col_tok, expect=[201, 200, 409])
            req("POST", "/api/collect-and-seal-sample", {
                "assignmentId": col_asg,
                "sampleId": sample_id,
                "containerType": amber.get("containerType") or "standard",
                "temperatureC": 5,
                "sealedAt": now_iso(),
                "coordinate": origin,
                "idempotencyKey": str(uuid.uuid4()),
            }, token=col_tok, expect=[201, 200, 400])
            req("POST", "/api/record-handling-checkpoint", {
                "sampleId": sample_id,
                "assignmentId": col_asg,
                "containerType": amber.get("containerType") or "standard",
                "observedTemperatureC": 5,
                "recordedAt": now_iso(),
                "idempotencyKey": str(uuid.uuid4()),
            }, token=col_tok, expect=[200, 201, 400])

        # courier
        code, j = req("POST", "/api/authenticate-user",
                      {"username": f"cou_{suf}", "password": "Pass123!"}, expect=200)
        cou_tok = data(j).get("accessToken") or data(j).get("token")
        req("POST", "/api/select-active-role", {"role": "delivery_partner"}, token=cou_tok, expect=[200, 201])
        code, j = req("POST", "/api/list-role-work", {}, token=cou_tok, expect=[200, 201])
        work = data(j)
        pending = work.get("pending") or []
        print("courier pending", pending)
        transport_asg = None
        for item in pending:
            if item.get("kind") == "transport":
                transport_asg = item.get("assignmentId")
                break
        lab_asg = None
        if journey_id:
            code, j = req("POST", "/api/read-journey-plan", {"journeyId": journey_id}, token=admin_tok, expect=[200, 201])
            plan = data(j)
            print("plan keys", list(plan.keys()) if isinstance(plan, dict) else plan)
            legs = plan.get("assignments") or plan.get("legs") or []
            for leg in legs:
                if leg.get("kind") == "transport" and leg.get("status") in ("offered", "pending", "accepted", "in_progress"):
                    transport_asg = transport_asg or leg.get("assignmentId") or leg.get("id")
                if leg.get("kind") == "laboratory":
                    lab_asg = leg.get("assignmentId") or leg.get("id")

        if transport_asg:
            req("POST", "/api/accept-assignment", {
                "assignmentId": transport_asg,
                "idempotencyKey": str(uuid.uuid4()),
