func (a *App) getSample(ctx context.Context, id string) (*models.Sample, error) {
        s := &models.Sample{}
        var inc []byte
        var originNode, holder, journey, target, received, handoff, exReason, exKind *string
        var sealedAt, receivedAt, locAt, exAt *time.Time
        var lat, lon *float64
        err := a.DB.Pool.QueryRow(ctx, `
                SELECT id, request_id, requester_id, origin_lat, origin_lon, origin_type, origin_node_id,
                        requested_at, delivery_deadline, earliest_collection_at, latest_collection_at,
                        sample_type_id, container_type, temperature_min_c, temperature_max_c, incompatible_sample_types,
                        serviceability, serviceability_reason, status, sealed, sealed_at, already_sealed,
                        current_holder_id, active_journey_id, target_laboratory_id, received_laboratory_id, received_at,
                        latest_lat, latest_lon, location_recorded_at, pending_handoff_id,
                        exception_reason, exception_at, exception_kind, created_at
                FROM samples WHERE id=$1 OR request_id=$1`, id).Scan(
                &s.ID, &s.RequestID, &s.RequesterID, &s.Origin.Latitude, &s.Origin.Longitude, &s.OriginType, &originNode,
                &s.RequestedAt, &s.DeliveryDeadline, &s.EarliestCollectionAt, &s.LatestCollectionAt,
                &s.SampleTypeID, &s.ContainerType, &s.TemperatureMinC, &s.TemperatureMaxC, &inc,
                &s.Serviceability, &s.ServiceabilityReason, &s.Status, &s.Sealed, &sealedAt, &s.AlreadySealed,
                &holder, &journey, &target, &received, &receivedAt,
                &lat, &lon, &locAt, &handoff,
                &exReason, &exAt, &exKind, &s.CreatedAt,
        )
        if err != nil {
                return nil, err
        }
        s.OriginNodeID = originNode
        s.CurrentHolderID = holder
        s.ActiveJourneyID = journey
        s.TargetLaboratoryID = target
        s.ReceivedLaboratoryID = received
        s.ReceivedAt = receivedAt
        s.SealedAt = sealedAt
        s.LatestLat = lat
        s.LatestLon = lon
        s.LocationRecordedAt = locAt
        s.PendingHandoffID = handoff
        s.ExceptionReason = exReason
        s.ExceptionAt = exAt
        s.ExceptionKind = exKind
        s.IncompatibleSampleTypes = FromJSON[[]string](inc)
        if s.IncompatibleSampleTypes == nil {
                s.IncompatibleSampleTypes = []string{}
        }
        return s, nil
}

func (a *App) locationStale(s *models.Sample) bool {
        if s.LocationRecordedAt == nil {
                return true
        }
        return time.Since(*s.LocationRecordedAt) > time.Duration(a.Cfg.LocationStaleSec)*time.Second
}

func (a *App) activeAssignmentIDs(ctx context.Context, sampleID string) []string {
        rows, err := a.DB.Pool.Query(ctx, `
                SELECT id FROM assignments WHERE sample_id=$1 AND status IN ('offered','accepted','in_progress','pending')
                ORDER BY sequence, created_at`, sampleID)
        if err != nil {
                return []string{}
        }
        defer rows.Close()
        var out []string
        for rows.Next() {
                var id string
                _ = rows.Scan(&id)
                out = append(out, id)
        }
        if out == nil {
                out = []string{}
        }
        return out
}

func (a *App) sampleStateJSON(ctx context.Context, s *models.Sample) map[string]interface{} {
        timeline, _ := a.getTimeline(ctx, "sample", s.ID)
        tl := make([]map[string]interface{}, 0, len(timeline))
        for _, e := range timeline {
                tl = append(tl, map[string]interface{}{
                        "eventId": e.EventID, "action": e.Action, "actorId": e.ActorID, "role": e.Role,
                        "entityType": e.EntityType, "entityId": e.EntityID, "success": e.Success,
                        "occurredAt": FormatTime(e.OccurredAt), "details": e.Details,
                })
        }
        out := map[string]interface{}{
                "sampleId":                s.ID,
                "requestId":               s.RequestID,
                "requesterId":             s.RequesterID,
                "origin":                  s.Origin,
                "originType":              s.OriginType,
                "requestedAt":             FormatTime(s.RequestedAt),
                "deliveryDeadline":        FormatTime(s.DeliveryDeadline),
                "sampleTypeId":            s.SampleTypeID,
                "containerType":           s.ContainerType,
                "temperatureMinC":         s.TemperatureMinC,
                "temperatureMaxC":         s.TemperatureMaxC,
                "incompatibleSampleTypes": s.IncompatibleSampleTypes,
                "serviceability":          s.Serviceability,
                "activeAssignmentIds":     a.activeAssignmentIDs(ctx, s.ID),
                "state":                   map[string]interface{}{"status": s.Status},
                "timeline":                tl,
                "locationStale":           a.locationStale(s),
        }
        if s.ActiveJourneyID != nil {
                out["activeJourneyId"] = *s.ActiveJourneyID
        }
        if s.TargetLaboratoryID != nil {
                out["targetLaboratoryId"] = *s.TargetLaboratoryID
        }
        if s.LatestLat != nil && s.LatestLon != nil {
                out["latestLocation"] = models.Coordinate{Latitude: *s.LatestLat, Longitude: *s.LatestLon}
        }
        if s.LocationRecordedAt != nil {
                out["locationRecordedAt"] = FormatTime(*s.LocationRecordedAt)
        }
        return out
}

func (a *App) sampleLifecycleJSON(ctx context.Context, s *models.Sample) map[string]interface{} {
        timeline, _ := a.getTimeline(ctx, "sample", s.ID)
        tl := make([]map[string]interface{}, 0, len(timeline))
        for _, e := range timeline {
                tl = append(tl, map[string]interface{}{
                        "eventId": e.EventID, "action": e.Action, "actorId": e.ActorID, "role": e.Role,
                        "entityType": e.EntityType, "entityId": e.EntityID, "success": e.Success,
                        "occurredAt": FormatTime(e.OccurredAt), "details": e.Details,
                })
        }
        completed := []string{}
        rows, err := a.DB.Pool.Query(ctx, `
                SELECT id FROM assignments WHERE sample_id=$1 AND status='completed' ORDER BY sequence`, s.ID)
        if err == nil {
                defer rows.Close()
                for rows.Next() {
                        var id string
                        _ = rows.Scan(&id)
                        completed = append(completed, id)
                }
        }
        replacements := []string{}
        if s.ActiveJourneyID != nil {
                rows2, err := a.DB.Pool.Query(ctx, `
                        SELECT id FROM journeys WHERE parent_journey_id=$1 AND status IN ('planned','active')`, *s.ActiveJourneyID)
                if err == nil {
                        defer rows2.Close()
                        for rows2.Next() {
                                var id string
                                _ = rows2.Scan(&id)
                                replacements = append(replacements, id)
                        }
                }
        }
        out := map[string]interface{}{
                "sampleId":                 s.ID,
                "status":                   s.Status,
                "sealed":                   s.Sealed,
                "completedLegIds":          completed,
                "activeReplacementPlanIds": replacements,
                "timeline":                 tl,
                "locationStale":            a.locationStale(s),
        }
        if s.ActiveJourneyID != nil {
                out["activeJourneyId"] = *s.ActiveJourneyID
        }
        if s.CurrentHolderID != nil {
                out["currentHolderId"] = *s.CurrentHolderID
        }
        if s.ReceivedLaboratoryID != nil {
                out["receivedLaboratoryId"] = *s.ReceivedLaboratoryID
        }
        if s.ExceptionReason != nil {
                ex := map[string]interface{}{"reason": *s.ExceptionReason}
                if s.ExceptionKind != nil {
                        ex["kind"] = *s.ExceptionKind
                }
                if s.ExceptionAt != nil {
                        ex["at"] = FormatTime(*s.ExceptionAt)
                }
                out["exception"] = ex
        }
        if s.PendingHandoffID != nil {
                out["pendingHandoffId"] = *s.PendingHandoffID
        }
        if s.LatestLat != nil && s.LatestLon != nil {
                out["latestLocation"] = models.Coordinate{Latitude: *s.LatestLat, Longitude: *s.LatestLon}
        }
        if s.LocationRecordedAt != nil {
                out["locationRecordedAt"] = FormatTime(*s.LocationRecordedAt)
        }
        return out
}

