	s, me, err := a.requireRole(r.Context(), models.RoleLaboratoryTeam, models.RoleAdministrator)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req struct {
		AssignmentID   string `json:"assignmentId"`
		SampleID       string `json:"sampleId"`
		LaboratoryID   string `json:"laboratoryId"`
		ReceivedAt     string `json:"receivedAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if err := decode(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	if req.SampleID == "" {
		writeErr(w, badRequest("invalid_json", "sampleId required"))
		return
	}
	if req.IdempotencyKey != "" {
		if cached, ok := a.checkIdempotency(r.Context(), s.UserID, "confirm_laboratory_receipt", req.IdempotencyKey); ok {
			writeData(w, 200, cached)
			return
		}
	}
	sample, err := a.getSample(r.Context(), req.SampleID)
	if err != nil {
		writeErr(w, notFound())
		return
	}
	var asg *models.Assignment
	if req.AssignmentID != "" {
		asg, err = a.getAssignment(r.Context(), req.AssignmentID)
		if err != nil || asg.Kind != "laboratory" {
			writeErr(w, notFound())
			return
		}
	} else {
		var id string
		err = a.DB.Pool.QueryRow(r.Context(), `
			SELECT id FROM assignments WHERE sample_id=$1 AND kind='laboratory'
			AND status IN ('offered','accepted','in_progress','pending')
			ORDER BY sequence DESC LIMIT 1`, sample.ID).Scan(&id)
		if err == nil {
			asg, _ = a.getAssignment(r.Context(), id)
		}
	}
	if asg != nil && asg.WorkerID != nil && *asg.WorkerID != me.ID {
		if s.ActiveRole != models.RoleAdministrator {
			ok := false
			if me.AssignedLocationID != nil {
				if req.LaboratoryID != "" && *me.AssignedLocationID == req.LaboratoryID {
					ok = true
				}
				if asg.LaboratoryID != nil && *me.AssignedLocationID == *asg.LaboratoryID {
					ok = true
				}
				if sample.TargetLaboratoryID != nil && *me.AssignedLocationID == *sample.TargetLaboratoryID {
					ok = true
				}
			}
			if !ok {
				writeErr(w, httpapi.ErrForbidden)
				return
			}
		}
	} else if asg == nil && s.ActiveRole != models.RoleAdministrator {
		// no assignment yet — require assignment to the laboratory
		ok := me.AssignedLocationID != nil && req.LaboratoryID != "" && *me.AssignedLocationID == req.LaboratoryID
		if !ok && me.AssignedLocationID != nil && sample.TargetLaboratoryID != nil {
			ok = *me.AssignedLocationID == *sample.TargetLaboratoryID
		}
		if !ok {
			writeErr(w, httpapi.ErrForbidden)
			return
		}
	}
	now := Now()
	if req.ReceivedAt != "" {
		if t, e := ParseTime(req.ReceivedAt); e == nil {
			now = t
		}
	}
	labID := req.LaboratoryID
	if labID == "" && asg != nil && asg.LaboratoryID != nil {
		labID = *asg.LaboratoryID
	}
	if labID == "" && sample.TargetLaboratoryID != nil {
		labID = *sample.TargetLaboratoryID
	}
	if labID == "" {
		writeErr(w, badRequest("invalid_json", "laboratoryId required"))
		return
	}
	_, err = a.DB.Pool.Exec(r.Context(), `
		UPDATE samples SET status='received', received_laboratory_id=$1, received_at=$2,
			current_holder_id=$3, location_recorded_at=$2 WHERE id=$4`,
		labID, now, me.ID, sample.ID)
	if err != nil {
		writeErr(w, errInternal)
		return
	}
	if asg != nil {
		_, _ = a.DB.Pool.Exec(r.Context(), `UPDATE assignments SET status='completed', completed_at=$1, worker_id=COALESCE(worker_id,$2) WHERE id=$3`, now, me.ID, asg.ID)
	}
	if sample.ActiveJourneyID != nil {
		_, _ = a.DB.Pool.Exec(r.Context(), `UPDATE journeys SET status='completed' WHERE id=$1`, *sample.ActiveJourneyID)
		_ = a.releaseCapacityForJourney(r.Context(), *sample.ActiveJourneyID)
	}
	a.audit(r.Context(), s.UserID, s.ActiveRole, "confirm_laboratory_receipt", "sample", sample.ID, true, nil)
	sample, _ = a.getSample(r.Context(), sample.ID)
	out := a.sampleLifecycleJSON(r.Context(), sample)
	if req.IdempotencyKey != "" {
		_ = a.saveIdempotency(r.Context(), s.UserID, "confirm_laboratory_receipt", req.IdempotencyKey, out)
	}
	writeData(w, 200, out)
}

